window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_025"]={"n":"黎民表","dyn":"明","poems":[{"t":"飞花曲","f":"七言古诗","c":["长安戚里竞春阳，桃李花开夹道傍。","遥裔鹤烟笼上苑，丰茸鸡树迩明光。","濯锦含霞非一色，刻翠施红映朝日。","同心并蒂引鸳雏，接叶交枝栖凤翼。","西第东邻望不迷，溶溶宛宛复凄凄。","歌残玉树飘成阵，曲罢山芗踏作泥。","婉态柔情分绰约，不与春光共销铄。","初拂交疏入绮窗，径度华池上青阁。","绮窗青阁盛佳人，二八蛾眉不解嚬。","红牙度曲梁尘起，银甲搊筝璧月新。","碧复云屏昼不开，莺啼燕语空徘徊。","慵妆未进雕胡饭，揽带方临玉镜台。","摘蕊扳条还自爱，睡起曾无一枝在。","愔愔迸泪乍停机，脉脉煎心翻解佩。","昔时烂漫空相惜，今日凋零竟何益。","宁知岁月损铅华，宁谓风光类弹射。","万事相看成转蓬，朝居裀褥暮尘中。","安陵坐弃前鱼泣，长信恒悲团扇风。","富贵荣华须及时，烹羊炮羔君莫辞。","清歌窈窕芙蓉帐，美酒蒲萄金屈卮。","高阳酒徒良不恶，执戟何如草《玄》乐。","谁肯低头拜七贵，谁能闭户穷三略。","莫叹飞花太薄情，可怜全盛易骄盈。","铜驼陌上荒荆棘，金爵台前漳水声。"]},{"t":"肖甫送至天雄故城因观宋大观五礼碑同赋","f":"七言古诗","c":["风吹古城势欲倒，征车北指燕山道。","道傍穹碑十丈馀，雨剥霜封卧青草。","我行拂拭开尘沙，良工独苦咸咨嗟。","婉丽似出虞秘监，廓落正类颜琅琊。","金薤离披立蛟鹄，赤手欲掣生龙蛇。","谁其能此宋令主，千载重操黑帝矩。","宫中才人捧砚立，殿前常侍登床取。","白麻宣诏赐天雄，署衔纸尾纷华虫。","雕镌琬琰勒黄绢，典雅尚有承平风。","可惜龟螭半斑剥，牧童烧焚牛砺角。","铜仙何日去咸阳，花石无踪寻艮岳。","停骖啜古不胜悲，况是邮亭把手时。","关门令尹逢迎处，更说羊公曾过之。"]},{"t":"遇张元春","f":"七言古诗","c":["侠斜日暮红尘里，扬鞭识是张公子。","春风大道控骅骝，明月西园醉桃李。","琅玕玉树媚眉姿，步上黄金未足奇。","诸生解作东山咏，才子邀吟辋口诗。","长裾懒作侯门客，挂帆归访专诸宅。","淋漓青壁满题名，牛衣胜卧长安陌。"]},{"t":"题黄山谷书黄龙禅师开堂疏","f":"七言古诗","c":["钟陵行押称第一，早岁已入兰亭室。","转运应知腕有神，掣颤尤工老来笔。","学诗唯许杜少陵，翰墨黄州乃其匹。","宋人岂解识真龙，天厩骅骝纵奔逸。","籍名党锢疾如仇，白首黔阳作系囚。","平生正得参禅力，万里危途百不忧。","黄龙老宿尔何子，槁目曾识东家丘。","相酬妙语千金直，能使芳名万古流。","擘窠何人勒翠琰，野火不肯焚银钩。","何年拓本来燕市，惨澹无人知满字。","金门久客逢休浣，北牖临风自粘缀。","发短谁知心尚长，侧釐尚望君王赐。"]},{"t":"粤台山怀古四首 其一","f":"五言律诗","c":["铜狄栖荒棘，珠衣没古蒿。","山回秦垒在，云出汉陵高。","大泽龙犹卧，深春鸟自号。","雄图将逝水，谁与较萧曹。"]},{"t":"粤台山怀古四首 其三","f":"五言律诗","c":["冷露沾瑶磶，凄风断翠华。","中原曾掎鹿，荒泽自鸣蛙。","涧古藏尧韭，岩幽偃舜花。","隆坻聊永叹，林薄振清笳。"]},{"t":"奉命至西山坟园 其二","f":"五言律诗","c":["宿草经春长，新阡近郭多。","彩销团扇粉，香尽舞衣罗。","陌上花如绮，云间月似蛾。","繁华今不见，遗恨雍门歌。"]},{"t":"游西山玉泉池","f":"五言律诗","c":["圆渟知异脉，方折纪灵踪。","濯月金规满，含风石镜融。","平湖隐作浪，曲涧泻为淙。","一入昆明去，千秋照绮栊。"]},{"t":"长门怨","f":"五言律诗","c":["永巷疏恩幸，长门绝履綦。","由来妾薄命，讵是妒蛾眉。","夜雨销兰气，秋风落桂枝。","凝思君不见，含态入罗帏。"]},{"t":"登鸡鸣寺 其一","f":"五言律诗","c":["宝地空香散，金绳觉路赊。","楼高碍白石，轩密秘青霞。","绿泣台城草，红悲辱井花。","江山今几劫，非独有恒沙。"]},{"t":"弹子矶","f":"五言律诗","c":["兹岭何绵亘，孤根下杳冥。","云光荡鸟背，水气杂龙腥。","蜀道攒为阁，庐山叠作屏。","定知人静后，风雨语精灵。"]},{"t":"铁泉庵","f":"五言律诗","c":["铁壁临千仞，乘危更一探。","瀑前安茗灶，松杪出花龛。","鹤忆窥残帙，猿经伴夜谈。","谁能开丈室，招隐向山南。"]},{"t":"泛石门溪","f":"五言律诗","c":["往来皆任兴，屡进石门溪。","雨气笼山浅，江云过鸟低。","稻田多汲竹，松火更蒸藜。","虽共渔翁宿，桃花路却迷。"]},{"t":"春夜同子鸣集少承馆","f":"五言律诗","c":["向夕衡门掩，吴中客子来。","长河翻月上，断柳逐风回。","小饮怜春尽，繁花受晚开。","汉关吾欲去，刻烛更徘徊。"]},{"t":"出塞曲送陈公聘使边 其一","f":"五言律诗","c":["骋望白狼间，追兵大漠闲。","黄河通月窟，青海入天山。","剖竹行秦垒，封泥守汉关。","豫知麟阁上，先候策勋还。"]},{"t":"夜集苏子川鸿胪宅命家僮作妓舞戏赠","f":"五言律诗","c":["曲房翻袖短，长带缀衣偏。","流盼光生电，回身急应弦。","雪飞从掌上，月堕在琴边。","萧飒清霜夜，求凰意悄然。"]},{"t":"盛仲交自金陵至集于乔舍人小园","f":"五言律诗","c":["坐荫凉云好，轻衣未觉寒。","月临花树午，春逼鸟声残。","满酌秦淮酒，新弹贡禹冠。","柳条时拂拭，浑作故人看。"]},{"t":"冬夜同张元易过顾叔潜得红字","f":"五言律诗","c":["枥马苦嘶风，徘徊恋竹丛。","寒声御沟水，月色建章宫。","小袖禁花艳，衰颜借酒红。","他年文字饮，能复忆城东。"]},{"t":"苏子川宅观芍药得枝字","f":"五言律诗","c":["为掩群芳色，开花独后时。","青扶承露蕊，红妥出阑枝。","绰约东邻子，风流郑国诗。","合欢还有恨，名字是将离。"]},{"t":"留都 其四","f":"五言律诗","c":["铜爵标霞外，金茎擢汉间。","祥基开白水，御苑跨黄山。","殿古宵钟彻，花深委佩闲。","苍苍后湖月，应载凤游还。"]},{"t":"留都 其八","f":"五言律诗","c":["幽蓟称岩甸，重襟亦在斯。","尚纡南顾策，数费北门师。","霜悴青苗尽，秋深赤羽驰。","谁能如贾谊，流涕向明时。"]},{"t":"祗事昭陵述感","f":"七言律诗","c":["日角常瞻御扇前，岂知人世有桑田。","金縢顾命留三相，玉辇升中已一年。","封似灞陵终用俭，衣留轩冢合成仙。","微臣握管恩偏重，痛彻龙髯上九天。"]},{"t":"阻风李阳驿","f":"七言律诗","c":["满目川原百战馀，旅情芳草共萧疏。","苍山古堠逢秋骑，野水残灯见夜渔。","地近潇湘多暮雨，雁来湓浦少乡书。","故人忆我停云外，惆怅烟波少定居。"]},{"t":"燕京书事 其五","f":"七言律诗","c":["朱楼迢递接平沙，叹息深闺有丽华。","青鸟几时随阿母，綵鸾今夜属良家。","桃栽碧海多成实，桂贮长门自落花。","寄语采桑南陌女，莫将颜色向人誇。"]},{"t":"祈谷斋居","f":"七言律诗","c":["铃索无声树色寒，集灵台上拜千官。","旌旗夜绕长杨陌，灯火春祠泰乙坛。","煖入芳郊阳气浅，月临青阁曙光残。","扬雄白首《玄经》在，谁捧云中玉露盘。"]},{"t":"癸亥十月书事 其三","f":"七言律诗","c":["汉家本自惜天骄，饮马年来到渭桥。","五夜将星明玉帐，七陵王气上丹霄。","军中选士皆穿札，幕府谋臣尽赐貂。","扈阁儒生惭献赋，燕然终拟勒岧峣。"]},{"t":"嬉春曲陈公载索和用韵 其二","f":"七言律诗","c":["芳草春阴垂钓矶，寒城斜日闪朱旗。","熏人欲醉怜花气，送客无情是柳丝。","画楫迥随兰浦入，金尊还傍竹阴移。","江湖十载浑疏放，空愧青楼半额眉。"]},{"t":"秋怀 其三","f":"七言律诗","c":["玉泉迢递入昆池，百尺阑干俯碧漪。","锦缆双维龙凤舸，雕楹深锁柏松枝。","侍臣鸣佩丹枫远，宫女临霞彩袖垂。","曾预都人誇盛事，周南今日叹衰迟。"]},{"t":"和顾汝和玉河见白燕 其一","f":"七言律诗","c":["杏花桃叶尽芳菲，曲水春风半掩扉。","玉羽乍窥池上影，霓裳如舞月中衣。","画梁多是无心绕，金屋谁同作伴飞。","回首凤笙云路杳，雕笼争道不如归。"]},{"t":"和顾汝和玉河见白燕 其二","f":"七言律诗","c":["曾是乌衣国里身，玉楼琼榭换丰神。","双飞剪出机中素，独立妆成掌上人。","月下步摇花有态，水边飘动袜生尘。","梁园词客难成赋，洛浦相逢总未真。"]},{"t":"戴金吾伯常招饮郑园","f":"七言律诗","c":["禁城秋色净无烟，碧水澄波带远天。","十里楼台通泰畤，五陵花木有平泉。","风摇柳浪低纨扇，日暮菱歌起钓船。","冰簟疏帘销暑地，流尘知不到尊前。"]},{"t":"宫词 其三","f":"七言绝句","c":["金屋无人奉属车，君王初诵上青书。","日长不用教歌舞，自绕琪坛学步虚。"]},{"t":"宫词 其四","f":"七言绝句","c":["未央楼殿敞秋风，芝火煌煌彻夜红。","知是骖鸾朝太乙，旌幢斜出五云中。"]},{"t":"宫词 其七","f":"七言绝句","c":["立残银漏未更衣，闻道龙池驻翠騑。","卫士夜深传画烛，御街尘起侍臣归。"]},{"t":"豫章江行 其二","f":"七言绝句","c":["山磴崎岖猿夜号，溪流如沸石如刀。","刺桐花下思归客，待得天明有二毛。"]},{"t":"寒鸦图","f":"七言绝句","c":["寒山寂历野苍苍，绕树惊飞不断行。","画角一声天欲曙，金河翻落满城霜。"]},{"t":"寄题潘少承西樵山房","f":"七言绝句","c":["新营丹室铁泉山，千树梅花不共攀。","夜夜京华成短梦，白云红叶屋三间。"]},{"t":"元夜曲 其一","f":"七言绝句","c":["束素施玄绀发光，暗尘偏逐越罗香。","内庭不放金莲炬，只恐蛾眉妒艳妆。"]},{"t":"元夜曲 其二","f":"七言绝句","c":["萧史乘鸾下帝台，参差仙盖拂云来。","分明禁苑春先到，万朵芙蓉月下开。"]},{"t":"题画为李宫詹子蕃 其二","f":"七言绝句","c":["武龙清斋太乙宫，上林舞处不春风。","遥知绛节随王母，青鸟飞来御苑中。"]},{"t":"赠张将军","f":"七言律诗","c":["之子江东旧隐沦，乍来惠我一杯莼。","常留白羽吟边月，不望朱衣座上春。","邂逅何辞邀笛醉，行藏空老据鞍身。","王朝执戟元无补，草阁耽玄岂异人。"]},{"t":"游仙六首 其一","f":"五言古诗","c":["我思忽不惬，藐然隘中区。","凌山度瑶碣，肃驾自云衢。","遨游清都阙，神猋吹我躯。","上帝垂藻旒，群后骖龙趋。","羡门进仙药，王乔授玉书。","餐和鍊真魄，精神游六虚。","自握无为宝，年寿安足虞。"]},{"t":"游仙六首 其二","f":"五言古诗","c":["濯足紫沂海，晞发朝阳阿。","云车载玉女，皓齿扬清歌。","参差丽霄汉，玉辚隐相和。","驾言憩玄圃，贻我琼树华。","光仪忽以逝，兹意成蹉跎。","岧岧阆风岑，汎汎蒙汜波。","仙才谅非偶，浩叹将如何。"]},{"t":"游仙六首 其三","f":"五言古诗","c":["烛龙衔奔景，倏忽归崦嵫。","思托浮丘子，高举乘云螭。","飘飖弭绛节，旖旎骖芝旗。","朝游昆崙丘，夕泳弱水湄。","奇龄等金石，桑榆安足悲。","夸父为邓林，但为俗所嗤。"]},{"t":"游仙六首 其四","f":"五言古诗","c":["山林非所托，所思在神州。","寓目八纮外，经过华池幽。","神光飒然至，青鸟从我游。","灵妃奉玉觞，清谣自相酬。","欢娱未终夕，曜灵不可留。","山川夐绵邈，白云良悠悠。","安得不死药，千载复来求。"]},{"t":"游仙六首 其五","f":"五言古诗","c":["长鲸鼓玄涛，巨鳌戴崇巘。","若华散馀晖，照曜金银殿。","流铃韵空歌，琼蕤倏如霰。","飘飘一水间，霞踪杳难见。","颓龄不可驻，流景疾蜚电。","喟彼蓬莱舟，伤哉柏梁宴。","谁能回日车，常令鬓不变。"]},{"t":"游仙六首 其六","f":"五言古诗","c":["淮南方好术，矫志栖云间。","金鉼汲素绠，宝鼎合神丹。","神丹资服食，白日生飞翰。","永随八公去，翱翔戏天端。","志大术良疏，功成虑亦殚。","连蜷丛桂树，翩翩留空山。","徒闻脱屣去，不见乘鸾还。"]},{"t":"咏怀二首 其一","f":"五言古诗","c":["佳人入我梦，华容渥如丹。","玉璜称姣服，扬辞吐馨兰。","接欢在须臾，寤言阻河山。","坐惜朱华改，空悲蕙草寒。","别离不可处，况乃玄律殚。"]},{"t":"咏怀二首 其二","f":"五言古诗","c":["肃肃高天鸿，冥飞慕俦侣。","岂无凝寒思，连翩自容与。","眷我平生怀，梯航限河渚。","块然守空堂，伊人自豪举。","揽桂聊淹留，折麻空延伫。","道远多风霜，岁晏多思虑。","光仪恒不忘，何异渴琼树。"]},{"t":"邯郸才人嫁为厮养卒妇","f":"五言古诗","c":["淹泪辞玉阶，含悽下瑶殿。","今日叹离居，夙昔欢同辇。","兰蕙自有芳，蘼芜固所贱。","淅淅西北风，吹我秋田蓬。","夜梦邯郸路，不识邯郸宫。","王颜会销歇，君恩那得终。"]},{"t":"出郭十里望白云","f":"五言古诗","c":["伊余霞外心，夙协沧洲想。","芳春戒簪朋，青溪肃徂两。","瀰瀰清露漙，英英白云上。","旭日熹阳厓，暄风散林莽。","栈道既萦纡，窥川亦沆瀁。","干吕气多奇，建木影殊状。","陟云脰已捐，览胜心逾壮。","玄圃非冥设，丹丘岂外象。","愿矫凌风翰，永恣山泉赏。"]},{"t":"僧归亭故址望栖霞寺临观黄太史精舍","f":"五言古诗","c":["青丘未云陟，磴道方邅回。","烟霞迹以怆，谁见化人开。","雕甍翼云外，玄构隐岩隈。","中有蕴真士，雅负凌云才。","汲古浩津梁，蓄宝富玟瑰。","奇文釐七略，玄象正三阶。","薄游沂水服，屡举河朔杯。","缁尘一以隔，岁月缅悠哉。","空馀云卧地，萧飒松风来。","有怀谅难已，愿假征鸿裁。"]},{"t":"登白云最高顶","f":"五言古诗","c":["灵岳奠南隩，凤翼矫而跱。","上干烛斗枢，下盘绝地理。","脩阪饶莃苓，回蹊荫楩梓。","东观极扶木，西窥逼濛汜。","晨标赪霞截，夜气白虹起。","玉树发葱青，金潭耿清泚。","平生信经奇，兹山擅巨美。","图史谩莫传，倜傥固难纪。","倘骖飞龙游，长揖当途子。"]},{"t":"入白云寺酌九泉","f":"五言古诗","c":["顿足云外游，弭服云中宇。","晨霞朗高木，晴晖射孤屿。","泠泠山漱琼，湛湛觞浮羽。","层栏蚀金碧，古瓦窜鼯鼠。","抚迹泯空有，忘怀契宾主。","手揭留荑赠，目送飞鸿举。","方谐鸾鹤踪，遽协濠梁矩。","齐物在斯辰，忧生非远虑。"]},{"t":"溯水帘洞过月溪寺","f":"五言古诗","c":["缘蹊路方涩，寻异景屡延。","凝思瞩幽岩，朗咏溯长川。","青莲敞妙界，璧月鉴华泉。","宝树无重影，金轮不复圆。","依微想台榭，出没怅云烟。","羽人绝髣髴，员峤徒空筌。","归寂竟何感，抚化弥泫然。","六龙倘可顿，为我挥虞渊。"]},{"t":"鹤舒台是安期上升处","f":"五言古诗","c":["安期鍊玉液，飞步凌紫霄。","空馀璇台在，千古郁岧峣。","金床锁灵穴，碧树敷英翘。","鸾笙空缥缈，鹤驭徒逍遥。","物化迹逾胜，理惬境自超。","愿弭云中驾，随君挥碧寥。"]},{"t":"虎头岩","f":"五言古诗","c":["松径光未黯，赏心讵云释。","揽胜陟崇崖，褰衣履危石。","云构方蒙茸，乳窦正淅沥。","险逾吕梁壑，崭异天井壁。","仰接惊猱栖，俯视飞鸟迹。","绿帙昼常扃，丹光夜逾赩。","杳杳曛烟生，澴澴冬霰积。","功非夸娥掉，奇假巨灵擘。","栖真事岩耕，倩尔飞凫舄。"]},{"t":"送何于逊游衡岳三首 其一","f":"五言古诗","c":["朱陵郁佳丽，真气雄哉纷。","华芝翳凤盖，空香飘鹤群。","羽衣何婀娜，行逢魏元君。","手掇金明草，口诵青苔文。","玄言屡敷析，刀圭时见分。","猋轮香难即，回身入青云。","流铃歌未歇，陵苕尚氤氲。","倘揖当途子，相期凌紫氛。"]},{"t":"送何于逊游衡岳三首 其二","f":"五言古诗","c":["神皋钟火德，名岳奠坤维。","岂伊灊霍俦，聪明谅在兹。","登封表崇壝，肃事展灵祇。","欹厓结衡宇，回阿荫桂旗。","卿云出扣阈，郎月流琐扉。","玉童夜击鼓，祠官朝祝釐。","触石散膏壤，生贤翊昌期。","理冥信莫测，迹贲良可窥。","蹇余俗士驾，何时骖赤螭。","晨登岣嵝岑，旷望弥赤县。","坰服引昭丘，襟带穷楚甸。","五峰郁游龙，三湘皎澄练。","礧砢矫以虔，云霞蔼而变。","尚想卢敖游，应蔑海若见。","尚子愿终毕，伯昏险可践。","夙昔经奇心，兹焉慰遐眷。"]},{"t":"送何于逊游衡岳三首 其三","f":"五言古诗","c":["姒皇昔导江，翻然感玄夷。","奇文镂金简，夭矫鸾凤披。","灵踪閟草莽，神功播无涯。","彼美昌黎子，千秋乃来仪。","精诚迪穷昊，白日回阴霏。","镵厓纪大雅，逸韵凌云飞。","钦圣有逸轨，怀贤注遥思。","慎矣涉脩路，跂尔琼树枝。"]},{"t":"送何乔仲赴阙四首 其一","f":"五言古诗","c":["招摇有桂树，结根南海湄。","蒙茏度霜霰，皎洁常不移。","以兹孤直性，贡之白玉墀。","春风被兰茝，荣耀同一时。","虽有艳阳质，比君璚树枝。","明堂备榱桷，海寓瞻巍巍。","丹青洵云美，玄素岂所睽。","无言愧桃李，幸得仰容辉。"]},{"t":"送何乔仲赴阙四首 其二","f":"五言古诗","c":["托养贲丘园，深衷媚泉石。","乘流纵归榜，登山望飞翼。","挥觞欣与同，啸咏忘昕夕。","讵云云雨乖，怅彼山川隔。","忘言昔所歆，投分贵不易。","龙蠖自有时，谁能效沮溺。"]},{"t":"送何乔仲赴阙四首 其三","f":"五言古诗","c":["驱车燕赵郊，道由介丘阳。","飘风起蓬藋，陵谷晦苍苍。","津梁浩千古，谁能测幽冥。","我犹局一隅，子今营四方。","翻飞无劲翮，蹇步愧同行。","安得皎日惠，愿言希末光。"]},{"t":"送何乔仲赴阙四首 其四","f":"五言古诗","c":["羽檄起边庭，夜火沉秋柝。","六月犹出师，连营亘沙漠。","虽收瀚海功，未极西山瘼。","丈夫徇国心，安能处其薄。","努力宣令猷，康屯运奇略。","卿云睹轮囷，欃枪见清廓。","马多却走馀，民有康衢乐。","王道喜清夷，书生守藜藿。"]},{"t":"园居杂兴二首 其一","f":"五言古诗","c":["时雨涤芳园，林皋薄暄燠。","微风捎池荷，轻云荫修竹。","怀人倦寝兴，褰裳展游瞩。","鯈鱼出深渊，蜚鸿渐高木。","云胡限欢赏，跬步成川陆。","琴心乱无绪，樵歌断复续。","缅彼濠上游，怅望清溪曲。","卜筑倘有期，从君蓺松竹。"]},{"t":"园居杂兴二首 其二","f":"五言古诗","c":["冲怀寄林壑，抱痾卧园庐。","诗书为我縳，一亩成丘墟。","清晨具农笠，命仆勤负锄。","新畦灌灵药，旧埒环嘉蔬。","兰生既盈亩，豆熟亦满车。","夜雨剪春韭，清霜登紫萸。","朋来可觞咏，安用烹神鱼。","食力古所贵，巢林诚足娱。","寄谢任公子，持纶安所如。"]},{"t":"晨起斋中读书二首 其一","f":"五言古诗","c":["息躬衡门下，游好在六经。","丘中列万木，风起皆金声。","山林有殊观，耳目无远营。","清晨屏荒翳，躧屣当前楹。","鸟耕思有岁，熊经希养生。","游心极罔象，顿足游大庭。","旷士恒抱朴，宵人若怀永。","或偶苏门啸，暂返南阳耕。","龙蠖本殊性，鹪鴳岂谐征。","兹乐庶不忘，烱然垂丹青。"]},{"t":"晨起斋中读书二首 其二","f":"五言古诗","c":["辞家适燕蓟，遥遥远行游。","怅兹云雨隔，忽复寒暑遒。","人生寓瀛海，安用怀百忧。","伊余困泥滓，有志仍丹丘。","临渊非钓国，巢林殊凿坏。","奔波冀回舳，骇路遄旋辀。","濠梁有逸矩，箕颍多清流。","仙夫杳难觌，妷女徒好修。","去矣从所欲，轩盖诚多尤。"]},{"t":"怀友诗","f":"五言古诗","c":["急景驰西汜，悲风起寒陆。","眷言心所思，缅邈林塘曲。","芙蓉为君衣，薜荔为君屋。","山巅思采苓，云中乃抱犊。","我欲往从之，道路阻且复。","宴坐恒屡迁，寤言复在目。","衾裯讵同御，椒兰徒盈握。","岁晚当归来，从君蓺松竹。"]},{"t":"送邝中伯北上二首 其一","f":"五言古诗","c":["扶南有奇士，雅志无与俦。","班荆翳环堵，被褐卧林丘。","手掇青琅玕，引领睇神州。","美人驰目成，逝将远行游。","阊阖启鸿运，缨弁宣灵猷。","舍我蓬门衣，披君紫绮裘。","挈壶有馀智，挥刃无全牛。","轩车岂云晚，邪径安足留。","居人易生思，客子常苦忧。","跂尔涉要路，知余怀阻修。"]},{"t":"送邝中伯北上二首 其二","f":"五言古诗","c":["征车何皇皇，念子如騑服。","严霜被中野，大气凄以肃。","我守衡门雌，子骋高衢足。","望望登君门，悠悠渐平陆。","献赋争光辉，夹毂相驰逐。","朝同楼护游，暮就主父宿。","时俗徇异同，明月袭鱼目。","去矣慎所投，慰我忘薖轴。"]},{"t":"同丁戊山人游白云寺","f":"五言古诗","c":["流观遍炎隩，结赏自员峤。","积阳熙层崖，凝阴豁林杪。","云构何厜㕒，乳窦自窈窕。","澒洞出谷云，渊渟瑩神沼。","稍疲暂憩石，选胜益跻表。","栏楯寄躨跜，轩窗瞰深窅。","猛簴发鸿音，宝轮晃馀照。","龛以昙花覆，阶将慧草绕。","讵谓劫灰馀，遂成夷原燎。","栋挠芝菌生，瓦圻鼪鼯啸。","金薤剥石幢，汞药遗丹铫。","惠远岂复招，巫阳不可叫。","萧晨命良俦，兰觞展奇眺。","感兹玄运徂，念尔冲规劭。","关河阂舟楫，云雨乖言笑。","潜虬媚烟霄，冥鸿避矰缴。","勉敦谷口盟，无贻北山诮。"]},{"t":"二忠祠 其一","f":"古风","c":["矫矫忠烈公，英谋本天惎。","不谓锦绣肠，乃伫干将器。","奋力当休明，朱䳒始一试。","谳狱清单辞，触邪慑文吏。","陈臬正统初，皇舆偶中溃。","寇阻括苍阳，江介潜魑魅。","帷幕已拊髀，诗书更谋帅。","公已深许国，挥剑没长彗。","连营赫组练，中坚拥旂?。","受降已蚁附，来苏乃麇至。","讵意下齐功，更阻平吴志。","乘危出远道，孤军陷死地。","可惜温序亡，竟踵睢阳事。","委巷有啜泣，壮士愈决眦。","精诚感天阍，庙食兰汤涘。","巨榜缠蛟龙，穹碑负赑屃。","哲嗣播清尘，鸿私永敷贲。","良史应特书，终古垂幽懿。"]},{"t":"二忠祠 其二","f":"五言古诗","c":["方伯本庆源，媲先树勋烈。","腾骧在万里，早已见汗血。","剖符古冈州，遇事辄勇决。","冠弁日岌峨，圭璋遽昭晰。","授钺典名藩，赐履遍海澨。","溟浸歼鲸鲵，碉房扫槎蘖。","舞干服三苗，回面靖百粤。","玉麟锡纷纶，铜柱表巀嵲。","石建盖恭谨，冯异功不说。","幽讨从江门，从容榜兰枻。","悯溺吊厓山，蹈海愤始渫。","左辖应未酬，台阶遂中折。","殊勋载盟府，芳猷被邦耋。","念功今神尧，崇祠再昭揭。","秋风汗马趋，夜月皋禽唳。","金貂缀惠文，千秋见臣节。"]},{"t":"巫山高","f":"五言古诗","c":["巫山高不极，远望何芊芊。","灵林构郁律，神宇閟冲玄。","曳云翳白日，兴雨蒙层巅。","平瞻景夷馆，俯瞰云梦田。","芳春展游豫，弭节此山前。","精灵尔何感，魂梦屡徂迁。","晨鸡奏天色，环佩声锵然。","空山旷延伫，掩涕方来旋。","人神道终异，欢爱难久延。","荒淫古有戒，兹乐诚已偏。","惟有高唐赋，千载凌云烟。"]},{"t":"拟庭前有奇树","f":"五言古诗","c":["嘉树媚朝阳，枝叶正相当。","佳人御纨素，攀条玩其芳。","眷彼从征人，思心共飞扬。","昔期别三载，今已历九霜。","繁华悦朝茂，荣耀难久常。","愿折三春干，一寄龙城傍。","不惜轩车晚，所畏道路长。","商声感鶗鴂，日暮愁红妆。"]},{"t":"社中分咏要离","f":"五言古诗","c":["勾吴素趫悍，颇闻侠烈风。","咄哉要离子，乃为万夫雄。","怯弱众所咍，伍胥明其忠。","锋刃雠所爱，草芥捐微躬。","持茅执几殆，入水术当穷。","奈何殒强敌，天幸成此功。","求名固已谬，轻生诚鲜终。","乘舟愧范蠡，首丘感梁鸿。","腐骨已蔓草，英气犹长虹。","惟有兴亡迹，千秋悲甬东。"]},{"t":"虞翻宅","f":"五言古诗","c":["城西有名刹，云是仲翔园。","烟萝日以翳，堂隍无复存。","幽林集异鸟，曲沼罗芳荪。","谏猎想奇节，醉酒悼微愆。","怀瑜尔何罪，捐玦诚少恩。","才情岂不劭，骨相故多屯。","瘴乡有逆旅，江介滞游魂。","抱独萦遐感，谈经思伟言。","运销名讵灭，身屈道弥尊。","惟有青蝇叹，千秋伤隐沦。"]},{"t":"天全所为大司马铁桥黄公作","f":"五言古诗","c":["西郭佳遨游，芳园萃森爽。","脩竹映沧池，潜虬动滉朗。","青泛何蜿蜒，降池肃间敞。","游神无近营，寓目发遐想。","彼美贲丘园，振缨遂遵养。","冥飞远矰缴，乘风适苍莽。","若凤感先民，为牺叹哲匠。","嗒尔非丧吾，超然得神王。","景行属旷筵，疏材荷甄奖。","岂伊平原欢，况逾竹林赏。","愿附扶摇翰，从容撰几杖。"]},{"t":"粤洲玩梅亭得世字","f":"五言古诗","c":["翠屿屯朝霞，青蹊屏氛翳。","藻构郁岩嵉，青阳倏开霁。","万物正芸芸，见此孤根丽。","疏影带栏楹，寒花绕庭砌。","点素焕星悬，凝英烂珠缀。","入室拟幽兰，留人比丛桂。","搴芳慰幽独，怀玉期贞励。","游目悟先几，忘言获真谛。","一谢尘滓游，逍遥人间世。"]},{"t":"玉虹涧得日字","f":"五言古诗","c":["碧溜疏遥岑，瑶光泻晴日。","束石乍萦回，衔厓转泌瀄。","清声散竽籁，静听调琴瑟。","分流虽究万，溯始乃归一。","幽讨讯真源，汲古怀脩繘。","习坎浩自盈，到海功始毕。"]},{"t":"赠陈诏州","f":"五言古诗","c":["韶石款南岳，肄水汇东溟。","岩镇俟良牧，疲人纡圣情。","推毂允明茂，之子扬德声。","豹变蔚文采，凤仪叶咸英。","渊冲恒若谷，温裕式如璚。","淮阳本卧治，华阴更传经。","匪惟惇化穆，实以心源清。","三年报邦政，万里导遐征。","衡茅惠高盖，疲苶愧逢迎。","云螭不可弭，凫藻驰我诚。","所冀隆弘美，王道今休明。"]},{"t":"送丁戊山人游罗浮 其一","f":"五言古诗","c":["远游岂不羡，逼此区中情。","愿得鸿鸾翮，乘之以遐征。","诘朝饰羽盖，嬉游至层城。","阴室启耀真，阳宫豁朱明。","俯盼列川岳，仰视灿日星。","朝搴琼树枝，夕采瑶草荣。","外观岂足慕，所贵能遗形。","纡尔瀇瀁怀，驰我凫藻诚。","临风不得并，望美空屏营。"]},{"t":"送丁戊山人游罗浮 其二","f":"五言古诗","c":["瑶台峙十仞，丹霞蔽朝阳。","上有青琅玕，下有孤凤凰。","来自君子国，五色绚采章。","所啄非腥腐，所营非稻粱。","我愿偕此鸟，溯彼灵风翔。","一举轶宕冥，再举周圜方。","昆丘罗碧树，青岑漱瑶浆。","路远竟莫致，苞羽空摧藏。","翻飞谅有待，何必内怀伤。"]},{"t":"双节为内江萧氏作 其一","f":"五言古诗","c":["华萼何相辉，兰荃竞为美。","婉娈当青阳，赍欢侍君子。","翻飞岂独翔，游行必俱止。","成言逾金石，伉义期桑梓。","良愿既我从，衔恩自兹始。"]},{"t":"双节为内江萧氏作 其二","f":"五言古诗","c":["白璧无缁磷，禔身自孤洁。","分形本同株，殉生岂殊辙。","铅姿逐泪毁，丝音随弦歇。","逝水宁回流，芳蕤不重结。","长夜何漫漫，一往成乖别。"]},{"t":"双节为内江萧氏作 其三","f":"五言古诗","c":["凄风起云屋，夕景下玄墀。","徘徊别鹤慕，啁唽离鹍悲。","陵苕夺幽色，阶草舍碧滋。","芳年屡回换，单居几何时。","感物增悽恻，羽觞难复持。"]},{"t":"双节为内江萧氏作 其四","f":"五言古诗","c":["境乐心逾悲，年殊志还戚。","茕茕抚婴孺，依依感畴昔。","红芳成皓首，㳅光信驰隙。","忘忧岂萱草，可卷诚匪席。","不见青陵台，上有双栖翮。"]},{"t":"双节为内江萧氏作 其五","f":"五言古诗","c":["芳草讵云蚀，高谊良有终。","怀清表秦里，石窌当齐封。","感念皋鱼子，精诚回昊穹。","图形昼袆翟，负榜缠蛟龙。","从此岷峨下，千秋传卫恭。"]},{"t":"题仲弟惟和云野山房","f":"五言古诗","c":["白云何灿茜，飞度玉山岑。","散漫南窗下，徘徊嘉树林。","凝霏入素几，委润夹幽襟。","翘首帝乡远，揽结兴长吟。","释耒起南亩，肤寸待成霖。","卷舒在适性，去来尔何心。","扶摇方整驾，总辔瑶池阴。"]},{"t":"天宁寺","f":"五言古诗","c":["穹标千朱鸟，嵓镇峙黄甸。","迢递屡劫馀，旷望千里见。","威神翊栋宇，丹梯凌栈齴。","隋荒戒不远，秦馀迹可践。","宇内骋良图，异人侧延盼。","混迹渔樵流，中备帷幕选。","叱咤兴风云，指麾定京县。","岂徒人谋胜，寔以觉力显。","曩基有增饰，故池仍重穿。","金骨永不焚，智灯夜犹炫。","弓剑归鼎湖，丹书閟净院。","古瓦苍鼠窜，寒林夕鸟啭。","玄运有兴衰，浮生信露电。","迷川藉津航，尘海孰漂转。","穷途创奇观，临风泪如霰。"]},{"t":"白云观","f":"五言古诗","c":["翠壁苔藓剥，雕楹风雨倾。","不见赤虬返，空闻白云名。","环中龙虎伏，鼎内铅汞争。","石函委真蜕，绛气干天庭。","松杉缅延伫，鸾鹥导遐征。","古甃汲寒冽，阴廊画仙灵。","羽流萃杂沓，鬼火流青荧。","腥膻漫玉椀，瓦砾飘金茎。","云螭杳难驾，霞踪怆余情。","修途逼暮景，改辙思长生。","稽首受玄籥，一为开瑶扃。","未敢望鄞鄂，庶能守申庚。","谛听获忧悯，恍惚聆箫笙。","出门悲风起，旷若失蓬瀛。","何时复来游，相随朝玉京。"]},{"t":"和陶徵君饮酒二十首 其一","f":"五言古诗","c":["天路何辽廓，吾生从所之。","致身苦不早，奄忽非少时。","迷途幸非远，回驾方自兹。","但当饮美酒，任性勿复疑。","有客款蓬庐，一觞欣共持。"]},{"t":"和陶徵君饮酒二十首 其二","f":"五言律诗","c":["禽庆游五岳，仲长之邙山。","鹏鴳各有适，大小安足言。","委运属壮齿，建功惭暮年。","所贵能遗形，岂愿竹帛传。"]},{"t":"和陶徵君饮酒二十首 其三","f":"五言古诗","c":["羲唐去世久，缅然伤吾情。","营营当途子，所徇利与名。","乔松历千载，蜉蝣无久生。","念此修短殊，徒令心骨惊。","有酒且斟酌，驱驰竟何成。"]},{"t":"和陶徵君饮酒二十首 其四","f":"五言古诗","c":["有乌具五色，乘云以翻飞。","毛羽何摧颓，日夜鸣声悲。","竹花久不实，饥寒无所依。","高松生南岳，岁晏当来归。","仲尼欲浮海，楚狂讥德衰。","戢翼守寒贱，无令兹愿违。"]},{"t":"和陶徵君饮酒二十首 其五","f":"五言古诗","c":["高台架林麓，眺听忘俗喧。","颇惬旷士怀，孰谓兹游偏。","轻烟起平陆，夕阳颓西山。","众鸟赴乔林，吾亦念归旋。","无闷徵在昔，铭骨事此言。"]},{"t":"和陶徵君饮酒二十首 其六","f":"五言律诗","c":["怆然感昨非，方知今为是。","白璧混青蝇，荆玉遭谗毁。","田疆困二桃，论功固当尔。","弋人亦何为，吾将寻园绮。"]},{"t":"和陶徵君饮酒二十首 其七","f":"五言古诗","c":["秋风被庭绿，粲然擢孤英。","变化每如此，底用惜其情。","开轩盼流景，倏忽西南倾。","携壶就花间，有鸟向我鸣。","兹欢信可毕，扰扰劳吾生。"]},{"t":"和陶徵君饮酒二十首 其八","f":"古风","c":["翩翩繁华子，灼灼桃李姿。","桃李虽不言，霜风摧其枝。","荣期老带索，李广逢数奇。","坎?良足念，天命不可为。","安步聊复尔，讵用乘金羁。"]},{"t":"和陶徵君饮酒二十首 其九","f":"五言古诗","c":["衡门昼常闭，好客每为开。","谓我当远游，故居不可怀。","明当偕子行，永与人徒乖。","游必昆华期，止当庐霍栖。","应龙志天飞，胡为乐蟠泥。","感君吐中肠，素心固所谐。","蹇裳自兹去，径路了不迷。","逍遥无何乡，千年方来回。"]},{"t":"和陶徵君饮酒二十首 其十","f":"五言古诗","c":["我昔游燕赵，览古登城隅。","回风振槁叶，雨雪泥中涂。","惨戚游子颜，岁晏坐驰驱。","谋生一何拙，衣襦岂无馀。","便当舍此去，息影穷山居。"]},{"t":"和陶徵君饮酒二十首 其十一","f":"五言古诗","c":["依依辞密亲，悠悠涉长道。","十上竟无成，回车念将老。","所希恢令猷，岂在忧枯槁。","冉冉玄运徂，颜色无常好。","彭殇等归尽，金玉焉能宝。","吾将谢世人，抗情烟萝表。"]},{"t":"和陶徵君饮酒二十首 其十二","f":"五言古诗","c":["吾年已强仕，非复少壮时。","都无怀禄心，尚耽古文辞。","其人虽已远，玄解或在兹。","欣与二三子，披襟瑩前疑。","忘言诚未易，庄惠不吾欺。","遵途有逸轨，逍遥随所之。"]},{"t":"和陶徵君饮酒二十首 其十三","f":"五言古诗","c":["桑麻翳蓬门，萧然断人境。","欣无耳目营，既醉还复醒。","知我诚已希，兹言贵深领。","高矩谢夷齐，清风挹箕颍。","天运固有常，得丧吾当炳。"]},{"t":"和陶徵君饮酒二十首 其十四","f":"五言古诗","c":["晦朔相环周，良辰已复至。","开轩候良朋，一斗径先醉。","衣带乘不理，杯盘乱无次。","龙蠖自有时，人岂能贱贵。","但愿餔其醨，独醒岂知味。"]},{"t":"和陶徵君饮酒二十首 其十五","f":"五言古诗","c":["炎洲负南海，中有神仙宅。","我欲从之游，苍烟杳无迹。","人生若惊电，年寿岂踰百。","玄夜忽几何，晨曦将复白。","霞举倘可期，脱屣非所惜。"]},{"t":"和陶徵君饮酒二十首 其十六","f":"五言古诗","c":["子云不晓事，白首窥玄经。","我昔弄柔翰，窃禄翼其成。","岂谓兹道非，年齿已屡更。","顾影守空堂，枳棘塞中庭。","灵芝尚三秀，鸑鷟待一鸣。","赖此慰迟暮，可齐达者情。"]},{"t":"和陶徵君饮酒二十首 其十七","f":"五言律诗","c":["芳兰杂萧艾，颓俗散淳风。","咄嗟可柰何，有酒时一中。","噤吟笑唐举，幽忧怜敬通。","真妄讵能辨，荆人遗其弓。"]},{"t":"和陶徵君饮酒二十首 其十八","f":"五言古诗","c":["世人营丹砂，系影无所得。","夸父为邓林，古来共称惑。","颓波赴沃焦，抔土安能塞。","愿言乘虚舟，往就不死国。","玄珠虽难求，获之在幽默。"]},{"t":"和陶徵君饮酒二十首 其十九","f":"五言古诗","c":["邴生长免归，于陵不求仕。","古之贤达士，得失徇诸己。","念此愧平生，屡进忘其耻。","不能守田庐，胡为去乡里。","虽云营斗储，力不任纲纪。","周任有遗训，吾行固当止。","蕣华不终朝，达生或可恃。"]},{"t":"和陶徵君饮酒二十首 其二十","f":"五言古诗","c":["余生素屯蹇，颇复怀清真。","谬当盛明日，再睹玄化淳。","人文固昭晰，宪章亦已新。","岂起东蹈海，会将西入秦。","征途不遑舍，所逐埃与尘。","为策虽不就，斯志良已勤。","奈何四海内，弃绝寡所亲。","朅来二十载，皇皇尚迷津。","念之动中怀，涕泪沾衣巾。","置此勿复言，齐契在古人。"]},{"t":"吴中三子诗 其一 文休承","f":"五言古诗","c":["文水浚灵源，信国挺华胄。","才本埒机云，论岂殊向秀。","好客屡清言，深衷辔携手。","坏林委丘壑，长缨困驰骤。","曩聆古剑篇，森罗灿星宿。","烽起吴江濆，骤珠不可觏。"]},{"t":"吴中三子诗 其二 彭孔加","f":"五言古诗","c":["彭公隐吴市，坦荡无俗氛。","雄书迈鲁国，善诔比扬云。","光彩戢鸾翮，圆方摩鹄群。","沉饮知杜机，万物从芸芸。","晤言杳关河，梦寐怀清芬。","何时觌璚树，良用慰悁勤。"]},{"t":"吴中三子诗 其三 周公瑕","f":"五言古诗","c":["周郎出江左，朗朗散风标。","六籍漱芳液，群玉方采樵。","磬折见冲抱，款言弥久要。","怆然念离夜，携手在河桥。","缅余樗散姿，谬倚英琼瑶。","回望具区云，心旌屡摇摇。"]},{"t":"游云谷山","f":"五言古诗","c":["朝从云中游，暮投云中宿。","烟岚稍出没，冈峦相迤属。","层标下奔峭，双窦惊腾瀑。","朗月沉东峰，残晖在林木。","迢迢浮云征，寥寥天宇肃。","揽衣不遑寐，良夜欣秉烛。","动极归有静，吾以观其复。","天鸡奏晨曦，杖藜骋遐瞩。"]},{"t":"大科峰望日出","f":"五言古诗","c":["炎洲孕灵秀，海澚潜异踪。","跻攀极岩险，始穷七十峰。","却倚何睢盱，竞秀皆冲融。","驾肩朝群帝，蜿伏腾飞龙。","一气混溟渤，万有开鸿濛。","骤陟忧鬓发，凝眄披心胸。","石菌不可拾，金沙或能逢。","终营菟裘居，赏心冀来同。"]},{"t":"谒白沙先生祠","f":"五言古诗","c":["玉台昔飞遁，名山屡登践。","泉壑閟霞踪，垣宫饰嘉荐。","两楹委林麓，四壁带苔藓。","敛形随化逝，神理将无变。","深衷怀若人，山阿或游衍。","渊机涵飞泳，帝牖灭闻见。","执鞭予已后，升堂迹方添。","茫然空所思，浮云没遥巘。"]},{"t":"天湖亭","f":"五言古诗","c":["湖水何悠悠，鲤鲂何筛筛。","临川无芳饵，叹息将奚为。","昔人思钓国，凌霞搆重基。","风云有消歇，池馆遂堙夷。","我行偶见此，踯躅心为悲。","旷士怀鹊起，霞举当有期。","不能唼蘋藻，泛泛随凫鹥。"]},{"t":"轩辕试剑石","f":"五言律诗","c":["仙翁本剑侠，游戏龙衮前。","金盘射白鹊，鹤发换童年。","幻化乃能尔，金石亮非坚。","神化终腾跃，洪垆空燄烟。"]},{"t":"通天嵓","f":"五言律诗","c":["郁罗隐萧台，琼扉不可扣。","耿耿阅幽灰，迢迢历星宿。","道逢猋轮客，倏与青精觏。","相携毓华林，行歌采三秀。"]},{"t":"飞云顶","f":"五言律诗","c":["龟台何岧峣，下临西极天。","灵妃舞云轺，嬉游携列仙。","鲸波忽簸荡，浮来知几年。","至今三青鸟，犹巢珠树颠。"]},{"t":"凤凰谷","f":"五言律诗","c":["翩翩五色鸟，乘云自丹穴。","览辉千仞冈，弄影寒潭洁。","饮啄岂不谋，腥腐非所屑。","虞罗尔何施，清冷坐怡悦。"]},{"t":"野人庐","f":"五言律诗","c":["黄野仙已去，于菟守灵关。","松风起万壑，时复乘鸾还。","朗吟梅花句，清丽非人间。","被衣出涧户，朗月沉空山。"]},{"t":"单道开石室","f":"五言律诗","c":["至人鍊真形，冬夏常穴处。","细石伴琼饴，饥来自堪煮。","万形等归尽，逍遥敛神去。","香火遗嵌岩，霞踪杳何许。"]},{"t":"中阁为陈公载赋","f":"五言古诗","c":["飞云带积阻，磴道多莓苔。","旃檀驾高阁，芳刹凌空开。","连峰入户牖，金银混蓬莱。","焱梯杳难即，天伎从风回。","阁中餐霞子，早隐莲花台。","神游挟希有，升降随九垓。","蠛蠓俯浊世，沧溟视浮杯。","金沙发五内，足底兴风雷。","笑入桃花源，浮光轶尘埃。","镵文记石壁，千载方归来。"]},{"t":"同文寿承李伯承郭次父梁思伯集冯大参汝言官舍","f":"五言古诗","c":["明月出西山，馀辉偏城楼。","城隅多轩盖，秉烛为夜游。","清笳杂繁吹，廓然销人忧。","坐有白云客，高谈比琳璆。","意欲蹑倒景，游戏昆崙丘。","顾我俗士驾，安能骖云虬。","开尊且命酌，主拜宾复酬。","悄然严霜下，褰裳不可留。","眷言兹夕欢，荆璧获所投。"]},{"t":"岁暮怀梁园三子 其一 吴明卿","f":"五言古诗","c":["瑶林挺荆楚，吴公秀无双。","鸿逵振英响，鸡舌备周行。","沈思运圆象，补衮回七襄。","犹龙不可絷，歌凤仍猖狂。","见客屡白眼，何人得升堂。","再召异宣室，憔悴同浮湘。","宇宙岂不廓，斯人日摧藏。","梁园啜古泪，萧条洒烟霜。","寤言觌璚树，怨彼河曲长。"]},{"t":"岁暮怀梁园三子 其二 张肖甫","f":"五言古诗","c":["蜀都寔才窟，铜梁奋天步。","心源迈古浚，气岸流俗迕。","屡迁宦不达，四壁家仍窭。","虚舟尔何心，蛾眉自生妒。","言念河朔游，亟蒙班石顾。","款关倒衣裳，胠箧见情愫。","夷门杳何许，劳人走霜露。","羊肠方险涩，鸾翮将焉鹜。","忧来变鬒发，良以思君故。"]},{"t":"岁暮怀梁园三子 其三 张助甫","f":"五言古诗","c":["汝南重月评，中郎冠时哲。","水镜铨人伦，圭璋映朝列。","玮词铸心匠，奇颖表天嶷。","将整扶摇翰，倒览金银阙。","抵掌笑时流，出走因妇舌。","遇我胸屡披，下士食为辍。","铜街骖辔游，紫逻挥杯别。","怀材卧空谷，下乘争驰蹀。","思君阻寒水，三花竟难折。"]},{"t":"五游赠郭山人次甫 其一","f":"五言古诗","c":["乘屩之劳山，三神郁相距。","羡门驾吞舟，凌波载游女。","投珠赤水阳，捐佩玄洲渚。","鳞裳杂星罗，虬盖随云举。","寓目溟涬观，挥手蜉蝣羽。","若士宁足矜，三光可为侣。"]},{"t":"五游赠郭山人次甫 其二","f":"古风","c":["恒代秘珍符，蓬蔂孕奇宝。","服食驻颓龄，颜容美神?。","息影事穷栖，散发卧绝岛。","止渴漱玄泉，疗饥掇神草。","三尸去我身，谷神自绵抱。","冥灵虽千秋，不知我寿考。"]},{"t":"五游赠郭山人次甫 其三","f":"五言古诗","c":["璚枝列涨海，若华散炎洲。","神鱼运大壑，巨浪排空浮。","云帆倏飘举，恍见轩辕丘。","鸾歌自往来，羽客乘烟流。","自非琴高侣，谁能驾扁舟。","一息骋万里，鹍鹏安足俦。"]},{"t":"五游赠郭山人次甫 其四","f":"五言古诗","c":["龙驷乘奔雷，羲和不遑舍。","白露应秋零，朱华随年谢。","愿因庆云兴，层城弥猋驾。","飘登阆风巅，三辰伏其下。","金台异温凉，玉瑩阅冬夏。","便娟多列仙，娱游使心奓。"]},{"t":"五游赠郭山人次甫 其五","f":"五言古诗","c":["天坛冠王屋，神芝伏其阴。","永愿排火粒，掇食驻蓬心。","蹑屩三台阻，息驾伊川浔。","道逢王子乔，笙竽吹凤音。","携手紫房里，匿影青云岑。","世人不可见，三华徒碧林。"]},{"t":"送姚伯子还润州旧隐","f":"五言古诗","c":["久作燕台客，几经秋月白。","秋月复春花，年年故园隔。","手把严安书，家储无甔石。","却扫平津门，垂翅长安陌。","昨夜梦归来，五湖荷花开。","杨帆从此去，要路不须媒。","北固青山在，长江流绿苔。","更寻江总宅，相期中散杯。","浮云尔何物，壮志空摧颓。","余亦乘扁舟，雷平披草莱。"]},{"t":"十四夜月同姚元白欧桢伯作","f":"五言古诗","c":["客心眷良游，秋月有华照。","霏烟敛天末，灏气澄霞杪。","素采虽未圆，云衢已光曜。","䆗窱舍朱宫，奫沦薄兰沼。","周除有近观，穷发无遗瞭。","清晖虽可娱，烦襟自萦绕。","坐俯蜻蛚吟，仰聆哀鸿叫。","关山限羁旅，岁月苦奔峭。","褰裳暂徘徊，挥杯共清啸。","朗鉴应可期，留悰展遐眺。"]},{"t":"十五夜月","f":"五言古诗","c":["纤云屏氛翳，圆景光逾烂。","澄辉溢层霄，晶瑩霭平旦。","下见长安城，金银造天半。","甲第杂星罗，雕甍蔚霞焕。","登台翼神猋，清规弥可玩。","飞觞展良游，促坐命华琯。","沈冥我思积，负羁尔情惋。","朱华方葳蕤，白露遽凌乱。","展转长河翻，劳歌南山矸。","揽环誓相于，居诸复何叹。"]},{"t":"十六夜月","f":"五言古诗","c":["盛满不恒居，驰晖已复歇。","轮囷尚皎镜，朒朓渐成玦。","气匠增萧寥，霜籁凝惨冽。","南楼俯岧嵉，关山不可越。","徂年值急景，蜚猋凌暮节。","良晤复几何，登临念乖别。","朱丝屡促柱，金罍岂徒设。","倚伏递相寻，荣贱同一辙。","且终今夕娱，冥心寄盈缺。","劳谦可久安，圭璋俟明哲。"]},{"t":"秋日集文寿承诸子得寒字","f":"五言古诗","c":["翻翻双飞鸿，戢羽游河干。","蹇予江海士，托交青云翰。","黄华届秋序，萧爽可游盘。","驩然逅缨弁，聚此西掖坦。","长筵列丝竹，中厨具盘餐。","光华盛朝阙，幽贞贲林峦。","吐讯出金石，漓文馥椒兰。","潢污非所贵，明信良已殚。","片诺季布重，盈虚翟公欢。","隙末申烱戒，相期保岁寒。"]},{"t":"赠大司马蔡公移省留都","f":"五言古诗","c":["洪河俟舟楫，大翼假扶摇。","明公值休朗，弱龄见英标。","剖符卧江海，浪迹偕渔樵。","徒闻季布诺，谁同贡公招。","朅来蓬池啸，躧步凌丹霄。","秉圭入铜龙，惠文缀金貂。","鸿思翊皇度，具瞻肃群寮。","姱容谁不企，希音一何寥。","改服指旧邦，乘流命归桡。","廉公思用赵，长孺愿在朝。","望隆位非薄，心迩迹岂辽。","永言树勋伐，怂恿慰杨苗。"]},{"t":"观舞","f":"五言古诗","c":["曲房罗荐合，华烛黼帷舒。","嘉宾出上国，妙妓产名区。","合欢垂绮带，连理缀罗襦。","霞起当瑶沓，花生绕玉除。","妆成遥掩月，体迅欲凌虚。","赴节偏容与，应歌目疾徐。","图云开绣衩，写凤曳长裾。","洛水惊鸿日，吴城掩鹤馀。","凝情增盼睐，回态转踟蹰。","静女思贻琯，芳华欲揽袪。","挂缨君未谅，解佩持相于。","寄谢东邻子，舍颦信不如。"]},{"t":"同王元美咏洼尊","f":"五言古诗","c":["昔贤寄沉冥，遗迹表江岸。","刳中若纸臼，青黄岂沟断。","鼓缶歌如渑，瓠落恣汗漫。","鲸饮聊止戈，蚕头剜柔翰。","岂惟勤小物，庶用托遐观。","盈虚有迭代，壑舟乃回换。","形模尚轮囷，铭识已芜漫。","明牧展旷筵，临盼起渊玩。","举釂咸尽欢，辍箸屡兴叹。","缅怀若旦暮，偕游等鹏鴳。","斡弃何足伤，坚贞赖幽赞。"]},{"t":"雪后同许计部过崔都水","f":"五言古诗","c":["潞水背京邑，簿书成陆沉。","况兹异乡感，复尔玄运侵。","疲骖何所适，矌望就前林。","大陆玄云合，苍龙迥且深。","绸缪赖君子，芳讯吐中襟。","并坐荫华榱，醇酎时劝斟。","悲风振积霰，颓光喧寒禽。","豫乐惬时序，延览谐夙心。","去晷良足念，来欢犹可寻。","高冥徯六羽，结桂山之阴。"]},{"t":"送苏子川之金陵","f":"五言古诗","c":["弱植窘修途，衰龄奋徒步。","愧匪璠玙姿，遂令雕琢误。","紫阁崇造天，铜龙辟朝暮。","邂逅逐骖镳，殷勤展情愫。","桂枝屡扳援，葛藟相依附。","金门我滞迹，乌衣子遵路。","方嗤洴澼劳，岂有缨緌慕。","秋草变芸黄，客子践霜露。","睽离属思浅，中情不能愬。"]},{"t":"太霞洞为周象贤赋","f":"五言古诗","c":["增城奠西趾，灵景潜金方。","仪璘列两曜，川岳备五藏。","冲腾郁剑气，䆗窱舍朱光。","乘屩恣远讨，划然见金堂。","阳乌翼我体，丹霓为我裳。","仰掇毓华林，俯吸瑶池浆。","形神永超轶，千秋常悦康。","始知中区外，还有不死乡。","玄钥顿能启，从君嬉紫房。"]},{"t":"别潘象安","f":"五言古诗","c":["紫阁崇造天，剑佩声相磨。","吐哺遘良宰，招延奇士多。","伊人奋下国，被发行燕歌。","愿以朱丝绳，锵然间云和。","千金不受赏，抱犊遵山阿。","流言点赤舄，推毂转蹉跎。","手中青琅玕，斡弃同蓬科。","倚门俟舟楫，旅服返江沱。","素交一以尽，行路起挥戈。","严霜下宿莽，悲风增微波。","强食以自爱，啜泣将如何。"]},{"t":"予告出京师贻同好诸子四首 其一","f":"五言古诗","c":["释来趋阙庭，洁身奉君子。","改服践二京，提椠馀十祀。","并辔参群龙，衰贱难隶齿。","倦翮思林皋，游鳞羡江汜。","干没今有期，离忧自兹始。","君门日九重，行子在万里。","岂无衣与繻，所念在桑梓。","揽蕙遵前途，泪下不能止。"]},{"t":"予告出京师贻同好诸子四首 其二","f":"五言古诗","c":["东阁多奇士，林风迈前闻。","而我斥鴳羽，安能凤凰群。","招延觏良宰，翻飞荷明君。","攀援绝马邓，论缀殊渊云。","荏苒经岁时，思树尺一勋。","驽钝未及展，驱策诚已勤。","行将反初服，沮溺同锄耘。","抚已寔踰量，所志惭食芹。"]},{"t":"予告出京师贻同好诸子四首 其三","f":"五言古诗","c":["双凫戏中沚，羽翼相因依。","眷言二三子，畴昔同裳衣。","嬿婉未及终，云雨当乖离。","往婴鸰原戚，今怀机杼悲。","贞悔难具卜，荣贱同一时。","众人各有营，畴能恤其私。","君子重明义，申以皎日期。","采撷异葑菲，以报琼玖贻。"]},{"t":"予告出京师贻同好诸子四首 其四","f":"五言古诗","c":["扬旌出三河，引领望双阙。","饮饯倾路岐，缨緌尽朝列。","婉娈贻赠章，光辉夺明月。","上有慎脩涂，下有遄回辙。","懿此同心言，念之五情热。","昔如形与影，今为环与玦。","朽钝诚已疲，提携俟明哲。"]},{"t":"纡胜园为张元易赋","f":"五言古诗","c":["中条距芳甸，丘壑亦未远。","缅怀上世人，于焉事嘉遁。","云螭不弭驾，霞踪尚可践。","疏峰结绮搆，临流杭珍馆。","盱䀭托幽遐，鱼凫乐暄暖。","乘流罄洄沿，习坎悟舒卷。","金门不可招，佳期起深眷。","素苕虽未零，朱华已堪蹇。","滞留岂不欢，岁月易婉娩。","愿回苑洛辔，丘中恣游衍。"]},{"t":"出京师贻同好","f":"五言古诗","c":["弱植乘嘉运，蹇步备用行。","庆云垂华渥，草木共光荣。","提椠分已溢，改玉心弥贞。","德宣藉亲交，芳兰间杜蘅。","云雨当乖析，燕婉不及并。","萧晨起严驾，揽涕沾我缨。","缅然阻川涂，旷尔逖音形。","贞悔岂预期，损益难具明。","弭怨即东路，含涕望西京。","陈词托归鸟，以愬我中情。"]},{"t":"同陵州牧关文学游小西天","f":"五言古诗","c":["陆海潜异珍，奇观在涿鹿。","积险希天门，重深讶渊谷。","真人感下生，神僧惧沉陆。","凿空启檀施，镂石藏梵牍。","委积弥年祀，青苔尚可读。","遥役讵能探，饮河恒满腹。","据槁日酣饮，远望荡心目。","夕乌东南驰，庭皋千里绿。","寤寐所思人，往来山之曲。"]},{"t":"登泰山作","f":"五言古诗","c":["神皋表东海，作镇何穷窿。","气匠搆万有，挥斤辟鸿濛。","颓然压九野，奔伏如游龙。","飞梯倚立壁，侧足临绝淙。","灵猋生两腋，乃造玉女宫。","仰视但苍莽，欲往阶何从。","平生汗漫游，泠然感绝踪。","海日连周观，悲风起秦松。","息影止岩下，摇心尚忡忡。"]},{"t":"答李季常","f":"五言古诗","c":["衡门绝尘鞅，慨然抚今昔。","良朋千里至，末契等金石。","枉驾追前踪，意惬从兹夕。","开襟出雕章，往往叙离析。","蔬畦渐堪剪，浊酒聊共适。","呜蝉歇高树，栖鸟投林隙。","为欢知几何，流火忽复易。","感君平生言，重逾连城壁。"]},{"t":"食荔枝贻李季常兼柬欧经季欧子耕","f":"五言古诗","c":["火齐出南海，累累荫房栊。","虽蒙侧生诮，移植甘泉中。","琼浆一入口，五内生泠风。","枳橘有常性，气味将无同。","君子幸见赏，饱食宁伤中。","虽云悦颜色，亦能热丹宫。","密脾间清汲，调燮乃见功。","神农疏草木，尔雅诠鱼虫。","烹芼失其宜，伐性兹无穷。","作诗贻北客，细咽无匆匆。"]},{"t":"别李季常 其一","f":"五言古诗","c":["担簦越五岭，矫志仍丹丘。","揽桂凌石室，晞发登罗浮。","金沙杳难觌，玄珠偕所求。","天长积远思，岁晏怀殷忧。","驰晖不可驻，江介迟归舟。"]},{"t":"别李季常 其二","f":"五言古诗","c":["归舟夙云迈，操袂大江陲。","一为千里别，晤言难重期。","余方忧鬒发，君自媚眉姿。","山川旷修阻，安得长追随。","玄素谅不暌，临路何足悲。"]},{"t":"别李季常 其三","f":"五言古诗","c":["临路何所陈，策身苦不早。","良马疲皂枥，应龙困泥淖。","刺绣难为工，操瑟非予好。","欢误未及营，驱驰已衰老。","青黄信木灾，被褐怀其宝。"]},{"t":"别李季常 其四","f":"五言古诗","c":["被褐守环堵，举目无相亲。","汎览穷铁摘，沉思铸玮言。","藜藿虽不充，容色无比伦。","田畴洵奇士，鲁连称达人。","君子慎末路，荣名重千钧。"]},{"t":"虬峰精舍为谢尉赋","f":"五言古诗","c":["匡山峙东南，积阻带晴霓。","蜿蜒三百里，峰峦转崭绝。","屹立睨中原，高擎拄天阙。","下有藏真士，散发弄松雪。","时来起渊潜，道味乃井渫。","薜萝惬幽贞，丛桂树芳烈。","行藏岂不荣，白黑因所说。","方追洪厓踪，距迷巨卿辙。","愿言就松门，挥杯共明月。"]},{"t":"栎园精舍为潘子朋赋","f":"五言古诗","c":["矫志事幽栖，结宇依空林。","岂无嘉树枝，息此散木阴。","达人守渊谷，遁思常陆沉。","青黄岂不贵，文绣非所任。","游言翳蓬藋，谐我忘世心。","班草话平生，寓目托嵚岑。","飞潜理自足，荣贱行相寻。","萧寥答天籁，葛天有遗音。"]},{"t":"木假山歌为邝子乾作","f":"古风","c":["越城古桧青虬枝，万仞孤生沧海湄。","繁阴婀娜巢鹓凤，盘根偃蹇藏蛟螭。","明堂大厦应难致，匠石挥斤几回弃。","礧砢已受风霜蚀，崚?会有云霄气。","山人家在扶溪边，邂逅神物心欣然。","解骖推食岂足数，移置此物当楹前。","旋开北堂上，坐我幽壑中。","眼前突兀见青嶂，绕室惨淡来悲风。","初疑天台雁荡淩紫烟，中有丹梯驾日相邅连。","又疑巨灵远擘昆崙丘，下有黄河万派喷薄之飞流。","阴阳为炭何年铸，至人往往能冥搜。","迢迢紫沂海，郁郁三神山。","崒嵂在何所，无乃虚无间。","就中拳石足怡悦，胡为跋步凋朱颜。","不如阿堵里，更著黄绮翁。","弦琴坐白石，散发呼松风。","平泉良岳知何在，惟有绿树摇青空。"]},{"t":"同关中杨勖肖宋珰传以忠吴晖王养蒙西蜀邓合何采燕集","f":"七言古诗","c":["朔风驱尘暗青草，蝉声夕满燕山道。","豪贵相逢不揖鞭，却走城南事幽讨。","城南净域敞青莲，悠悠钟磬出人天。","绿水宛通秦苑树，繁花常带汉陵烟。","寓目游情无不有，却典貂襜为沽酒。","紫绮初飘陌上桑，银鞍却繫门前柳。","座中豪士本三秦，西蜀才人并足珍。","手揽云霞挥日月，律调霜雪变阳春。","不分勋名归汗马，常思称纳上麒麟。","迩来索米长安市，伏枥悲鸣绝知己。","击筑谁知高渐离，鼓琴未遇钟期子。","就来论交应最深，莫比悠悠行路心。","孟公痛饮犹投辖，季子穷途尚剖金。","邀欢未久又伤离，汎梗飘蓬无定期。","沧江白石摇归兴，陇树秦云入梦思。","予亦翻飞向越城，几回秋月向人明。","他年汉主隆词赋，应念雄文似长卿。"]},{"t":"仙鹤花异植也青跗素萼状类胎禽即嵇含草木记所谓鹤草也观自随时山人余因命舍弟为图系以此作","f":"七言古诗","c":["青蹊窈窕连云上，芝草琅玕萃森爽。","玉蕊飘飘间药开，璚蕤的的缘溪长。","何年华表舞胎仙，缟翼霜毫势宛然。","秀方薝卜深能浅，馥俪优罗色更鲜。","五鸟枝头羞绰约，三花树里斗嫣妍。","骈素含香在遥巘，几度春风落如霰。","舞蝶萦枝乍可寻，来禽隔水纷难见。","空谷幽人觅紫芝，静闻芳气远相随。","暂移仙种归玄圃，思植灵根在赤墀。","月满空林露未销，碧海青天思寂寥。","倘遇缑山王子晋，愿随风驭听鸾箫。"]},{"t":"天台山障歌为上舍欧载卿赋","f":"古风","c":["仙闾五岳玄风迥，福地三山真气孤。","烟云杂沓见青嶂，知是何处夐绝之清都。","披图验往牒，无乃天台山东南屹，地轴洒落重溟间。","张生东吴号痴绝，十年踪迹穷追攀。","胸中尽吞云梦泽，笔下横扫淩荆关。","经营沧海赤岸万里之玄涛，意匠缥缈真宰号。","忽从波中涌宝地，稍向浦溆分渔舠。","又写风烟之九曲，古树联绵走平陆。","高人夜雪回扁舟，初日莺啼上修竹。","青蹊此去入云林，扣舷时闻樵采音。","碧桃花落纷如雾，家住秦人深复深。","探奇历险恣窈窕，却在云中蹑层峤。","石梁倒驾垂苍虬，霞标直上干朱鸟。","回流飞瀑何泠泠，远视但见银为城。","巉壁莓苔经日月，崇祠桐柏剥丹青。","金支翠旗飒羽卫，斑麟白虎纷相迎。","飘飘云气似可即，我欲散发呼仙童。","起来行叹复坐思，不觉恻恻令心悲。","狂游汗漫竟何有，黄尘污衣眼迷津。","秋霜夜夜凋玄草，春雨年年长白芝。","山泽之儒知在无，我今结束胡为乎。","盘囊丝络苍精剑，玉京渺渺从双凫。","谢康乐，孙兴公，精灵往来空山中。","文采风流今已矣，汲泉采药行当逢。","夜登天坛见海日，朝驱列缺从罡风。","阳乌顾兔反在下，笑驾楼船弱水东。"]},{"t":"秋风三叠 其一","f":"七言古诗","c":["秋风袅袅流清商，朱华零落绿草黄。","明月委隙回素光，寒螀夜啼候雁翔。","膏炉沉燎朱火扬，空房独宿私自伤。","凝思关山绕羊肠，杳难致之双明珰。","蘼芜易莠菊易芳，君何远游长相望。"]},{"t":"秋风三叠 其二","f":"七言古诗","c":["秋风淅淅玄夜狙，黼帷高张华烛孤。","严霜被野鸣蟪蛄，塞鸿沙鸨相喧呼。","惨惨白露栖庭芜，回身悃阁愁且旴。","不觉涕泗沾衣裾，白云在天丘陵纡。","杳难致之红罗襦，梁间夕鸟犹相于，别长会促谁与须。"]},{"t":"秋风三叠 其三","f":"七言古诗","c":["秋风凄凄霜霏霏，薄寒夜透琉璃扉。","玄蝉抱枝露气微，疏灯耿耿流黄机。","中房泪下如绠縻，金方路遥消息稀。","杳难致之双明玑，三星煌煌承夜辉，何为淹留忆忘归。"]},{"t":"刘明远松石图为邝子乾作","f":"古风","c":["刘生善画兼能书，材力却与凡工殊。","千金为寿不一顾，下笔颇获骊龙珠。","凡花俗卉岂足奇，貌此千仞磊落之雄姿。","左盘右蹙势争长，崩厓巨石相撑支。","皴皮剥尽风雨干，劲铁屈作珊瑚枝。","苍厓缟皓洒飞雪，晴空夭纠奔鸾螭。","太阴冥冥气熛怒，疑是巨灵挥斤之所为。","邝君高堂悬此障，阶下迸泉倏排荡。","四旁观者寂不言，顿觉丹青色凋丧。","我生好古悲已迟，五羊从前多画师。","林良待诏金銮殿，刘也奔腾真数奇。","欲遣巫阳不可招，抱膝对尔兴长谣。","秦封禹贡何琐琐，看尔直干凌烟霄。"]},{"t":"答欧桢伯长歌见怀之作","f":"古风","c":["天风木叶落，江南应早秋。","故人何处住，梦想在沙洲。","沙洲旷望弥芳渚，桂楫棠舟自容与。","零露朝漙五色芝，轻霜秋熟千头树。","怜君幽尚结精庐，抱膝躬耕读道书。","龙额何年封李广，狗监犹未识相如。","翻飞本谓云中鹄，垂耳今为辕下驹。","忆我别君颜色久，去去天涯屡回首。","玄朔风高豺虎骄，黄河日落蛟鼍吼。","金门上书不得意，落魄风尘在人后。","摧眉折翼还归来，寥落寒山对窗牖。","结驷谁知环堵贫，金貂应笑牛衣丑。","悠悠世事那复论，秪合狂歌饮醇酒。","桃哀已死不复生，见尔交情不相负。","琅玕赠我光陆离，始知风雅未全衰。","垂名本是丈夫事，莫谓扬雄壮不为。"]},{"t":"碧桃花长句","f":"七言古诗","c":["上林珍篽竞芳菲，姑射幽悰本自持。","茏葱掩月瑶台扇，皎洁临风玉树枝。","露井寒轻莺尚涩，虹梁日暖燕初窥。","施玄似污连城色，结绿偏宜照夜姿。","不同陇首飘风早，愿言度索结芳迟。","美人诒赠方璚玖，素影盈盈照窗牖。","抟成香雾睍难消，点缀云英瑩逾久。","宛转冰纨半入怀，的皪霓衣小垂手。","繁艳朝窥北里墙，轻霏夕洒临邛酒。","轻霏繁艳正堪怜，青萼芳蕤簇绛烟。","都荔胡绳惭酷烈，兰苕翡翠避相鲜。","秦人鸡犬曾迷姓，方朔诙谐遂得仙。","别有深宫愁日暮，二八年时坐虚度。","纤腰束素楚王怜，广额涂黄汉宫妒。","蜂须蝶翅芳绪阑，蕙楼菌阁罗衣单。","阶前玉露生愁色，镜里铅华失旧欢。"]},{"t":"白莲长句和公实","f":"七言古诗","c":["九春芳物已凋残，百舌声中兴转阑。","东园有恨成蹊易，南国无媒寄远难。","成蹊寄远空惆怅，素萼青跌忽摇漾。","袅袅金茎瑞雾通，霏霏玉井香云上。","玉井金茎不易逢，绿叶田田复几重。","鹭窥冰彩愁难定，蝶绕檀心恨正浓。","鹭窥蝶绕疏华动，幽香更倩回风送。","轻绡似出鲛人织，明珠乍见江婓弄。","回塘曲水日初长，妖姬妷女自相将。","但识汉宫持作盖，宁知楚客制为裳。","照影竞窥眉上绿，凌波争比额边黄。","长裾荡桨怜丝罥，皓腕攀条畏刺伤。","直谓将心同白日，始知行乐在青阳。","青阳白日去悠悠，几度相思南陌头。","娇靥只矜如月满，繁华须念逐波流。","银床寂寞翻清露，纨扇凄凉及早秋。","年催已畏倾筐尽，昼短何妨秉烛游。","风撼铜铺难独守，星回金屋迥添愁。","愿学汉皋能解佩，还同河徼善操舟。","操舟解佩怜君久，弃置红颜相忆否。","空持白璧误投人，为少黄金能取酒。","妾意频惊桃李时，君来已及芳菲后。","行路羞看陌上蓬，连根愿比池中藕。","采莲日暮绿江深，因君哀怨进讴吟。","鸿来不惮关山远，菱唱还过越水浔。"]},{"t":"仆穷居方丈之室睹时事有郁抑于中者欲默则不能欲言则不可因作五歌以遣意冀轺轩之使有闻焉 其一","f":"七言律诗","c":["沉珠浦前恶气起，玄甲朱裳附如蚁。","红旗五丈画蚩尤，海艚掠尽行商死。","庙堂肉食运权谋，刀尺纷纷搔狱市。","街衢横尸君不闻，调燮安能辅天子。"]},{"t":"仆穷居方丈之室睹时事有郁抑于中者欲默则不能欲言则不可因作五歌以遣意冀轺轩之使有闻焉 其二","f":"七言律诗","c":["去年斥卤犹有苗，今岁膏场若无草。","渔人虽收网罟功，农夫夙夜忧不饱。","皇天旱潦自有时，浑沌终伤凿机巧。","出门语塞不得言，仰视浮云色枯稿。"]},{"t":"仆穷居方丈之室睹时事有郁抑于中者欲默则不能欲言则不可因作五歌以遣意冀轺轩之使有闻焉 其三","f":"七言律诗","c":["买香南海千馀日，昔日十家空九室。","恶风巨舶不复来，官府悬金费要质。","已闻关门閒斥堠，复见宫中祠太乙。","君王蚤晚罢轮台，江湖私愿从玆毕。"]},{"t":"仆穷居方丈之室睹时事有郁抑于中者欲默则不能欲言则不可因作五歌以遣意冀轺轩之使有闻焉 其四","f":"七言律诗","c":["四方郡国皆太平，唯有粤南多战争。","攻城劫藏无虚日，旷野萧萧闻哭声。","我军才出又献捷，椎牛酾酒沾冠缨。","沙场本是征人死，何用防秋苦募兵。"]},{"t":"仆穷居方丈之室睹时事有郁抑于中者欲默则不能欲言则不可因作五歌以遣意冀轺轩之使有闻焉 其五","f":"七言律诗","c":["乘车戴笠何后先，粤人重交从古然。","迩来云雨成翻覆，秪有萁豆相熬煎。","屈原反遭申兰妒，尼父空羞盗蹠贤。","我生本是忘机者，痛哭应惭贾少年。"]},{"t":"送易居士还云台山","f":"七言古诗","c":["瓢仙昔隐云台山，悬峰侧径常追攀。","又从苍梧泛溟海，穷搜始入罗浮间。","身上木皮常百结，匣里莲花带双玦。","朱门豪贵眼曾经，尘世功名口羞说。","逢予谓是餐霞人，过款南窗动旬月。","伏火常思勾漏砂，烹茶屡忆蛾眉雪。","有时半醉插云烟，代舆员峤当眼前。","神龙跋浪腾玄圃，大鹏举翼凌苍天。","新缣偏掩笼鹅帖，浊酒何须挂杖钱。","抵掌论心方未已，海思江情倏然起。","玉舄朝翔庾岭云，霓衣夜渡贪泉水。","把君衣袂还相怜，看君神气何凛然。","爰居岂乐钟鼓响，麒麟不受珊瑚鞭。","要窥龙汉经浩劫，下视沧海犹桑田。","缑山一别堪惆怅，华表归来又几年。"]},{"t":"赠写真张山人孟易","f":"七言古诗","c":["张君少小传家学，粉绘新诗何磊落。","初仿林良画花鸟，近日白描能间作。","精心苦艺谁得知，下笔翩翩气盘礴。","松煤雪茧相映光，势似流云载飞鹤。","移床脱帽当前楹，倏见山姿在丘壑。","荷衣蕙带翻从风，细纹琐襭咸隐锋。","英芝瑶草在阶下，两旁古木皆巃嵷。","向前摩挲始觉异，僧繇醉旭将无同。","尔今技成何所羡，褰裳便欲翔燕甸。","黄金白璧意自轻，凌烟拟为开生面。","曳裾拥彗过王侯，雕盘锦席罗珍羞。","貂裘懒复事游说，白石空歌独饭牛。","人生快意百不忧，鸿冥鹄举君莫留。","鲁人今日轻家丘，余将献赋长杨去，为结鹍鹏万里游。"]},{"t":"答徐山人","f":"七言古诗","c":["东风二月沙尘起，旅邸相逢徐孺子。","敝裘短褐常不完，素发萧萧垂过耳。","往年书记云中城，五侯书币来相迎。","听葭不独知风角，聚米兼能画地形。","拟使阴山无黠虏，坐清沙漠报承明。","纨裤之徒何碌碌，卫青本自兴奴仆。","鹦鹉才高不受羁，汗马功多谁见录。","归来环堵空萧然，万卷丹书徒在腹。","天涯过我情更亲，劝予俛首甘风尘。","高冠大爵世岂乏，何必文章能致身。","我谢君言良太苦，九牛一毛何足数。","丹青本自图岑邓，汗竹谁曾薄巢许。","干旋造化由群公，苏息苍生赖明主。","石田茆屋可盘桓，阁皂罗浮相对看。","缁尘汗衣且归去，秋风落尽青琅玕。"]},{"t":"送邝和仲之郁林","f":"七言古诗","c":["邝君视我同门友，廿载交情最相厚。","下笔翩翩掣凤皇，一代词人尽回首。","少年折桂登皇畿，黄金台上倾珠玑。","直气屡千星象表，赤手欲补山龙衣。","绨袍旅邸无人荐，金马门前稀召见。","起家才得中大夫，出守遥临旧京甸。","摧眉伏谒意所轻，卧治烹鲜徒有名。","推毂不闻思魏尚，催科谁复识阳城。","以兹修途还折翼，世路羊肠堪叹息。","白衣苍狗在须臾，骐骥驽骀同一枥。","嗟君宦拙诚足悲，羡君有才何不宜。","朝廷侧席思化理，苍生引领苏疮痍。","行部倘过勾漏洞，啜古可读罗池碑。","丈夫遭逢信不偶，雌伏雄飞会有时。","我今风尘胡见羁，效颦半额羞蛾眉。","江皋已绿王孙草，烟雨欲折商颜芝。","慈亲倚门待吾归，孤帆破浪杳然去，赠君万里遥相思。"]},{"t":"送罗山甫归金坛","f":"古风","c":["君不见句曲之山横已字，三峰巉岩势相似。","金庭地肺杳莫窥，上盘天文下地理。","前有大，茆君后有杨长史。","膺图受箓称上真，炼石烧丹求不死。","隐居之后琐琐尔，十赉犹存九锡风，清虚不救台城耻。","翰墨长留天地间，琅玕散落烟霞里。","古柏槯残元气裂，龙池可以洗君耳。","华阳幼仙罗山甫，早岁餐芝思脱屣。","风流远蹑二子踪，字艺之工亦其此。","三十无人是知己，黄河之清讵能俟。","前年裹足游帝京，几度悲歌饮燕市。","布衣不得谒公卿，词场唯许交徐李。","翻然更作出塞游，拟树奇功报天子。","风尘蹩躠不可留，剑气谈锋徒碨磥。","上书羞蹈终南径，垂钓空思五湖水。","只今豺虎多啖争，主持正赖周中兴。","君期岁暮探云谷，余亦秋风发广陵。","海鹄沙鸿不可羁，水远山长无尽期。","他时肯觅朱明洞，叩门一访轩辕师。"]},{"t":"经季子祠","f":"七言古诗","c":["古木丛祠走狐兔，南北行人往来路。","坟前松树摧折枝，犹是当时留剑处。","古来贤达何纷纷，生死交情只有君。","不独片言轻尺璧，能将千乘等浮云。","可怜祠下东流水，世事悠悠亦如此。","田窦相倾又一时，宁保升沉不相弃。","失路狂生笑向天，悲歌中夜思分子。"]},{"t":"桂之树行","f":"古风","c":["桂之树，枝叶一何纷披。","托根三山阳，流辉南海湄。","隆冬霜露常不衰，扳桂之枝仰母慈。","云衣霓带皇所绥，荣光炜煜无休期，丹穴之鸟将来仪。","桂之树，其实何离离。","惟母有子载以驰，南觐上元西瑶池。","鸤鸠均平巢树枝，岭海之氓饱而嬉，非母之德嗟何为。","猗桂树，寿无极，长江如虹流不息。","踆乌之飞矫其翼，何以寿母此其匹，于万斯年保贞吉。"]},{"t":"送梁尚宝宣伯册封还朝","f":"七言古诗","c":["毅皇昔在承平曰，廊庙几人秉周礼。","文康玉立当青霄，遇事引经持大体。","逆耳每叫巫阳阍，荐贤屡有三公启。","元气当时赖斟酌，苍生至今无疮痏。","手持玺绂迎代舆，却早抽身辞楚醴。","荣枯翻覆那可常，回首台阶一流涕。","怜君杰出称凤毛，少年声价推词曹。","丰仪磊落见孤鹤，步骤英贤遗佩刀。","只今衔命窥江湖，虎符龙节藩王趋。","雕盘翠釜劝餐饭，皓齿蛾眉喧坐隅。","麾金应羡杨夫子，授简何惭楚大夫。","三湘洞庭渺在望，日暮归心愁绿芜。","翻飞更向黄金台，五云垂采辉蓬莱。","霜前驿路牙旗转，海上楼船清吹哀。","人生快意有如此，君恩未报胡为哉。","酒阑牵衣且徘徊，中原羽檄飞尘埃。","宵衣正切河南地，按剑直待诸侯来。","看君称纳麒麟殿，不愧万里腾骧材。"]},{"t":"送梁思伯游燕兼赴故人吴给事匡庐之约","f":"七言古诗","c":["梁生倜傥非凡俦，家世况乃平津侯。","前年束书走燕赵，布衣屡作金门游。","长安贵客竞迎致，生也拂袂仍丹丘。","归来二顷无负郭，茅屋秋风自萧索。","壶觞谁过仲长园，校雠空哂扬云阁。","翻然更作江湖游，知有心期在庐岳。","出门大笑谁绝群，浮云万里忽相踰。","鸿鹄从来羞燕雀，骅骝宁复顾辕驹。","江城贳酒与君别，美人当筵歌一阕。","南陌衣冠聚似云，东园桃李飞成雪。","丈夫此去岂长贫，嵂兀黄金可致身。","万国星躔环紫禁，五陵意气骄青春。","徐乐公车相待久，赋献河东未白首。","罗浮应有倦游人，书来更道相思否。"]},{"t":"邹将军平寇歌","f":"七言古诗","c":["大罗之山莽回互，石林岝崿盘西楚。","悬梯织铁难跻攀，朝啼鼪鼯夜猛虎。","茆棚竹箐何纵横，三峡黄昏怨行估。","上书无人扣北阙，忍使苍生茹荼苦。","丙辰之岁尤跳梁，羽檄交驰震霆怒。","楼船下濑遄出师，诏遣将军持绣斧。","荆蛮象郡抽精锐，漓水湟川动鼙鼓。","阴厓杀气回长风，白日精灵泣飞雨。","将军功成振凯归，大旱为霖救焦土。","伏波铜柱安足誇，昆崙之捷可重睹。","问君谋略何太奇，昔日东吴遏倭虏。","丹书兽锦从天下，大纛高牙自能取。","吁嗟四海今承平，南粤再见烟尘清。","明珠贡篚岁岂乏，玉门斥堠无脩营。","更烦牛酒休军士，函谷封泥不用兵。"]},{"t":"送亲丈黄廷寅应贡北上","f":"七言古诗","c":["孝宗之朝多俊贤，金堂玉树巢神仙。","中郎致身何坦荡，长离举翼当云天。","君臣契合在人耳，更有子姓能联翩。","季也森然见奇干，庭阶却立春风妍。","腹中万卷何磅礴，锦绣玑衡互参错。","班嗣书多不借人，相如剑成应耻学。","登台自倚轻千金，闭户那知困三略。","青衫白首何足悲，树帜词场气益奇。","贤良对荣公孙子，侧席英才正此时。","首夏辞家望京阙，三江五湖坐超越。","桂树秋风几自攀，芳草天涯未应歇。","龙阳秀色满乡关，知尔承恩霄汉间。","玉河桥畔逢五弟，为道冥鸿恋碧山。"]},{"t":"以李蓟丘竹木荒寒图赠潘少承","f":"七言古诗","c":["大漠飞霜没平野，见此森然挺奇秀。","苍苔剥落龙鳞粗，翠筱蒙茏石棱瘦。","野火烧残霹雳馀，爽气高标飒回首。","佳人绝代卧空谷，贤士羁孤成老丑。","何人貌此真苦心，古法兼应存篆籀。","异代流传李蓟丘，父子声名在人口。","轻缣古墨两相投，粉绘丹青俱落后。","潘生好事偶见之，以手摩挲叹良久。","置身恍在颠厓间，撝呵恐作蛟龙走。","锦标钿轴装重池，持归不用连城购。","潘生相就仍索诗，为尔重增遇合悲。","杜陵桃竹或变化，张公宝剑能雄雌。","千金敝帚登廊庙，肯使瑰材委路歧。"]},{"t":"题诃林异上人奇峰精舍","f":"七言古诗","c":["城西古树枝相樛，云是神僧手所植。","青皮赤文十抱强，虎攫虬奔人莫识。","几度摩娑行树底，爽气阴风振泉石。","顷来溽暑常伏枕，怅望禅栖杳难即。","清晨剥喙闻扣门，倏见磥砢悬素壁。","雪山灵草光照眼，祗园宝花乱相射。","跏趺座上尔为谁，庞眉电目仍霜髭。","楞伽万遍口能诵，毗邪丈室身不移。","白茆况迩诃林井，大士曹溪曾灌顶。","胜地犹依龙象力，清地屡照鸾凰影。","吾师日长绕百过，雨折风披何碎琐。","香炉仙乐知有无，宝胜铢衣飘婀娜。","只今甲子旬五日，种花谁见还成果。","予生苦遭尘网缚，依止清凉无不可。","此图此树俱幻迹，况涉言词计应左。","披图且谢门徒归，野客吟成山叶堕。"]},{"t":"送李尚宝伯承弟仲连归濮阳","f":"七言古诗","c":["李侯芳誉腾青云，更有爱弟能攻文。","担簦远来游上国，历块丰神倾昔闻。","共着斑衣奉慈母，满挹黄封起为寿。","谢庭玉树乃连枝，玄圃灵芝竞三秀。","兄也委身奉明主，弟也翻飞向林薮。","谁肯咸阳作布衣，却待燕台收马首。","两情去住正堪怜，歧路还逢雨雪天。","尧祠苍莽望中断，濮水潺湲何处边。","青门群公争祖席，知尔思归留不得。","云霄豪举讵为难，麟角凤毛人共识。","池塘别后句应成，宝月流辉在玉京。","倚门予独劳归梦，鸿雁南飞少寄声。"]},{"t":"仙人白鹿图同高比部伯宗作","f":"古风","c":["长安日暮尘沙愁，张镫置酒客为留。","青山忽然在旅舍，满堂木叶风飕飗。","山下长松复崛强，径路逼侧岩石幽。","黄冠似是仙人流，控驭白鹿如龙虬。","神情森爽散冰雪，紫芝照耀青云裘。","琅函玉斧插翠笼，羽扇冰弦挂杖头。","将凌三山穷五岳，暂游少别俱千秋。","白茆反琐守丹汞，洞门欲去还夷犹。","吁嗟此图仅盈尺，能令坐客开胸臆。","散发思攀岭上云，枕流愿得溪中石。","名羁利绁为何人，羡尔霞踪少拘迫。","我家行来岁月久，白鹤玄猿怨萧索。","诃林实落虞翻苑，金汋烟销葛洪宅。","低头?面胡为乎，瑶草琪花梦中隔。","远讨须寻缩地方，思归终假排空翮。"]},{"t":"送陈佥宪于舜之任浙中","f":"七言古诗","c":["蜀西使君才且雄，绣衣谒帝明光宫。","紫髯白面惊左右，剧谈吐论回悲风。","金钟翠釜世希有，紫电掣曳凡马空。","兴来落笔满毫素，片片青天飞白虹。","朝回遇我长安陌，谓是夷门抱关客。","亟呼美酒登高楼，蛾眉千金轻一掷。","是时春尽寒云愁，杨花糁糁萦芳洲。","金羁驰骤尘沙起，万里不见黄河流。","拔剑起舞君且留，茫茫世事空百忧。","五陵豪侠散烟雾，魏国平原今在否。","酒阑看君双玉玦，会稽茫茫不可越。","乘兴还从剡曲舟，相思空寄樟亭月。","樟亭月色满荷花，青山绿水拥鸣笳。","谁邻金马羁栖客，怅望银河慱望槎。"]},{"t":"送王生游关中兼赴喻中丞之招","f":"古风","c":["王生朅来厌湖海，乘屩直入云台山。","云台峰高障白帝，莲花秀色开函关。","秦封汉畤纷蚁垤，龙争麟斗如等閒。","叔孙礼乐不暇数，贾谊过秦文最古。","娄生脱?从东来，形势兴亡若目睹。","嗟哉二子旷世之，雄奇生也磊落能。","当之文章少年薄，骚雅行藏壮气仍。","孤羁黄金台前击短筑，少妇闺中赋扊扅。","星河可望不可即，推毂云霄知是谁。","西游候吏能物色，开府才人旧相识。","意气偏轻范叔袍，笑谈肯吝虞卿璧。","请缨便可击名王，手弯繁弱挥天狼。","解纷排难见胸臆，功成不顾尚书郎。","平原之游亟回首，风光已绿芜城柳。","祈连新冢生莓苔，何似菱歌酌春酒。"]},{"t":"秋夜过王库部定甫观元人赵原山水小幅因题其后","f":"七言古诗","c":["荆关神妙世希有，莒国山人亦名手。","意匠经营颇逼真，水石山林气森秀。","剡藤一幅才盈咫，万穴千岩俱点就。","芙蓉开萼迤太清，星宿汇流款崇岫。","陂陀映带粘箴莎，涧石纵横走泉溜。","日出初分意色浓，秋高始脱烟霞瘦。","吮粉含丹无此流，北苑营丘合回首。","王君好事偶得之，棐几云房顿觉奇。","况当燕市风尘日，见此溪山罨画姿。","泠然便觉心神披，严霜扑人叶辞枝。","翠眉更进金屈卮，白云在天河汉移。","醉来骑马忘南北，桐叶分题赋小诗。"]},{"t":"杂言题刘仲恭少岩图","f":"楚辞体","c":["何云雾之灿旧，而苔藓之斓斑。","划层厓之中断，闻流水之潺湲。","长松萧瑟散竽筑，泠风载鹤而往还。","纳长春之景，耀驻日月于山间。","意蓬瀛之不可涉兮，曰太行之??，走千里而开壶关。","悬梯织铁倚天璧，金堂玉霤非尘寰。","帝令倏忽凿浑沌，豢龙之子来追攀。","面岑青兮翠观，列蕙榜兮兰室。","绕九光以怡颜，鍊五石而永日。","步徙倚以忘归，抚荣观其如失。","虽封圭与緤组，终撄情乎兹术。","噫，丹青之纷诡兮，乃气象之移人。","岂予见似而惊眙兮，知久蹭蹬乎风尘。","君候千里騕䮍之身，白环世业方嶙峋。","安能从黄石而脱屣，望清溪而垂纶。"]},{"t":"哀莆中王子世廉侠士也悯闽嵪之乱作为此歌予读之泫然亦同作焉","f":"七言古诗","c":["霜拂壶公无紫气，恶氛剪断兰陂水。","城中斗潦直千钱，铁壁重关裂如纸。","儿啼女哭不得将，十万居人同日死。","虹蜺蔽日颓无光，毒蛊含沙海雾黄。","官军重入收馀烬，士卒冯凌转创伤。","吁嗟二百年来久，海上烽烟从癸丑。","徽饶行贾多缗金，漳泉篙师称好手。","七国连谋败晁错，百年为戎叹辛有。","可怜枉死朱中丞，束湿无功成祸首。","皇天厄运诚可悲，翡翠琅玕亦杀机。","王恢失计真堪恨，殷浩虚名徒尔为。","腐儒藿食忧诚拙，借箸前筹亦未迟。","虎符急下潮阳戍，三版孤城好出师。"]},{"t":"送吴约卿西巡讯张助甫","f":"古风","c":["男儿不成名，老当死蓬蒿。","一朝被遇风云起，躐登卿相如鸿毛。","仆也江湖沦落士，抱关窃伏长安市。","蔡泽甘为憔悴人，穰侯却忌纵横子。","青云之客谁相亲，九牛一毛何足齿。","荆南吴公才绝伦，念我盐车蹭蹬身。","春花秋月常邀致，剖玉倾金不厌频。","十月西行肃行李，为购宛驹报天子。","锦节朝驰马服山，金笳夜渡黎阳水。","故人为郡在滏城，千骑双旌来送迎。","推毂无人思魏尚，停骖今日挹侯嬴。","劳劳下马倾尊处，须忆青藜卧汉京。"]},{"t":"曾缮部以三招余过桢伯馆以事不赴有诗见贻因和答之","f":"七言古诗","c":["华阳高馆向夜开，严霜拂面如飞埃。","愧我驱驰犹未息，南陌东城复几回。","水部梅花清兴发，招邀月下倾金罍。","可惜佳期竟虚度，主人不乐为停杯。","城头紞紞鼓声下，碧云愁暮空徘徊。","风尘澒洞谁怜才，昭王骏骨成驽骀。","鲍叔分金怜管仲，左桃忍死推羊哀。","今人结交不重义，斯道弃之如草莱。","云天高谊乃见尔，以胶投漆差堪儗。","曾闻怀友出关门，转见悲歌觅燕市。","明堂榱栋日经营，华省移文要纲纪。","多暇犹能过我曹，露胆倾肝向知己。","鱼目难酬明月珠，阳春却入巴人耳。","只今西北烽尘起，四郊多垒国之耻。","摧眉伏枥将何为，手执龙渊报天子。","功成当看画麒麟，拂衣归钓沧溟水。"]},{"t":"中宿山歌","f":"七言古诗","c":["中宿之山如积铁，两岸临江不容笮。","回波撇漩恐行人，峭石惊湍难桂席。","土风虽恶山水奇，丹檐绛宇横江湄。","福庭七十传孔记，牺尊千载经秦时。","猿猴喜客掷山果，木魅窥人攒翠眉。","阳开阴闭在顷刻，神凄气凛令心悲。","我游万里常经此，岁月崩奔逾四纪。","宝玉应留沈宋诗，黄钟不见轩辕子。","矫首尘踪欲卧游，此山安得轩窗里。"]},{"t":"梁园歌","f":"古风","c":["我从淮阳来，十日苦风雨。","访古登平台，苍茫见齐鲁。","平台昔日孝王园，仪卫还同万乘尊。","周庐延阁通珍馆，脩竹青池带国门。","四方宾客皆麇至，枚叔邹阳最称美。","明月西堂作赋成，严霜曲榭称诗起。","荣枯翻覆那可常，左右谋臣忽中伤。","日暮杵声停故苑，秋风葵藿下睢阳。","骄奢岂辨当时事，惟有怜才解人意。","门馆荒凉谁曳裾，川原旷望聊停骑。","吁嗟行路良悠悠，白日经天河汉流。","朱轮自古多倾覆，黄金底用如山丘。"]},{"t":"答戴常伯","f":"七言古诗","c":["我昔浮沈卧金马，倾盖当时尽骚雅。","戴逵遇我情最深，一月新诗常满把。","鸰原回首忽沾衣，魏阙无媒此道非。","已甘伏枥同鸡皂，争谓弹冠谒紫微。","长安骑马希相识，朔风吹人少颜色。","穷途尚典鹔鹴裘，泥蟠未有应龙翼。","怜君结驷慰吾愁，霜腴雪韭庖人羞。","剧谈铜狄今谁在，遥指苍梧望不流。","知君日下多恩顾，奉舆执靶瑶池御。","载酒须寻仲蔚居，功成却倚将军树。"]},{"t":"鲤鱼图为大司徒三川刘公赋","f":"七言古诗","c":["谁剪生绡画神鲤，黄金作鳞丹砂尾。","大者矫健凌飞涛，小者唼喋随波起。","赤日簸弄扶桑潮，此鱼有意排青霄。","气连海岱成肤寸，势挽天河注沃焦。","良工画此有深意，不独研机在山水。","君臣遇合将无同，龙变云蒸亦如此。","燕市何人购此图，宝之不减双璠玙。","持归华屋生烟雾，倏尔沧洲落五湖。","是日天高秋瑟瑟，宾客满堂皆动色。","朱弦喜奏凤将雏，瑶阶更叶兰生日。","知是祯符不偶然，麒麟事业旧青毡。","佩刀王氏元名德，经术玄成本象贤。","腐儒亦解知英物，看尔扶摇上九天。"]},{"t":"运丁行","f":"七言古诗","c":["黄河运卒何艰苦，不值泥涂即风雨。","千里常行半载馀，得到京城半为土。","大车小车输上仓，官家却用大斛量。","拣成颗粒明如玉，复以风轮扬去糠。","仓中鼠雀尽张喙，片言不合辄笞捶。","入口沙泥尚不充，掩骭单衣岂成睡。","潜辞甲长暂逃归，忍使丁年坐憔悴。","人言自古从军乐，岂知从军亦太恶。","不如大贾浮江湖，明珠满载无官逋。"]},{"t":"思归引","f":"七言古诗","c":["平生任性无羁束，蹋翼尘途成碌碌。","年时提椠隐閒曹，此日之官领钱谷。","秖谓朝参远国门，岂知束带无朝昏。","问之几马不能对，上林圈兽都无言。","以兹筋力转驽缓，安能驱逐随车轮。","吁嗟叔夜无深识，邴原辞俸过六百。","我今蹭蹬胡为哉，况乃形容转衰白。","闻道故园初罢兵，薄田数亩可归耕。","扬舲稍待桃花水，策杖须寻漉酒生。"]},{"t":"夏仲昭万竿烟雨图为刘仲恭题","f":"七言古诗","c":["洋州墨竹曾传谱，东吴夏卿亦其伍。","常扫风枝及雨叶，世人往往倾赀取。","此幅离奇动万竿，烟岚灭没蛟龙蟠。","碧鲜下拂彪池浅，翠葆阴生洞壑寒。","天籁刁骚忽然起，水意山情落棐几。","窗前作赋戛金声，林下挥觞助玄理。","烦襟俗状借解纷，始知不可无此君。","写真已足轻尺璧，何况溪边十亩云。","愿君宝之勿轻掷，城南僦舍胜泉石。","藉苔瀹茗时展观，洗予肮脏风尘色。"]},{"t":"感旧篇答苏子川","f":"七言古诗","c":["识君忆自公车日，倾盖论心若胶漆。","长杨羽猎挥毫赋，上兰歌舞联镳出。","自馀风月尝邀致，兴来每过苏端室。","华阳骏骨知在否，乐生高台未萧瑟。","先帝乘龙去不返，小臣江汉扶衰疾。","君亦南浮入会稽，欲寻台岭营芝术。","当时席上几才人，世路艰虞各相失。","罗裳钿翠为谁骄，邻笛哀伤事非一。","岂知日月重昭洗，明堂再睹成周礼。","更衣正叶鸣鸡奏，趋朝不待铜龙启。","颇闻濒海销锋镝，复传宫中罢角抵。","否往泰来理则然，感时抚事空流涕。","管鲍交情今已无，骊黄过眼终难眯。","怜君日侍上方羞，笑余累索长安米。","风云腾踏当奈何，火色鸢肩犹旅邸。"]},{"t":"五岳山人歌赠陈玉叔之淮阳","f":"古风","c":["君不见有虞受禅封名山，五岳盘错天地间。","金堂玉霤虽迥绝，便门径路堪追攀。","真形混沌翕元气，窃之可以超人寰。","恒宗风雨舜不到，蓬莱波浪秦引还。","蜀严尚平尔何者，裹足乃欲穷孱颜。","龙伯大人顾而笑，夸父僵走诚可叹。","丹床一秘几千载，侧身长望阻且艰。","好奇独有陈夫子，妙年历落金闺士。","胸中云梦吞八九，周游名胜无难理。","虎头盘囊稳系身，直鞭天上黄麟起。","手排阊阖挥浮云，过都历国寻常耳。","昆崙五城反在下，焦原倒足愁胥靡。","玉阶历上帝谓之，齐州烟尘待纲纪。","握节朝辞金马门，单车夜到淮阴市。","东吴绮缟输几轴，洞庭橘柚来包匦。","徐关白沙河瀰瀰，须君治之平若砥。","食粱刺肥差可喜，丈夫功名要磈磥，卧游不出轩窗里。"]},{"t":"送洪山人从周谒张观察塞上","f":"古风","c":["雌伏长安市，时人嗤瓠落。","一朝烽尘起，褰衣赴戎幕。","楞伽刹宇近边庭，枪垒风云护井陉。","行拜将军金鹊印，还披壮士曼胡缨。","自言白猿传剑学，匣里青龙时出跃。","蛮府娵隅解赋诗，辕门乌鸟能占角。","韬钤本自用才人，况尔风流入幕宾。","蒲类即看登计簿，乌孙不久作藩臣。","陆沈笑我栖金马，心期岂是悠悠者。","不辞酒肉似邱陵，櫜鞬共醉垂杨下。"]},{"t":"送韩子成补三衢太守","f":"古风","c":["君不见凤凰羽翼何襹?，丹霄掣曳谁能羁。","丈夫磊落负才气，遇合风云自有时。","江左韩生称国俊，射策君门名益振。","下笔偏窥左史书，剧谈合绾苏君印。","曹郎待次拂衣回，管乐心情付酒杯。","十载幽忧缠橘市，两朝仙驭上瑶台。","畴昔论交几人在，一麾君亦思江海。","钱塘江水日生潮，严滩明月何曾改。","挂帆信宿且经过，予亦青山梦斧柯。","兰阴之水葡萄渌，襄阳小儿铜鞮歌。","腐儒岂辨一生事，黄金到手须快意。","扬雄禄位诚足轻，相如肯与公卿议。","浊水清尘自不同，贫贱之交莫相弃。"]},{"t":"刘观察仲脩酒后出芝杯饮客作短歌","f":"七言古诗","c":["刘侯喜客开华堂，正逢三五明月光。","酒酣起舞欲为寿，夜深更出玄芝觞。","此芝何年入君手，古色苍纹如篆籀。","金环觅得宁论直，玉髓凝来不曾久。","纤手雕盘照颜色，满座传观骇未识。","肯辞举釂为君欢，百年有几开胸臆。","刘侯玉署曾奋身，早年肮脏辞风尘。","异物来作长生供，怜汝本是餐霞人。","穷途遇君颜色好，析胆倾肝争草草。","交欢娄护岂足誇，不饮公荣堪绝倒。","衰迟且欲息微躯，水宿风餐借一盂。","杖藜更拟携笼去，烟雨雷平正可锄。"]},{"t":"西王母图歌为陈侍御道帙母太夫人寿","f":"古风","c":["瑶池渺何许，荡漾连龟台。","琳宫贝阙相逶迤，旭日倒射辉蓬莱。","宫中之人衣绛衣，左携青童右瑶姬。","鸾匏凤箫俨先导，天花万片飘琼蕤。","娥眉萧飒三千岁，翠軿下頫人间世。","青萃长琐丹台藉，紫元曾授金珰秘。","朅来览辉南海遥，云林仙姥还相邀。","在傍笑者东方朔，履上星辰侍玉霄。","黄封屡给天厨醴，锦绮亲裁织女绡。","一上太行停节旆，几回蜀坂住征轺。","兹日烽烟销南斗，斑斓起舞尊前寿。","幔亭曾孙今几代，浔阳江潮清浅否。","椷书青鸟更飞来，年年劝进长生酒。"]},{"t":"唐寅仲卜居英州不遂竟归作此慰之","f":"七言古诗","c":["唐生宿有耽书癖，早岁下帷穷铁摘。","赋就还称八斗才，剑成自倚千人敌。","岂知明月翻暗投，不觉青春易抛掷。","去年辞我游浈阳，南山水石为生色。","芒屦行经碧落天，墨痕渍在云华壁。","山中未具郤卿橐，道傍争避朱公席。","君有腾骧八尺身，何为蹩躠羁风尘。","尔非广柳车中客，亦岂皋桥庑下人。","劝君归来且莫嗔，城南万雉连通津。","青翰翠被堪娱日，柳眼桃心竞发春。","割角谁轻王粲少，曝衣难笑阮家贫。","旧时彩笔休轻掷，此日河东赋颂新。"]},{"t":"同黄全之梁思立黄公绍陈忠甫访安期生石室","f":"七言古诗","c":["白云山下栖真室，松径何人访黄石。","芳草犹寻旧日盟，弃繻千载曾书生。","野禅顾我忻而笑，玄鹤鼓翅锵然鸣。","林间木榻且安坐，江上浮云阴复晴。","岩前散发者谁子，划然长啸为鸾声。","兴来枕藉向天地，何暇坎壈较不平。","崎岖石路且回车，白日未落欢有馀。","登山临水不尽醉，枉作高阳一竖儒。"]},{"t":"陈忠甫以邛竹杖遗予戏作短歌","f":"七言古诗","c":["邛竹传奇西夏日，肿节瘦茎如鹤膝。","天竺高僧屡护持，尚方灵寿差其匹。","陈君好事偶得之，入手铿然知古物。","指麾铜柱开烟霏，柱石罗浮看日出。","朅来载笠访安期，怪石欹厓恐颠踬。","提携似有苍精翊，闪烁应愁山鬼泣。","偷视刀环未敢言，笑尔青藜落吾室。","感君把赠意已多，置之座右勤摩娑。","只今沧海扬洪波，冯夷出没翻蛟鼍。","微闾聚窟渺在望，金堂玉霤空嵯峨，杖乎杖乎奈尔何。"]},{"t":"画菊为孙舍人以道赋","f":"七言古诗","c":["九月严霜风槭槭，篱下黄花纷五色。","千枝结束艳明霞，一片丛生媚幽石。","略施粉黛人已惊，净洗铅华谁解识。","孤根独立已后时，岁晚馨香堪自惜。","柴桑三径未曾栽，孤山万树长相忆。","舍人寓直披此图，棐几芸窗时拂拭。","嫣然空谷回春姿，莫道佳人难再得。"]},{"t":"为邵长孺寿戚将军","f":"七言古诗","c":["将军昔佩金虎符，洗涤闽浙清寰区。","上书不肯羁南越，抚剑直欲鸣伊吾。","庙堂宵衣思颇牧，诏移内地卫神都。","蓟门坐镇今几载，能使沙场成陆海。","投箠朝澄玄菟波，衔枚夜夺乌孙垒。","旌旂整暇号令严，士马欢腾气逾倍。","椎牛酾酒日从容，翠釜黄封下九重。","边庭数米知军实，幕府程书上国功。","将兵不独如王剪，好士兼闻似孔融。","只今行年才五十，冰雪肌肤发如漆。","喜气遥从海上来，明星炯向营前出。","仙籍青华纪算多，功名麟阁图形毕。","颇闻戏下盛才良，借箸今谁是子房。","腐儒不识征西府，留滞空愧尚书郎。","愿徯函谷封泥后，剑履重看入未央。"]},{"t":"赠瞿生","f":"七言古诗","c":["齐安瞿生风骨殊，腾骧七尺非凡驹。","十龄下笔薄史汉，握中往往灵蛇珠。","而翁顷者遭羁绁，裹足洒泪来燕都。","九关峨峨森虎豹，白日朗照明区区。","肉刑末减逢汉主，槛车薰沐收夷吾。","岂为能言识黄雀，亦是精诚感白乌。","嗟哉瞿生孝且贤，珊瑚碧树谁不怜。","琅琊小令人伦鉴，倒屣为赋长离篇。","我苦十旬始休暇，不能罗致心茫然。","采衣持节即远道，青云干吕随行船。","匣中莲花光煜然，韬而不试神乃全。","用少正及中兴年，耸身玉立当云天。","遭逢不孤名下士，帝师当时亦孺子。"]},{"t":"古墨斋歌","f":"七言古诗","c":["钟王妙迹世希有，典型一代存仙手。","碑版当时走四裔，岂知摧折成枯朽。","负荷虽堪柱石才，沈埋未免尘沙垢。","英雄困顿亦如此，石阙何知但钳口。","谁其眄睐施㫋椎，李侯无乃其华胄。","松煤雪茧相映光，春蚓秋蛇互蟠虬。","团圆阴魄如顽铁，错落星辰馀北斗。","平生半世看墨本，洒泪临风一回首。","冲腾紫气初发硎，匣之恐作蛟龙吼。","所嗟指腕不相随，习气平生今在否。","李侯瑰磊能攻诗，亦复解发狂濡酒。","操笔应留纸尾书，不觉神明顿还旧。","愿君宝此勿弃捐，败缯敝帚人争售。"]},{"t":"书五岳真形图后遗朱汝脩","f":"七言古诗","c":["芦灰一杀鸿水怒，浑沌瓜分奠中土。","搆形太素谁能知，西王窃之遗汉武。","龙拿螭泊真离奇，鹄画螺书安足数。","封圭锡号徒纷纭，崇侈无乃宋道君。","苔文尚留日观顶，野火不共秦碑焚。","金门吏隐桃椎子，早学丹砂悟玄旨。","玉笈青囊稳系身，水慑蛟龙陆虎兕。","云外天行自兹始，醯鸡井鲋胡为尔。"]},{"t":"乾上人以铁如意遗余作歌答之","f":"古风","c":["吾闻壮夫一吷昆吾折，大半精光犹未灭。","鍊为如意坚且强，镂作盘螭颇殊绝。","宛若寒空千丈电，泠如阴山太古雪。","何年却入高僧手，魍魉见之应却走。","有时举向莲花座，人天万众俱回首。","羡师根尘久已除，身外尤物徒区区。","知予颇解鸿都学，相招为署阿兰居。","空中一掷偶称意，倒匣不吝牟尼珠。","尘昏幸借指授力，揽结愿与行藏俱。","用之可代巨鳌足，小试肯碎珊瑚株。","吁嗟人生电露真须臾，满堂金玉非良图。","坏衣瓦铁堪为供，绮障转觉羞吾徒。"]},{"t":"神鼎歌为任参军赋","f":"七言古诗","c":["神鼎何年出荆土，三趾龙文形制古。","丹砂水碧纷斓斑，款识纵横尚堪睹。","就中星罗六十字，读之钳口不能数。","王在寒师命太史，对扬王休周仲父。","戈鋋矛戟森开张，蛟螭离奇忽奔舞。","嗟尔神物胡为来，中兴抚运重明开。","两宫鼎食备厚养，万方玉铉多良材。","千夫操畚筑城下，富媪有意呈奇瑰。","琅函将发出紫气，石窌大吼如惊雷。","牧臣盱眵诧灵异，贮之为筑中天台。","衡霍呵卫驱罔两，江汉洗涤倾尊罍。","予生好奇颇识字，荒僻安能逢盛事。","搦管争传王太令，得宝况是任公子。","空勤枣木勒千言，尚乏赫蹄遗一纸。","逡巡闻未献明堂，金薤灵篇尚秘藏。","且罢山中采黄独，期君蚤晚发潇湘。"]},{"t":"送本空上人西游","f":"七言古诗","c":["圆师亦是吾乡士，少小出游迷处所。","寻师忽遇清凉山，裹足不踏长安路。","持咒经禅阅几霜，知有慈亲在故乡。","锡挂一袍迅飞鸟，身轻千里不赍粮。","白发相逢不相识，雨泣含凄愬胸臆。","难将恩爱等寻常，惟有无生堪报德。","欲留橘井与比邻，小筑茅龛结胜因。","魔王璎珞空持赠，长者黄金不贷贫。","白云又指苍梧道，三月瘴江多毒草。","钵里潜龙应避踪，水底鲛人争献宝。","机锋妙说倒王公，登坛振铎演宗风。","勿谓道安逢凿齿，须知玄度待支公。"]},{"t":"送泰泉先生赴南都掌院","f":"五言律诗","c":["旧迹纡皇览，稽谋藉老成。","位因推隽起，国以用儒荣。","凤阁纶为草，龙门史作程。","所希调鼎鼐，延首咏升平。"]},{"t":"粤台山怀古四首 其二","f":"五言律诗","c":["京台聊暇日，四望柳条春。","象郡元吞楚，龙洲自隔秦。","英雄无窟宅，战伐有埃尘。","汉文宽大诏，犹自感遗民。"]},{"t":"粤台山怀古四首 其四","f":"五言律诗","c":["风急俯层城，乌乌夜角鸣。","河湟千里草，骆越十年兵。","孤剑时闻吼，雄心郁未平。","脩名何冉冉，徒愧请长缨。"]},{"t":"送陈公聘","f":"五言律诗","c":["京华非远地，子去近明君。","晓辨龙池树，春翔象阙云。","封章何日上，旌旆此时分。","天末多佳句，因风寄雁群。"]},{"t":"寄盛子才","f":"五言律诗","c":["离鸿发五岭，比翼间云涯。","春拂秦城柳，秋乘汉渚槎。","风尘怜玉树，江海思瑶华。","忆女山亭夜，空岩度落花。"]},{"t":"题子乾双鹤","f":"五言律诗","c":["爱尔双笼鹤，昂昂在野堂。","孤标能自许，独立亦何妨。","素翮逢秋劲，清声入夜长。","云罗知不碍，莫遣羽毛伤。"]},{"t":"神乐观听吴道士弹琴","f":"五言律诗","c":["和风扇杨柳，古殿肃轻阴。","释我樊中虑，谐君方外心。","钧天疑度曲，流水自成音。","恐别仙源去，飘飘不可寻。"]},{"t":"香山寺","f":"五言律诗","c":["却月横香阁，祠星隐绀台。","殿随山势转，池向水源开。","双阙浮云敛，千林返照来。","鹤岑清绝处，心赏信悠哉。"]},{"t":"闻大驾南巡恭赋 其一","f":"五言律诗","c":["君王游幸地，江汉本朝宗。","湘浦聆轩乐，昭丘讯楚宫。","昔闻欢旧镐，今见入新丰。","徙倚看南极，俄成五色龙。"]},{"t":"闻大驾南巡恭赋 其二","f":"五言律诗","c":["黄道天行速，瑶图睿览纡。","万方归贡篚，四海混车书。","问道回轩驾，巡方奉舜舆。","非熊如入梦，能载渭川渔。"]},{"t":"闻大驾南巡恭赋 其三","f":"五言律诗","c":["凿道通龙辇，疏山转凤轺。","柳当旂外拂，花度幰前飘。","地即桥山古，津仍滦水遥。","皇情悲恸处，松柏入青霄。"]},{"t":"闻大驾南巡恭赋 其四","f":"五言律诗","c":["吉日行千里，征途驻六飞。","周庐闻夜柝，旅帐正宵衣。","御气翔丹毂，绯烟绕紫微。","祝融先儆路，何敢褺皇威。"]},{"t":"闻大驾南巡恭赋 其五","f":"五言律诗","c":["九庙神灵在，銮舆暇豫回。","徒劳赋黄竹，祇见却龙媒。","凤历占千祀，鸿私下九垓。","悬知歌吹入，高宴柏梁台。"]},{"t":"柬陈公聘兼怀盛子才 其一","f":"五言律诗","c":["聆尔金闺赠，思余白石歌。","共看杨柳暮，相隔海云多。","采服依丛桂，高轩映薜萝。","椒潭风日美，倚棹一经过。"]},{"t":"柬陈公聘兼怀盛子才 其二","f":"五言律诗","c":["天南归二鸟，俱是凤池群。","独立青冥外，时来瑞圣君。","春风摇綵笔，夜月理玄文。","惆怅初阳洞，相思寄暮云。"]},{"t":"挽陈少谦","f":"五言律诗","c":["定交怜鲍叔，解剑忆徐君。","穗帐生秋色，华池入暮云。","潜夫空有论，封禅竟无文。","他日山阳笛，重游不可闻。"]},{"t":"除夕和惟鉴家兄","f":"五言律诗","c":["雨色净遥天，华灯照四筵。","气催残腊日，花发艳阳年。","冷蕊融残雪，疏枝带暖烟。","春明好行乐，莫忘棣华篇。"]},{"t":"再游西山","f":"五言律诗","c":["爽气朝仍在，乘春偶独过。","雨稀芳桂少，山密夕阳多。","粤鸟愁燕土，南冠赋楚歌。","凭轩无限意，流涕满岩阿。"]},{"t":"出塞曲送陈公聘使边 其二","f":"五言律诗","c":["鸣笳发陇首，建节望河源。","莫以边功重，能令中国尊。","名王应膜拜，渠帅会宵奔。","早献安边议，归来入蓟门。"]},{"t":"过仪真访谭子羽留酌江霞馆因赠 其一","f":"五言律诗","c":["榻下高人宅，飞觞夜向分。","门临扬子渡，窗隔蒋陵云。","鸾啸因风起，渔歌送客闻。","江潭无限恨，琼树思氤氲。"]},{"t":"过仪真访谭子羽留酌江霞馆因赠 其二","f":"五言律诗","c":["留滞周南久，川程倚棹过。","江流经楚尽，岭树入吴多。","兴为悲秋发，情如惜别何。","津亭明日路，相望隔烟波。"]},{"t":"留都 其一","f":"五言律诗","c":["钟阜郁岧峣，河山望不遥。","神宫侵日月，辇路上烟霄。","弓与龙髯堕，笙随鹤驭飘。","金凫知不灭，绛节下朝朝。"]},{"t":"留都 其二","f":"五言律诗","c":["六㝢神猷焕，三垓睿览存。","铸金成九鼎，剪叶建诸藩。","玉历调元气，琼枝荫本根。","叨逢中兴日，不改旧乾坤。"]},{"t":"留都 其三","f":"五言律诗","c":["成龙占王气，游凤记高台。","山色荆衡尽，江源巴蜀来。","庙谟资一德，天险仗群材。","壮观今如此，中流讵足哀。"]},{"t":"留都 其五","f":"五言律诗","c":["紫署招延地，时髦尽逸群。","镐京陪湛露，韶舞续卿云。","秀抱江河润，光生草木文。","菁莪今日化，慷慨忆殊勋。"]},{"t":"留都 其六","f":"五言律诗","c":["伊昔风云际，谁依日月光。","鹿穷归历数，龙变化侯王。","俎豆丹青里，江山剑戟傍。","铅刀思一骋，流恨向宫墙。"]},{"t":"留都 其七","f":"五言律诗","c":["水府荒南国，江津控百蛮。","登秋来橘柚，踰海贡琅玕。","岁月龙编远，风烟鸟道寒。","朝宗真此地，王会万年看。"]},{"t":"登鸡鸣寺 其二","f":"五言律诗","c":["驻目凭虚阁，神思迥欲飞。","雨惊黄叶散，磴绕白云微。","钟簴千秋在，豪华六代非。","昙花无住迹，顿染客游衣。"]},{"t":"送李少阶尹嘉兴 其一","f":"五言律诗","c":["君向东吴去，幽寻兴不违。","水田青稻粒，游女绿荷衣。","问俗纡玄绶，裁诗坐翠微。","趋朝须及早，莫遣雁南飞。"]},{"t":"送李少阶尹嘉兴 其二","f":"五言律诗","c":["制锦荣新秩，还乡是昼游。","彩云辞凤阙，仙盖弥麟洲。","身系苍生望，符分圣主忧。","江南民瘼甚，应为达宸旒。"]},{"t":"和子乾游浮丘","f":"五言律诗","c":["海上仙山改，人间幻迹留。","鼎犹烹白石，霞自媚丹丘。","瑶草期相拾，璇房得并游。","采芝人不见，惟复桂岩幽。"]},{"t":"梦中作","f":"五言律诗","c":["春殿儆宵钟，千官步辇从。","中林亲射鹿，瑶水远乘龙。","柳外笙歌发，花间紫翠重。","周南留滞久，何日待东封。"]},{"t":"瑞雪 其一","f":"五言律诗","c":["午夜罄灵祈，千官匝紫微。","望云车盖合，度曲凤凰飞。","皎洁随纨扇，凄清炫玉衣。","侍臣裁郢曲，转觉和人稀。"]},{"t":"瑞雪 其二","f":"五言律诗","c":["瑟密因风度，严城迥不哗。","入林俱缀叶，妆岫讵成花。","积气浮琼岛，流云结素华。","盈车占上瑞，持此报皇家。"]},{"t":"题玉屏墨庄 其一","f":"五言律诗","c":["净业临丹壑，高居拥翠屏。","云光过沼白，山色入池青。","独鹤将人静，閒门共月扃。","安知灌园客，不是少微星。"]},{"t":"题玉屏墨庄 其二","f":"五言律诗","c":["兰沼碧沈沈，微风生树林。","游鱼避荇叶，食鸟下蒲心。","径狭牵衣袂，岩虚应足音。","知君数来往，应不倦幽寻。"]},{"t":"题玉屏墨庄 其三","f":"五言律诗","c":["陇蜀平分处，风烟迥不迷。","斜阳褒谷口，古树汉坛西。","泉石经龙卧，烟萝拂凤栖。","何时纡俗驾，从尔问丹梯。"]},{"t":"过盛子才馆 其一","f":"五言律诗","c":["花林同载酒，幽客重相寻。","春事连三月，乡愁搅寸心。","草青临浦尽，云白到江深。","莫忘还家路，缁尘易见侵。"]},{"t":"过盛子才馆 其二","f":"五言律诗","c":["扰扰复依依，閒来此息机。","一惊春草绿，再见杏花飞。","楚老怀瑜泣，齐门抱瑟归。","五陵珠玳美，谁复念牛衣。"]},{"t":"真州旅馆小楼望江南","f":"五言律诗","c":["江皋飞雨至，羁客易潸然。","稍湿汀前草，微生树杪泉。","舟行移远岸，帆过宿孤烟。","偶动乡园念，知忘课秫田。"]},{"t":"同行诸公渡江予独留真州","f":"五言律诗","c":["飘蓬转岐路，归梦绕丘园。","落日天边尽，孤云海上翻。","汀兰看渐歇，径菊别应繁。","谁念分俦侣，殊方独闭门。"]},{"t":"答谭子羽","f":"五言律诗","c":["三年书少至，万里兴难乘。","暂尔忘乖别，从前废寝兴。","梦回芳草积，愁入夏云蒸。","待尔金闺去，思予卧茂陵。"]},{"t":"延清馆小集和子乾","f":"五言律诗","c":["蓬径初延赏，空斋独尔思。","酒深寒夜酌，梅发早春枝。","浦外流云袅，城闉上月迟。","莫缘风共雨，长负此幽期。"]},{"t":"送何郡博迁信宜尹","f":"五言律诗","c":["初散槐阴市，还过岭峤东。","地应邻合浦，人更美文翁。","县静山容媚，官廉海错丰。","双凫难久滞，早见入丹枫。"]},{"t":"长汀李大尹挽词 其一","f":"五言律诗","c":["美政推榆次，芳名拟岘山。","祇闻携鹤去，俄见泣麟还。","荒垄松楸古，平原橘柚斑。","夜台埋剑气，犹照斗牛间。"]},{"t":"长汀李大尹挽词 其二","f":"五言律诗","c":["一从淹建水，无复画麟台。","学有雕龙辨，人非展骥才。","茂陵长卧病，栗里竟归来。","往事穹碑在，松风起暮哀。"]},{"t":"桐庐道中杂咏 其一","f":"五言律诗","c":["宿雨朝来歇，山云尚接连。","芙蓉乱越渚，粳稻满吴田。","有景拚为客，无机任似禅。","乡心虽强制，犹废夜中眠。"]},{"t":"桐庐道中杂咏 其二","f":"五言律诗","c":["结宇荷为盖，编篱槿作扉。","野晴乾鹊噪，沙暝水禽飞。","牵路缘青壁，樵歌出翠微。","滞淫非客意，山水自忘归。"]},{"t":"桐庐道中杂咏 其三","f":"五言律诗","c":["谷口条风改，江中暮霭沈。","云山招隐兴，京洛倦游心。","缉芰香盈袂，听猿泪在襟。","客愁容易老，星鬓莫相侵。"]},{"t":"桐庐道中杂咏 其四","f":"五言律诗","c":["失路人争厌，羁游兴独缄。","已捐湘水玦，还进赤亭帆。","水急流纹聚，峰高落日衔。","青山如可买，来此卧松杉。"]},{"t":"钓台","f":"五言律诗","c":["垂纶人去后，楼阁缅纵横。","龙卧沧江晚，鸿冥芳草生。","水犹喧野碓，风自落柴荆。","物色真虚事，知君不重名。"]},{"t":"豫章江行 其一","f":"五言律诗","c":["绿筱迷荒岸，清溪下乱流。","可怜听雨夜，强半为花愁。","囊已无金错，衣犹拥黑裘。","翻悲生计拙，不似钓鱼舟。"]},{"t":"豫章江行 其二","f":"五言律诗","c":["千越通津处，青山匝岸多。","鸥来摇水镜，鸿去避云罗。","钓■依蒲柳，行舟触芰荷。","本无浮海志，乘醉且狂歌。"]},{"t":"豫章江行 其三","f":"五言律诗","c":["路已经吴越，舟还溯豫章。","洪涛撞远岸，独鸟下危樯。","地近长沙湿，山连粤峤长。","所思非远道，犹复叹殊方。"]},{"t":"吕仙福地","f":"五言律诗","c":["烟霞千仞闭，沧海几回枯。","碧甃流丹汞，瑶坛上绿芜。","溪深人过少，松暝鹤来孤。","愿探琴心妙，藏身向玉壶。"]},{"t":"少壑为蔡山人赋 其一","f":"五言律诗","c":["林园无外事，一榻类安禅。","翰墨尘悰少，衣冠古制全。","市朝容大隐，山泽俨儒仙。","更欲逃名去，知成内外篇。"]},{"t":"少壑为蔡山人赋 其二","f":"五言律诗","c":["玉笥峰头景，还专一壑奇。","山卮随鸟劝，涧户有猿窥。","问字多携酒，寻僧不废棋。","云房招隐处，谁共此幽期。"]},{"t":"踰岭","f":"五言律诗","c":["萧飒风尘鬓，栖遑几入关。","蹊回还有径，林尽转多山。","无论鸣驺入，欣随望气还。","不知缘厎事，容易损红颜。"]},{"t":"香炉峡","f":"五言律诗","c":["重林遥蔽日，群峭上摩天。","蜃气何崷崒，猿声更接连。","双娥行雨庙，百丈上泷船。","远道应愁绝，乡园若个边。"]},{"t":"久雨 其一","f":"五言律诗","c":["秋风吹暮雨，萧索滞空城。","窗隙应妨入，檐虚不绝鸣。","稍侵书帙润，更益研池清。","一榻容身外，浮云未足营。"]},{"t":"久雨 其二","f":"五言律诗","c":["空斋长昼掩，于世颇无机。","一雨野池溢，千山黄叶飞。","林僧看竹少，园客负樵稀。","试问浮生里，蘧蘧几是非。"]},{"t":"久雨 其三","f":"五言律诗","c":["愁霖淹别墅，朋旧解招携。","竹偃侵花径，栏倾碍鹤栖。","苔生吟畔石，虫篆壁间题。","伫待晨曦至，腰镰课秫畦。"]},{"t":"容庵黄公挽词 其一","f":"五言律诗","c":["名高鲁单父，孝掩汉黄香。","绝学笺蝌蚪，清朝咏凤凰。","乞身书太早，忧国鬓徒苍。","赖有中郎笔，新镌古道旁。"]},{"t":"容庵黄公挽词 其二","f":"五言律诗","c":["省署捐华要，山樊适性灵。","身齐漆园吏，人授济南经。","紫气龙泉掩，玄堂马鬣扃。","年年椒糈奠，图象在丹青。"]},{"t":"寄丁戊山人","f":"五言律诗","c":["高情怜博奕，几度宿芙蓉。","琼树海云隔，瑶坛风露重。","晨餐憩危石，旅服入深冬。","后夜闻笙处，知从紫盖峰。"]},{"t":"玲珑石","f":"五言律诗","c":["险类天门凿，奇方日观悬。","云移根尚湿，雨滴溜成穿。","偃壑知灵草，窥窗有瑞烟。","可怜醒酒处，树木旧平泉。"]},{"t":"八月兵入京师十月广州始得平安消息 其一","f":"五言律诗","c":["京华愁独坐，蓬径辍相期。","惊鸟南枝怨，飞鸿北地思。","龙庭悲鼓角，凤野见旌旂。","此日江湖梦，偏悬六月师。"]},{"t":"八月兵入京师十月广州始得平安消息 其二","f":"五言律诗","c":["插羽喧边郡，游氛薄帝京。","士皆轻死战，将祇重横行。","马上青娥惨，腰间宝玦明。","生灵尔何苦，会见扫欃枪。"]},{"t":"八月兵入京师十月广州始得平安消息 其三","f":"五言律诗","c":["气倍临轩日，风生授钺时。","九边森虎旅，七萃起鱼丽。","选士皆穿札，徵兵尽死绥。","圣谟真不战，关塞偃征旗。"]},{"t":"八月兵入京师十月广州始得平安消息 其四","f":"五言律诗","c":["幽蓟襟喉地，边兵造次来。","雁门无李牧，马邑有王恢。","故垒秋阴澹，清笳落日催。","勒铭麟阁上，应待出群才。"]},{"t":"八月兵入京师十月广州始得平安消息 其五","f":"五言律诗","c":["午夜闻班马，清朝遂解围。","风尘双目短，消息万方稀。","保障逾青海，宸居正紫微。","柴门候远使，喜极倒裳衣。"]},{"t":"同易道人过霈上人山居 其一","f":"五言律诗","c":["支公禅观处，密义许相酬。","白黑虽殊致，玄无本一流。","经翻疏树下，茗宴曲池幽。","为问浮生里，何人得此游。"]},{"t":"同易道人过霈上人山居 其二","f":"五言律诗","c":["师曾访道去，言至伏牛山。","残雪经行苦，深林乞食艰。","心花晴自湛，身界老终閒。","一衲云峰下，秋来独闭关。"]},{"t":"过鹤舒山人别馆","f":"五言律诗","c":["却扫元非病，斋心欲断缘。","残年惟翰墨，虚壁祗灯烟。","夕露滋团菊，斜阳下冷蝉。","汉庭今重武，谁好子云玄。"]},{"t":"泰峰为刘处士作","f":"五言律诗","c":["习静空斋里，瞻奇仰泰峰。","白云流绝壁，黛色隐寒松。","寺与茅檐直，门经竹崦重。","夜来清梦觉，还得听晨钟。"]},{"t":"从化山水六咏 其一 刘仙岩","f":"五言律诗","c":["羽驾今何往，丹梯迹尚存。","窌藏金粟暗，书积紫苔昏。","秋水沦妆镜，春风掩洞门。","空山人不见，白露湿兰荪。"]},{"t":"从化山水六咏 其二 石鼓楼山","f":"五言律诗","c":["片石横江浒，危亭驾泬㵳。","山烟初幂树，溪水欲平桥。","游女思捐佩，佳期托采萧。","登临意无限，猿狖响山椒。"]},{"t":"从化山水六咏 其三 曲江","f":"五言律诗","c":["山色晚幽幽，清溪独放舟。","轻风低舞蝶，急雨应鸣鸠。","鸡犬桃花岸，人家杜若洲。","故园春服好，应不厌经游。"]},{"t":"从化山水六咏 其四 太平寺","f":"五言律诗","c":["为有云房约，来探不二门。","雨花临近砌，山翠落前轩。","赞佛还听偈，看心本息言。","未能超忍辱，聊此涤烦喧。"]},{"t":"从化山水六咏 其五 龙潭","f":"五言律诗","c":["侧足应防险，沈竿讵测深。","神珠浮沼面，宝剑坠潭心。","草树涵秋碧，烟萝翳夕阴。","欲知霖雨意，肤寸起遥岑。"]},{"t":"从化山水六咏 其六 杨溪洞","f":"五言律诗","c":["远岫横丹穴，危梯倚玉虚。","长生留秘诀，清隐阅仙书。","舄本凫飞后，羊知石起馀。","沧桑那可测，惟见化城墟。"]},{"t":"严何二子约予与易居士会海珠不果有诗见诒奉答","f":"五言律诗","c":["灵气方予愧，真缘子独深。","片云凝野思，明月寄遐心。","罗网鸿飞急，烟霄鹤去沈。","瑶台知不远，同尔一追寻。"]},{"t":"丁戊山人再至予适泛海归","f":"五言律诗","c":["舍舟俄见面，素发忽相侵。","纵有逢君处，知无住世心。","身将灵岳遍，性入梵缘深。","莫动归与兴，丹丘即故林。"]},{"t":"童御史仲良谪官南海偕隐士刘安元来游倾盖驿亭率尔贻赠 其一","f":"五言律诗","c":["已向青门隐，欣从白社游。","乾坤为一马，身世在虚舟。","海拟张融赋，丹从葛令求。","肯怜离索意，来访桂岩幽。"]},{"t":"童御史仲良谪官南海偕隐士刘安元来游倾盖驿亭率尔贻赠 其二","f":"五言律诗","c":["槐里归来后，苍生尚系思。","史曾书直谏，人久挹光仪。","踰岭愁风热，携家渡海迟。","想承前席问，还在中兴时。"]},{"t":"五仙观钟楼次刘安元韵","f":"五言律诗","c":["飞楼延倒景，徙倚听鸾笙。","树并孤烟耸，山当落日横。","沧波终不极，天路此时平。","未论求仙去，深杯且共倾。"]},{"t":"十五夜同丁戊山人集泰泉先生宅分得深字","f":"五言律诗","c":["行云隐明月，华烛散轻阴。","南国词臣第，东游海客心。","坐怜寒漏短，閒爱夜杯深。","更听霜空鹤，翩翩送好音。"]},{"t":"同梁思伯讯陈贵吾卧病","f":"五言律诗","c":["怪尔经旬卧，疏灯对影孤。","药曾因病识，身岂为名拘。","叹逝从星鬓，安贫任泽癯。","莫愁过往绝，人自访潜夫。"]},{"t":"上丁日拜梁文康公祠","f":"五言律诗","c":["画阁春云里，参天翠柏围。","虹光留宝册，风雨动灵衣。","扈圣天心眷，回銮火德辉。","留侯名冠古，能托赤松归。"]},{"t":"闻梁公实得请南归","f":"五言律诗","c":["天地干戈满，风尘信息稀。","暂辞青琐直，遥望白云归。","种秫堪为酒，纫兰可作衣。","蹇予犹负米，惭尔息尘机。"]},{"t":"望思伯不至","f":"五言律诗","c":["北阙书难上，南荒路不通。","尔仍淹水宿，吾已倦沙蓬。","梦寐风波外，交亲意气中。","帝城知己绝，何处托梁鸿。"]},{"t":"同吴而待杨挺秋朝天宫万岁山登望","f":"五言律诗","c":["陟胜缘芝岭，寻幽过竹房。","帝乡云冉冉，关路树苍苍。","叶应空斋磬，烟参画阁香。","玉壶偏可狎，何必泪沾裳。"]},{"t":"吴舍人内子挽词 其一","f":"五言律诗","c":["鸾镜俄朝掩，兰闺遂夜扃。","路尘昏柳翣，山雨泣松铭。","精卫魂终在，潜英梦岂灵。","空馀潘岳赋，惆怅不堪听。"]},{"t":"吴舍人内子挽词 其二","f":"五言律诗","c":["讵是朱颜改，还悲白发催。","未闻封石窌，谁见返瑶台。","瑟共湘灵鼓，舟从易水回。","江蓠应可荐，词客有馀哀。"]},{"t":"秀林亭为王舍人桓赋","f":"五言律诗","c":["风烟尘市隔，花木俗情疏。","閒爱寻渔艇，静宜看道书。","岱云翻迥野，泉水灌清渠。","羡尔高斋客，持觞常晏如。"]},{"t":"秋雨夜过公实 其一","f":"五言律诗","c":["急雨驱残暑，萧然夜掩关。","秋声过乱竹，凉气殷空山。","紫署君期入，青门我暂还。","庭前桂花发，曾忆几人攀。"]},{"t":"秋雨夜过公实 其二","f":"五言律诗","c":["懒性过逢少，襟期祇见君。","雄心频说剑，清夜且论文。","露早虫偏切，风高雁数闻。","便应欹枕卧，时事日纷纷。"]},{"t":"秋雨夜过公实 其三","f":"五言律诗","c":["隐几不成寐，萧条来朔风。","高城翻落叶，远浦滞寒鸿。","意惬新凉后，杯深永夜中。","因君爱疏散，三径数来同。"]},{"t":"招梁彦国仲登二子","f":"五言律诗","c":["江湖群盗满，搔首叹离居。","旧好谁怜子，新篇独起予。","风前停野酌，雨后剪春蔬。","不负山阴约，柴门更扫除。"]},{"t":"拙清楼闻笛","f":"五言律诗","c":["窈窕边城思，随风下陇头。","数声山石裂，一曲暮云流。","候雁霜前苦，江枫露下愁。","庾公多逸兴，今夜在南楼。"]},{"t":"欧桢伯招余过草堂不赴","f":"五言律诗","c":["拟寻鸡黍约，远赴故人招。","落叶千山暮，孤村一水遥。","天寒收橘柚，岁晏罢渔樵。","未得同携手，新林过板桥。"]},{"t":"和中阁山人守岁 其一","f":"五言律诗","c":["寒雨转霏霏，更长灯烛微。","风尘孤剑在，江海十年归。","短计惟收秫，清时屡食薇。","相看春色好，花竹满林扉。"]},{"t":"和中阁山人守岁 其二","f":"五言律诗","c":["列炬照前庭，分题尚未成。","风烟稍欲敛，河汉淡将倾。","短褐南山梦，长缨北阙情。","行藏俱莫问，披豁任吾生。"]},{"t":"药室六咏 其一","f":"五言律诗","c":["未暇浮沧海，清思一室中。","餐霞归绛府，食柏变青童。","采药幽禽导，栖心静者同。","方知灵骨异，飘举欲乘风。"]},{"t":"药室六咏 其二","f":"五言律诗","c":["结搆绿萝阴，端居怀古今。","岂能随橘性，暂觉远蓬心。","亚树猿争果，窥玄鹤应琴。","世途俱冥绝，唯有羽人寻。"]},{"t":"药室六咏 其三","f":"五言律诗","c":["上士遗丹诀，中年遣世情。","九光飞素鞅，五岳炼真形。","缓步随罡斗，斋心礼太清。","自能超浩劫，何必访蓬瀛。"]},{"t":"药室六咏 其四","f":"五言律诗","c":["卜筑虽方丈，青溪合自然。","壶中乘倒景，枕内叩灵篇。","龟脑方和药，龙胎定假年。","从来山泽里，别自有儒仙。"]},{"t":"药室六咏 其五","f":"五言律诗","c":["金门虽可羡，雅志在玄虚。","身世了非我，琴尊不愿馀。","行吟朱实落，散帙绿阴疏。","幽独园居懒，寻山或起予。"]},{"t":"药室六咏 其六","f":"五言律诗","c":["山林成独往，未觉兴情孤。","作赋怀嘉侣，忘言据槁梧。","冰肌仍绰约，金液岂凋枯。","始信风尘外，藏身有玉壶。"]},{"t":"别黄幼章南归","f":"五言律诗","c":["客程犹万里，旅服已三春。","倦马风尘色，离觞江汉人。","病兼吟落叶，愁复泛长津。","白璧谁持赠，还家慰所亲。"]},{"t":"赠王文纯","f":"五言律诗","c":["玩世吾应拙，逃名尔更迂。","夷门人岂识，燕市酒曾沽。","白首矜然诺，黄金信有无。","归来江海日，能□□□□。"]},{"t":"潞河风雨骤作","f":"五言律诗","c":["自笑浮生拙，飘飘信客槎。","波涛翻陆海，风色惨平沙。","岸圻应防燕，林昏不辨鸦。","江湖成稳卧，无梦到京华。"]},{"t":"黄子铺","f":"五言律诗","c":["京尘犹未远，野落自萧骚。","田父频驱雀，居人半带刀。","牛羊斜日下，蓬堁朔风号。","苦忆南窗下，壶觞只自操。"]},{"t":"董子祠","f":"五言律诗","c":["古庙丹青在，幽人此重寻。","浮云碣石外，落日广川阴。","壁尚藏书古，庭犹积草深。","因怜不遇者，此地倍沾襟。"]},{"t":"狼口阻风","f":"五言律诗","c":["断岸悲风急，停舟浊浪深。","千山低野日，孤树繫春心。","客邸频炊玉，行囊屡探金。","无能慰离索，箕踞向秋阴。"]},{"t":"同徐郎中吴给事访李使君郡斋得雷字","f":"五言绝句","c":["故人千里至，落日一尊开。","天合孤城雨，风驱大□□。","□□□□□，□□□□□。","□□□□□，□□□□□。"]},{"t":"歌风台","f":"五言律诗","c":["万乘威灵远，千秋伏腊思。","古墙阴薜荔，寒雨湿旌旂。","汤沐山河在，光华日月垂。","竖儒逢世难，流恨大风词。"]},{"t":"集姚元白市隐园","f":"五言律诗","c":["江山馀故国，水石到名园。","草色幽亭合，云光曲沼翻。","狂来犹说剑，乱后此开尊。","一罢濠梁咏，襟期谁共论。"]},{"t":"题余伯祥河亭","f":"五言律诗","c":["高斋开白下，疏树倚青溪。","竹露秋逾滴，山云晚渐低。","汉京班氏学，剡曲戴颙栖。","念尔风流在，令予恋解携。"]},{"t":"过黄淳父旅寓","f":"五言律诗","c":["烽火不堪论，相逢但酒尊。","悲歌同易水，长剑去吴门。","世事穷愁过，贫交古谊存。","销魂怜此别，江路听清猿。"]},{"t":"姚园席上赠吴山人子充","f":"五言律诗","c":["剧谈修竹里，共指白云期。","四海无家日，千山独往时。","故人蝉冕贵，久客鬓毛衰。","欲把吴钩赠，飘零念路歧。"]},{"t":"永兴寺访吴僧福懋","f":"五言律诗","c":["敛屦穿深竹，牵萝过石桥。","僧来经茂苑，寺古记南朝。","暂住因烽火，将归驾海潮。","谁言缘易断，翻遣别魂销。"]},{"t":"同黄淳父登雨花台","f":"五言律诗","c":["高座翻经处，扪萝试一登。","群峰当暮敛，万象入秋澄。","树色分萧寺，松风起汉陵。","伤心烽火日，楼橹在西兴。"]},{"t":"过陈时亿兄弟留酌石亭先生之子","f":"五言律诗","c":["江左应才窟，三株独出群。","交情原白首，器业自青云。","万事衔杯失，千山把剑分。","龙门吾敢托，生已后陈君。"]},{"t":"避兵青阳将军滩","f":"五言律诗","c":["已是愁风景，兵戈复路难。","鬓毛今日变，衣袖几时乾。","山水还鄣郡，奔亡自楚冠。","酒楼萧索尽，谁遣客愁宽。"]},{"t":"送林元育之仙游","f":"五言律诗","c":["何氏乘龙处，芳湖澹不流。","烟霞异人境，鸾鹤下真游。","扇枕黄香恋，岩泉谢客留。","石床须汛扫，吾欲访丹丘。"]},{"t":"送苏仁甫之永安","f":"五言律诗","c":["君去延平郡，传经有旧踪。","青山藏九岛，紫气抱双龙。","傲吏当清世，閒曹拟素封。","裁诗多暇日，能寄海云重。"]},{"t":"同思伯将游石室山经石门作","f":"五言律诗","c":["秋风摇落后，水国挂帆游。","壁垒成千古，江山空四愁。","浦云移远树，汀月送行舟。","不用歌丛桂，王孙自滞留。"]},{"t":"泊灵洲宝陀寺","f":"五言律诗","c":["荒亭围树色，孤石揽云根。","野水寒侵岸，渔舟夜到门。","霜枫閒共倚，沙鸟静闻喧。","不寐看山月，秋声满给园。"]},{"t":"至三水江雨骤作","f":"五言律诗","c":["鸡犬依茅屋，鱼虾集市门。","峡山高浪隐，桂水细流喧。","雨枕听更卧，江船把酒论。","丹梯知不远，飞梦蹑昆崙。"]},{"t":"渡峡","f":"五言律诗","c":["沧江流正急，山势划中开。","绝壁交青竹，寒冰滴翠苔。","树翻栖鹘动，藤接饮猿哀。","不为耽形胜，能无夜雪回。"]},{"t":"嵩台","f":"五言律诗","c":["景绝因江会，楼高更得名。","山回到海色，树殷落潮声。","日影朱旗直，风含白氎清。","凭阑聊引睇，谁悉古今情。"]},{"t":"宗吕二牧宴于孝肃堂","f":"五言律诗","c":["词人今岳牧，能吏岂閒曹。","象郡烽烟净，龙门气色高。","清尊开暮雨，虚槛俯秋涛。","不共南楼夜，谁知庾亮豪。"]},{"t":"尹明府雨中邀饮","f":"五言律诗","c":["漉酒能留客，柴桑意绪多。","疏花明雨槛，高栋隐星河。","檐雀窥尊喜，城鸦接翅过。","不愁沾湿重，馀润入烟萝。"]},{"t":"宗吕二牧邀游石室山 其一","f":"五言律诗","c":["锦石分琼岛，苍山转碧流。","岩泉高迸出，云木曲相樛。","栈绝应防马，崖悬稳系舟。","谢公今在郡，何似永嘉游。"]},{"t":"宗吕二牧邀游石室山 其二","f":"五言律诗","c":["鶱飞心屡动，回复意空迷。","山势移舟失，云光避席低。","黄花粘岸细，锦树得霜齐。","风起长林暝，清尊未解携。"]},{"t":"宗吕二牧邀游石室山 其三","f":"五言律诗","c":["金床何窈窕，玉乳细堪扪。","苔藓深题刻，风云出洞门。","幽仙閟绝景，弱水断孤根。","服食留真诀，惟应静者论。"]},{"t":"宗吕二牧邀游石室山 其四","f":"五言律诗","c":["山水何来暮，宾游赖此同。","波涛恐谢傅，风月醉山公。","竹日停深翠，枫霜倚薄红。","清笳莫更奏，箫鼓出岩中。"]},{"t":"宗吕二牧复饮饯于嵩台书院","f":"五言律诗","c":["谁言千里别，复此一尊留。","意气深投辖，声名起共舟。","风江宜晚泊，云峤罢东游。","一掩蓬蒿径，萧条桂树秋。"]},{"t":"唐寅仲以李公麟瓦研见遗谢答","f":"五言律诗","c":["一片陶泓质，曾经洗玉池。","文章今日事，模范古人师。","雨濯金星出，苔侵玉箸欹。","连城何用假，投赠比琼枝。"]},{"t":"风汎崇兰图","f":"五言律诗","c":["在室偏同气，当门偶自防。","祇怜幽谷性，莫叹后时芳。","作佩馨弥久，裁书叶正长。","佳期频怅望，南国有微霜。"]},{"t":"杨祠部宅送陈玉叔之淮安","f":"五言律诗","c":["故人遥拥传，炫服且还乡。","芳草经吴绿，清淮入海黄。","离襟分夜月，官烛照西堂。","祇益风尘梦，随君郢路长。"]},{"t":"答吴明卿见寄","f":"五言律诗","c":["兵起黄河日，余归岭峤时。","风波一失势，歧路转相悲。","白鹿成长往，青云恐后期。","罗浮故无恙，来把桂松枝。"]},{"t":"同欧桢伯梁思伯游西樵山夜宿浦口","f":"五言律诗","c":["近戍津亭暗，遥村猎火孤。","秋风吹日夜，客思满江湖。","梦怯鱼龙起，愁听雁鹜呼。","苍茫问前路，吾已愧长途。"]},{"t":"翠岩在碧云村外","f":"五言律诗","c":["青山开断岸，千尺下嵚崟。","风起碧云乱，虹流白日阴。","藤萝争袅缀，鱼雁悦高深。","纵有桃花发，应无俗驾寻。"]},{"t":"下山复题云谷书院壁","f":"五言律诗","c":["何年招隐地，绮构出林端。","石磴苍烟湿，云门白雪寒。","地因霞外僻，天到谷中宽。","有约重携手，高临百八盘。"]},{"t":"同吴而待张中卿兄弟过崇胜寺","f":"五言律诗","c":["一径远尘嚣，孤峰坐阒寥。","霜林依断岸，江浦入寒潮。","草自香台积，花随宝胜飘。","禅心无起灭，持钵过清朝。"]},{"t":"寄刘安元","f":"五言律诗","c":["戎马关心日，谁能问隐居。","想过天竺寺，还著茂陵书。","鸿雁经年至，风尘两鬓馀。","梅花难远寄，吟望独愁予。"]},{"t":"游罗氏园池","f":"五言律诗","c":["芳园穷落日，山水有馀欢。","早岁知怀橘，清秋共握兰。","风烟向浦尽，花木隔池看。","为恋幽岩桂，尘冠且未弹。"]},{"t":"同桢伯泛芙蓉溪","f":"五言律诗","c":["锦水经寒浅，扁舟任兴行。","幽花两岸紫，残照一湖明。","游女行歌艳，渔翁对影清。","芳洲多杜若，搴望若为情。"]},{"t":"梁少传馆咏拒霜花","f":"五言律诗","c":["簇簇繁霜朵，深秋开正齐。","纤浓随落日，结束对幽栖。","客屡停杯坐，诗频摘叶题。","试看临水处，何似若耶溪。"]},{"t":"少传期集琪林徐道士馆得青字","f":"五言律诗","c":["采药何时返，乘风此暂停。","入门桐树长，到院薤丛青。","碧海藏城市，瑶坛见日星。","过逢元胜侣，能为写黄庭。"]},{"t":"心远亭听陈公载弹琴","f":"五言律诗","c":["阮公操绿绮，梧竹对高閒。","白雪流深壑，夕阳明远山。","幽襟散物外，馀响出林间。","兴到悠然处，披襟未拟还。"]},{"t":"送谷子迁还姑苏","f":"五言律诗","c":["万里寻师去，沧波肯暂留。","岭云经古寺，江路入新秋。","瑶草应堪拾，丹砂不易求。","归逢明处士，沽酒话罗浮。"]},{"t":"刘仙坛","f":"五言律诗","c":["坐出千林杪，坛荒累劫馀。","烟霞归内景，天地入蘧庐。","白石留禽戏，苍筠篆鸟书。","无能探蕊笈，归路独踟蹰。"]},{"t":"朱子庵","f":"五言律诗","c":["灵飞超浩劫，珍馆寄幽寻。","水引山门远，云藏涧户深。","青精堪度世，白日此修心。","洞口风雷起，鸾笙下翠岑。"]},{"t":"黄子书堂","f":"五言律诗","c":["白业留孤墅，青山蔽数椽。","鸟曾迎木客，花更挹蒲仙。","瓢挂县萝壁，茶烹涤砚泉。","犹疑散发处，长诵紫苔篇。"]},{"t":"暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其一","f":"五言律诗","c":["远眺山河尽，孤吟水竹偏。","高云搀树密，野日避花鲜。","径石欹相带，岩房曲对悬。","贪奇收客泪，留醉夕阳边。"]},{"t":"暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其二","f":"五言律诗","c":["胜事传韦曲，幽寻我辈能。","临风觞酌缓，落日兴情增。","画壁逢僧问，丹梯引蔓登。","故侯应不贱，瓜地有东陵。"]},{"t":"暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其三","f":"五言律诗","c":["大野临燕赵，跻攀意自豪。","云沙千堞暗，松柏五陵高。","西日愁相对，南音醉懒操。","菟裘无处所，弥觉此生劳。"]},{"t":"暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其四","f":"五言律诗","c":["脱帽当松顶，移舟傍竹阴。","岂知青琐客，还有绿萝心。","思苦诗篇警，情忘酒盏深。","寥寥山吏部，千载此知音。"]},{"t":"暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其五","f":"五言律诗","c":["林壑晚逾胜，风尘远暂忘。","物情嫌肮脏，吾意在耕桑。","败叶虫行篆，浓花密占房。","浮生堪浊酒，穷远任苍苍。"]},{"t":"暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其六","f":"五言律诗","c":["列岫当空倚，三峰近席攒。","碧滋苔藓色，阴益石池寒。","日费壶中药，天遗象外观。","却疑幽绝处，堪挂野人冠。"]},{"t":"暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其七","f":"五言律诗","c":["海柏南方得，名花上苑移。","露添垂径实，风亚出墙枝。","采摘情都尽，飞腾意转迟。","芳菲应可惜，停骑待成诗。"]},{"t":"暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其八","f":"五言律诗","c":["布地千金积，邀欢一径开。","花光摇解佩，荷气送行杯。","水蹙昆池动，云移碣石来。","飘零犹壮观，肯作雍门哀。"]},{"t":"暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其九","f":"五言律诗","c":["芳园争倚并，幽事此中多。","时序花飞甚，身名老去何。","天遥金马署，星动白鸥波。","我去寻黄绮，相思在薜萝。"]},{"t":"过姚上舍伯子草玄亭","f":"五言律诗","c":["怜君花树下，复有草玄亭。","山色墙头出，宫云雨后青。","听莺移远杖，相鹤检仙经。","谁测风尘里，沈冥有客星。"]},{"t":"官舍杂咏 其一","f":"五言律诗","c":["多病年方觉，清斋日颇长。","槐阴閒闭閤，竹榻静焚香。","宿鸟争移树，疏花不过墙。","幸无尘牍扰，幽事足徜徉。"]},{"t":"官舍杂咏 其二","f":"五言律诗","c":["怀绂初为吏，修心未到僧。","流年穿木榻，长夜伴灯檠。","懒出从题凤，慵书误画蝇。","款门逢酒伴，胜饮玉壶冰。"]},{"t":"官舍杂咏 其三","f":"五言律诗","c":["兰省虽清秘，蓬扉自泬㵳。","编篱多绿槿，间树出红椒。","客至常班草，觞馀自挂瓢。","茹芝聊复得，空费鹤书招。"]},{"t":"官舍杂咏 其四","f":"五言律诗","c":["不堪驱世事，祇足称閒居。","叩齿清朝过，科头累月馀。","墙隈常置笔，帐内苦无书。","虽羡侏儒饱，终年免负锄。"]},{"t":"官舍杂咏 其五","f":"五言律诗","c":["知有看花约，春朝更不眠。","盖多从雨借，屐自上山穿。","得俸宁供醉，谋生亦任天。","校量终岁里，常在习池边。"]},{"t":"官舍杂咏 其六","f":"五言律诗","c":["官箴浑不解，侠气顿能销。","素发嗟垂领，红尘屡折腰。","世情飞絮过，乡思断蓬飘。","为甚抽簪未，山中少药苗。"]},{"t":"官舍杂咏 其七","f":"五言律诗","c":["灌园常不仕，沿牒偶为官。","夜宿芸香阁，朝看苜蓿盘。","草玄能尚白，鍊骨未成丹。","终拟藏名去，墙东老鹖冠。"]},{"t":"官舍杂咏 其八","f":"五言律诗","c":["潦倒时堪弃，清狂自懒医。","生涯千日酒，岁课五言诗。","倚树常趺坐，逢人或解颐。","汗青吾岂敢，赖有子云知。"]},{"t":"官舍杂咏 其九","f":"五言律诗","c":["虽然称校理，笔研久生尘。","白虎多同异，金门自隐沦。","桂薪从度日，榆荚又残春。","斟酌浮生理，须寻漉酒人。"]},{"t":"官舍杂咏 其十","f":"五言律诗","c":["高枕从吾拙，卑栖乐性全。","岂无洴澼计，不受绨袍怜。","野客犹分俸，当垆更觅钱。","管弦何处乐，夜夜似西天。"]},{"t":"官舍杂咏 其十一","f":"五言律诗","c":["红叶侵阶出，青枫夹陛飞。","春风开紫阁，月朔拥朱衣。","端拱封书少，清关接士稀。","惊心垂象下，江海客星微。"]},{"t":"官舍杂咏 其十二","f":"五言律诗","c":["故山多胜绝，归梦不须占。","竹长成高格，松青坠古髯。","种园芝自给，煮石火频添。","何日抛簪绂，迎暄在短檐。"]},{"t":"同吴明卿游大觉庵","f":"五言律诗","c":["风尘不入寺，花木自为林。","赤日清凉地，青山吏隐心。","古藤垂屋角，独鹤占松阴。","车马长安客，谁能向此寻。"]},{"t":"张肖甫宅饯别高右丞伯宗得杯字","f":"五言律诗","c":["长安残雪后，复共故人杯。","挥手关山远，离心岁月催。","楼船过澧浦，羽猎上京台。","应念游梁客，金茎首重回。"]},{"t":"张肖甫洪从周过款山房","f":"五言律诗","c":["天涯殊物候，犹未换春衣。","花事看将半，故人逢渐稀。","过云传旅雁，乘月启山扉。","幸有尊中酒，能忘赋式微。"]},{"t":"同肖甫夜宿龙华寺 其一","f":"五言律诗","c":["曲水通龙沼，荒塍次鹿园。","风尘湖外断，云气岛中鶱。","静院鸟双下，寒檠客对言。","谁知朝市里，丛桂得扳翻。"]},{"t":"同肖甫夜宿龙华寺 其二","f":"五言律诗","c":["相期禅客话，高枕白云层。","月色千江水，山门七祖灯。","钟声散落叶，壁影挂寒藤。","欲续良宵兴，尘劳恐未能。"]},{"t":"郭山人次甫从东海来将游北海留止轩中因赠 其一","f":"五言律诗","c":["双屐带莓苔，新从日观来。","山川游子梦，风雪故人杯。","龙性应难驭，鸾情不易媒。","莫言成独往，高浪驾蓬莱。"]},{"t":"郭山人次甫从东海来将游北海留止轩中因赠 其二","f":"五言律诗","c":["采药三年别，乘风万里游。","可怜丛桂约，又过菊花秋。","大梦君先觉，多岐古所尤。","鲁连空蹈海，何似驾苍虬。"]},{"t":"陈侍御道襄招朱陈二使君同集","f":"五言律诗","c":["双凫犹暂驻，骢马复同游。","入夜城阴静，将春雪意收。","月曾千里共，兴作两宵留。","何处吟庄舄，凄风起凤楼。"]},{"t":"溪南别业为万考功言卿赋 其一","f":"五言律诗","c":["自有山林性，能将物我齐。","剪茅成野径，披荔待幽栖。","辋口茱萸沜，芳洲杜若溪。","何当接衡宇，琴酒日相携。"]},{"t":"溪南别业为万考功言卿赋 其二","f":"五言律诗","c":["日暮鸣桡去，溪流几许深。","自随明月往，应少世人寻。","水石含幽意，鱼凫识赏心。","漆园元寄傲，何事挂朝簪。"]},{"t":"溪南别业为万考功言卿赋 其三","f":"五言律诗","c":["凭眺因高尽，虚明与水宜。","绿萝垂雨幄，丛筱罥风丝。","岛屿通桃径，壶觞到习池。","因知竹林下，不减上皇时。"]},{"t":"溪南别业为万考功言卿赋 其四","f":"五言律诗","c":["昔年云卧处，尚有读书台。","墨沼鹅群浴，苍苔鸟迹开。","洞门扃馆宇，涧户出风雷。","谁识东山意，曾招隐士来。"]},{"t":"姚元白以玉华石见遗兼枉高篇奉答一首","f":"五言律诗","c":["幔亭一片雪，迢递削孤峰。","云壑有千态，丹梯知几重。","瑶华君辍赠，金简我遭逢。","好驻壶中景，他年炼玉容。"]},{"t":"同思伯携酒访文寿承辞以事弗果文有诗见贻和答一首","f":"五言律诗","c":["长安才日下，犹阻使人来。","便欲笼鹅去，空成骑马回。","寻盟须夜雪，留兴待春杯。","莫谓青毡冷，东风有落梅。"]},{"t":"和徐子与答郭次甫折梅相赠之作","f":"五言律诗","c":["何处来芳讯，春风把一枝。","薄云千涧暝，深雪独行时。","策杖香随至，开尊影倒窥。","罗浮虚月色，此地有佳期。"]},{"t":"同子与过善果寺访吴约卿时濮阳二苏在席得台字","f":"五言律诗","c":["称心游野寺，携赏上春台。","日色催停骑，花枝笑举杯。","吏閒方外得，山好雪中来。","暂过虽乘兴，翻成倒载回。"]},{"t":"雪中同约卿过子与","f":"五言律诗","c":["出关愁日暮，踏雪喜新晴。","酒挹青骢客，诗传白雪声。","径花沾湿重，檐溜滴阶平。","此日冲寒兴，还因下榻名。"]},{"t":"十三夜过苏子川兄弟","f":"五言律诗","c":["残雪留寒在，空庭占月多。","玉珂停上客，红袖拂清歌。","劈杏调香酪，分杯试海螺。","谢家兄弟好，邻并忝羊何。"]},{"t":"忆归","f":"五言律诗","c":["久客念将归，重嗟筋力违。","蘼芜长送客，荷芰未裁衣。","白首贫交少，青山旧业微。","伤心同海燕，懒向画梁飞。"]},{"t":"晓经西苑","f":"五言律诗","c":["玉树晓青苍，琼花接混茫。","回风吹雨气，曲磴落云光。","薜荔摇珠网，芙蓉暗石房。","鱼龙无秘戏，双鹢锁朦廊。"]},{"t":"送江山人游岱岳","f":"五言律诗","c":["暂拂缁尘去，将扳岳顶行。","布裘经雪绽，藜杖入山轻。","奇字扪萝识，新诗望日成。","路人惊骨异，疑是羡门生。"]},{"t":"过范子宣得山字","f":"五言律诗","c":["解鞍寻竹下，逸客况同攀。","一榻成云卧，双轮对雪山。","笼鹅方点翰，贳酒且开关。","城市逃名得，扁舟未羡閒。"]},{"t":"送董孟材","f":"五言律诗","c":["燕台收暮雨，杨柳变繁阴。","以我思乡泪，知君久客心。","云门攀岳近，汶水到家深。","羽猎看成赋，高标在桂林。"]},{"t":"同尹王二僚长夜直禁中","f":"五言律诗","c":["偶同金马客，儤直凤凰城。","景气浮琼岛，春星丽玉衡。","缭垣疏树色，曲水细流声。","独夜难成寐，斋心捧大明。"]},{"t":"同杨邦彦徐子与过汝和雪舫集","f":"五言律诗","c":["芳菲不可度，幽意与谁论。","夜雪留孤舫，春花入酒尊。","风尘容倦客，湖海共清言。","兴罢各分手，青山落蓟门。"]},{"t":"韦园别子与得谈字","f":"五言律诗","c":["宾御促征骖，离觞且共衔。","春风吹杜若，野日上松杉。","郡外嵩高色，尊前史汉谈。","竹林吾党在，何必羡江南。"]},{"t":"张玄超诸子集借树轩得春字","f":"五言律诗","c":["门多车马尘，行径且逡巡。","沧海风期在，长安冠盖新。","燕来茅屋雨，花暗玉河春。","莫厌尊中酒，青山别故人。"]},{"t":"送盛少府烈忠还长兴","f":"五言律诗","c":["金门逢傲吏，知住五湖浔。","洞壑苍山远，云门下箬深。","钓舟移柳浪，茶具在花阴。","倘遂抽簪兴，双凫共入林。"]},{"t":"次甫将游北岳有期复过轩中同作","f":"五言律诗","c":["将还沧海上，复共草堂眠。","药笼金鹅蕊，藜灯白雪篇。","浮沈官自拙，肮脏尔相怜。","三径容归去，何须问俸钱。"]},{"t":"送梁思伯使云间兼归岭南","f":"五言律诗","c":["尊酒促鸣珂，云间拥传过。","王程千里远，秋色五湖多。","拜手辞金阙，淹情寄绿萝。","乡心将去雁，随尔渡关河。"]},{"t":"李伯承张玄超月下过轩中","f":"五言律诗","c":["竹簟因风敞，萝衣过雨披。","故人来此夜，词客况同时。","坠叶惊风早，归禽选树迟。","烦襟何用涤，玄论自相宜。"]},{"t":"省中即事","f":"五言律诗","c":["蹉跎成白发，不敢叹为郎。","饱食知才忝，高眠苦日长。","渴思金井冻，坐恋玉墀香。","不记频来往，藤花又过墙。"]},{"t":"送陈子野之崇仁","f":"五言律诗","c":["荣君非薄宦，所贵在经奇。","山续匡君传，亭寻孺子碑。","行藏多任性，词赋不逢时。","会看双龙气，冲腾向赤墀。"]},{"t":"送梁彦国之滦州","f":"五言律诗","c":["击筑悲难尽，挥杯路向分。","山藏到海郡，树引入关云。","才大人称屈，时明主好文。","白麟奇木对，前席待终军。"]},{"t":"送李仲连任赵藩审理","f":"五言律诗","c":["桐叶随王命，丹书遣侍臣。","出关迎紫气，飞盖起黄尘。","树拥丛台月，花馀邺水春。","从来豪侠地，授简尚词人。"]},{"t":"招姜主客宗孝王杜二舍人王项二文学吴沈刘居四山人集借树轩 其一","f":"五言律诗","c":["蓬径留嘉赏，风尘得友生。","白云窥夜酒，明月照乡情。","叶应孤砧响，星浮万堞平。","岁华空荏苒，莫厌管弦声。"]},{"t":"招姜主客宗孝王杜二舍人王项二文学吴沈刘居四山人集借树轩 其二","f":"五言律诗","c":["帝乡星渐改，燕谷暖还遥。","心事邀欢尽，年华赖酒销。","花枝随起舞，月色破孤寥。","聚散浮生易，难忘是此宵。"]},{"t":"同王仪甫过水塘庵","f":"五言律诗","c":["入寺已昏黄，纱灯照上方。","寒冰胶积水，清梵响空廊。","颂酒襟期洽，怀山梦寐长。","不辞风雪夜，携手共云房。"]},{"t":"得张广平助甫书","f":"五言律诗","c":["经年传尺素，入手泪纵横。","白发生乡国，秋风到郡城。","著书千古事，作吏众人名。","谪去方年少，怀沙莫怆情。"]},{"t":"雨","f":"五言律诗","c":["短日仍多雨，轻飞似暗尘。","病逢寒食夜，书寄故乡人。","节物频年异，衣冠后会新。","圣朝容拙宦，又过五陵春。"]},{"t":"闻徐子与解汝宁太守","f":"五言律诗","c":["一麾犹未达，多病遽隳官。","岂为才名误，终伤世路难。","河濆归客骑，苕水濯尘冠。","猿鹤应相语，空山得岁寒。"]},{"t":"上巳雨夜王仪甫吴约卿杜从殷见过时王将外补","f":"五言律诗","c":["汎羽逢今夕，春阴未有花。","乡心随去雁，城柝乱栖鸦。","聚散京华梦，飘零汉使槎。","朋知青琐满，前席莫言赊。"]},{"t":"李伯承将之谪所同吴约卿欧桢伯携酒过讯","f":"五言律诗","c":["星斗正阑干，春风夜复寒。","归心牵濮水，别酒共长安。","流落诗名在，驱驰吏道难。","莫言捐玦易，曾著鵔鸃冠。"]},{"t":"送王正意之任怀庆","f":"五言律诗","c":["不薄王门吏，知君属数奇。","图书观洛日，车骑入梁时。","沙覆经秋草，风高积雪枝。","河堤回首处，碣石暮云垂。"]},{"t":"约卿授馆桢伯携酒过讯","f":"五言律诗","c":["风尘疲上谒，幽兴屡难忘。","敛屐穿深竹，移尊过草堂。","流尘经雨净，微月逗云光。","谁下南州榻，相怜有异乡。"]},{"t":"过刘刑曹仲恭出先世所藏名贤翰札相示","f":"五言律诗","c":["华省归常晚，明灯坐不迟。","雨凉新草径，风静落花枝。","物论中朝在，文章故老贻。","西园叨胜引，清夜可无诗。"]},{"t":"佛日过顾汝和观柳公权书兰亭禊帖同许元复文寿承姚元白集","f":"五言律诗","c":["欲寻修禊事，屡问辟疆园。","车马尘方静，莺花日稍暄。","馔蒲供早食，班草对清尊。","莫谓过逢易，三生此共论。"]},{"t":"桢伯以西山纪游诸篇见示因书其后","f":"五言律诗","c":["闻追金马客，振锡万峰阴。","西岭元天竺，东来是佛心。","梯楼还见日，绝壑更扪参。","归诧风尘士，探珠自宝林。"]},{"t":"迁居","f":"五言律诗","c":["沈冥无所适，燕市又移居。","庑下从栖泊，蓬门倦扫除。","炎风时展簟，凉月乍窥书。","犹说金张第，登龙日不虚。"]},{"t":"得家报云岭外焦旱殊甚深有渔樵之忧赋此","f":"五言律诗","c":["近得家园信，羁人易怆情。","四郊多垒战，三月废农耕。","婚嫁谋多拙，渔樵计未成。","谁怜炊桂者，犹自滞秦京。"]},{"t":"同许长史殿卿姚鸿胪元白欧文学桢伯游郑氏园池 其一","f":"五言律诗","c":["何处移觞得，欣逢出郭晴。","林光披雾远，树色入池清。","喜客禽争聒，穿花日递明。","虽然萍水地，携手一交情。"]},{"t":"同许长史殿卿姚鸿胪元白欧文学桢伯游郑氏园池 其二","f":"五言律诗","c":["逼仄缁尘里，兹游属兴奇。","梯云花落树，伏槛水平池。","暝色催歌起，凉风返棹迟。","分携还此日，须忆桂丛枝。"]},{"t":"姚元白将还金陵同顾汝和兄弟欧桢伯过访","f":"五言律诗","c":["伏热应难避，幽寻重有期。","蓬门经雨静，旅馆见花迟。","世路归能早，才名宦独卑。","飘零五湖约，杯酒又何时。"]},{"t":"约卿自邯郸回同桢伯过讯留酌出示张助甫所寄书","f":"五言律诗","c":["三径促行杯，单车远道回。","凉风披菡萏，深夜坐莓苔。","洛水双鱼至，晴天一雁来。","碧云何处所，乘月故徘徊。"]},{"t":"约卿自北岳回以庙碑见贻","f":"五言律诗","c":["绛节凌虚上，行吟已日边。","树穷沙碛外，石堕寺门前。","云气扶双舄，泠风下列仙。","相逢嵇叔夜，犹枉紫苔篇。"]},{"t":"独坐","f":"五言律诗","c":["触热还骑马，乘閒即掩扉。","乡愁来伏枕，雨气入秋衣。","薄禄胜渔猎，贫家望蕨薇。","简书闻遣将，为解揭阳围。"]},{"t":"七夕约卿携酒邀过桢伯馆","f":"五言律诗","c":["北斗拂阑干，凉风下露寒。","新妆初学凤，彩女正乘鸾。","别恨良宵促，来期隔岁难。","谁怜金屋里，犹倚桂华看。"]},{"t":"雨夜姚元白欧桢伯携酒过访","f":"五言律诗","c":["杯酒销馀日，茆斋坐夜清。","疏砧风外急，孤烛雨中明。","乡国伤多事，浮沈笑此生。","问奇吾转愧，难得是交情。"]},{"t":"桢伯馆同咏秋雨得青字","f":"五言律诗","c":["萧飒含悲思，那堪倦客听。","风烟驱惨淡，木叶应飘零。","远树先浮白，重峦骤失青。","停云无浊酒，谁为遣沈冥。"]},{"t":"助甫梦与余泣别见寄","f":"五言律诗","c":["谪宦人情异，新秋景物悲。","别离如昨日，少壮岂前时。","易水风犹惨，关山月屡亏。","故园嵩洛畔，携手莫教违。"]},{"t":"伯常携酒过访僦居","f":"五言律诗","c":["载酒蓬扉下，烽尘正此时。","将军勤破敌，野客废谈诗。","久坐丛花烂，狂歌白氎欹。","边尘犹未静，吾敢道归期。"]},{"t":"奉命至西山坟园 其一","f":"五言律诗","c":["回首长杨苑，风霜始觉秋。","青山低卷幔，寒日淡披裘。","杨柳兼村落，菰蒲有钓舟。","佩鱼虽汉使，还得采真游。"]},{"t":"陈侍御道襄宅离夜遇雪得零字","f":"五言律诗","c":["把袂风尘日，燕歌且共听。","客心寒易怆，离夜酒长醒。","蕉荔经持节，江湖感聚萍。","黄金交谊少，垂白任飘零。"]},{"t":"陈宪使少岩之西越附寄舍弟书","f":"五言律诗","c":["偶逢铜柱使，一寄岭南音。","乡思楚云碧，江帆漓水深。","名途谁荐士，歧路我沾襟。","不似西飞雁，随君到桂林。"]},{"t":"欧桢伯馆夜别梁彦国还卢龙","f":"五言律诗","c":["东阁多奇士，诸侯有辟书。","岂知残岁别，仍卧茂陵居。","绝塞烧荒后，孤城雨雪馀。","飘零今夜酒，难与故人疏。"]},{"t":"阅军池河度清流关","f":"五言律诗","c":["赤符曾破敌，紫气复临关。","千古兴亡地，中原指顾间。","浮云随马策，落日照刀环。","远愧轻裘者，铭功上岘山。"]},{"t":"同盛仲交宿黄崖岭","f":"五言律诗","c":["荒村无雨盖，枕藉向田庐。","汲水初蒸黍，燃肪可照书。","山云遮户密，松韵过窗虚。","寄谢牛衣客，劳劳且驻车。"]},{"t":"闽警","f":"五言律诗","c":["干戈愁越骆，闽海更堪怜。","篁竹频依险，鲸鲵共戴天。","未收熊耳甲，莫费水衡钱。","痛哭谋臣疏，珠厓肯弃捐。"]},{"t":"得仲弟西越书云有挂冠之兴予亦请告期暮春可聚故园赋此订约 其一","f":"五言律诗","c":["北阙无媒者，南音只自操。","向人肝胆露，为吏爱憎劳。","药饵丹砂少，山林白雾高。","故园茆屋在，相见接春醪。"]},{"t":"得仲弟西越书云有挂冠之兴予亦请告期暮春可聚故园赋此订约 其二","f":"五言律诗","c":["铜符如可解，皂帽肯归迟。","迂拙人皆笑，功名我自疑。","花应团北户，鸟亦恋南枝。","何必山阴守，将归发誓辞。"]},{"t":"闻吴明卿上计以禁例不得相晤赋此寄怀","f":"五言律诗","c":["流落闽中使，生涯近始闻。","泪收江北雨，身老越南军。","积思生春草，新愁隔暮云。","倘携延水剑，犹可报明君。"]},{"t":"坠马卧疾遣闷","f":"五言律诗","c":["寒冰方内手，蹇劣亦长驱。","岂意千金堰，翻成九折途。","过门劳客问，策杖待人扶。","试探囊中俸，东邻酒肯沽。"]},{"t":"明卿自闽至晤于吴约卿官舍","f":"五言律诗","c":["一自游梁后，相逢又郭门。","酒因多病废，诗许故人论。","霜雪驱单骑，星河望九阍。","莫谈江海事，羁客恐销魂。"]},{"t":"曾子玉比部召饮同桢伯集","f":"五言律诗","c":["岁晏驱羸马，过逢亦少期。","偶从官阁里，共和法曹诗。","扫叶当风牖，衔杯摘露枝。","琳琅欣触目，留醉愿归迟。"]},{"t":"姚元白自金陵至遇于慈仁寺方丈","f":"五言律诗","c":["共怜千里约，还向五陵逢。","行径寻黄叶，栖禅问雪峰。","诗篇新满纸，旅思夜闻钟。","君看双班鬓，知余万事慵。"]},{"t":"同苏子川欧桢伯访吴化卿姚元白于慈仁寺","f":"五言律诗","c":["二仕逃禅处，人谁访薜萝。","穿林惊雪重，梯阁见山多。","候骑花间并，栖禽竹下过。","云房未寥寂，红烛对清歌。"]},{"t":"送姚元白考绩还金陵","f":"五言律诗","c":["赐舄旋南省，归轩背北风。","故人青琐隔，江月白门空。","酒熟逢残腊，花开觅旧丛。","因君忆鲈脍，携手问江东。"]},{"t":"曾子澄过访招桢伯同集时子澄将之塞上 其一","f":"五言律诗","c":["论交千里日，不独旅情亲。","夜烛长安酒，征衣北地尘。","荣途吾白首，风景是残春。","欲赠无奇策，西秦别有人。"]},{"t":"曾子澄过访招桢伯同集时子澄将之塞上 其二","f":"五言律诗","c":["亦知分手易，杯酒问前期。","怨别难成赋，从军更有诗。","孤莺将薄曙，残露尚明枝。","回首天山夜，闻笳忆此时。"]},{"t":"孔子河逢刘德卿","f":"五言律诗","c":["高士藏真处，门迎孔子河。","青山经楚暮，凉雨到江多。","白发生行路，清樽对放歌。","回车千古意，今日共蹉跎。"]},{"t":"秋夜山亭答潘少承","f":"五言律诗","c":["别离欣把袂，披写共登楼。","木叶千山雨，虫声四壁秋。","酒缘多病止，榻为故人留。","已似嵇康懒，那堪复远游。"]},{"t":"兰薰香","f":"五言律诗","c":["岭外多奇树，扶疏异泽兰。","空山徒自媚，中土不曾看。","色夺青绫被，香宜紫箨冠。","携来经万里，犹结故人欢。"]},{"t":"元美改席于浮玉山同作","f":"五言律诗","c":["青山行不尽，转入道场幽。","孤塔云相拄，双溪水合流。","舟移石不碍，星落影还浮。","俯仰看今古，能无忆醉游。"]},{"t":"雨中留宿张幼千家 其一","f":"五言律诗","c":["秉烛坐清夜，摊书共草堂。","疏砧秋思早，微雨客衾凉。","鸡黍成良晤，风波忽异乡。","羁愁稍披豁，触目见琳琅。"]},{"t":"雨中留宿张幼千家 其二","f":"五言律诗","c":["不为愁风雨，还因恋解携。","途长思老马，梦短怯晨鸡。","离思中年恶，音书后夜题。","片帆何处落，邗水易东西。"]},{"t":"广陵旅舍欧桢伯陆华甫黄定甫过访","f":"五言律诗","c":["草草簇蔬盘，还追燕市欢。","云停高阁暮，雨过大江寒。","贫贱交情在，风尘昭语难。","行装戒前路，谁问客衣单。"]},{"t":"同定甫游李鸣卿园亭","f":"五言律诗","c":["世事足悠悠，因君复漫游。","行随脩径转，坐占小亭幽。","艳蕊晴堪摘，清池夏不流。","诗情馀白首，云卧恣丹丘。"]},{"t":"谒董子祠","f":"五言律诗","c":["英风怜马上，间世睹人文。","玄冕加繁露，青衿仰庆云。","诗书维汉鼎，柱石奠淮濆。","东阁多奇士，寥寥竟不闻。"]},{"t":"铜瓦厢谒大禹庙","f":"五言律诗","c":["德水千年在，谁能忘禹功。","金堤非旧迹，铜瓦见新宫。","野著沧凉日，林交惨淡风。","路岐何用感，王气满关东。"]},{"t":"冬夜过许计部官舍","f":"五言律诗","c":["壮心怜岁月，浊酒话平生。","古院疏槐影，高楼画角声。","孤踪悬北阙，倦翮思南征。","惟有无衣客，同君独夜情。"]},{"t":"趋顺义县 其一","f":"五言律诗","c":["使者正乘轺，东行上郡遥。","关门临井口，城堡落山腰。","岸远沙如雪，风悲水似潮。","客愁何处著，寒月助萧萧。"]},{"t":"趋顺义县 其二","f":"五言律诗","c":["内园停使节，地主敞华筵。","酾酒黄粱薄，登盘紫芡圆。","军声飞鸟外，乡思捲芦边。","向夕无探骑，平沙直际天。"]},{"t":"洪胜寺","f":"五言律诗","c":["野寺逢人少，残僧乞食迟。","古墙花不发，丛薄鸟兼悲。","沙聚看尘劫，天长立暝时。","伊吾惭抚剑，剜草读唐碑。"]},{"t":"峪口","f":"五言律诗","c":["翠削庞峰峻，高蟠鸟道孤。","东西分幕府，沙草满平芜。","牧马闲千匹，当关用一夫。","传闻汉诸将，犹议塞飞狐。"]},{"t":"过真如寺乾上人访蔡文学子耕","f":"五言律诗","c":["霞踪成海客，休暇惬相寻。","累劫空弹指，千言是说心。","当门官树直，隐座佛灯深。","阶雪方盈尺，何人候少林。"]},{"t":"杜比部遣惠瓶酒白鱼","f":"五言律诗","c":["碧酒双丝络，银盘小白鱼。","味全胜冷炙，情独重春蔬。","冻瓦封霜后，晴檐曝日馀。","赖君能好事，难并太玄书。"]},{"t":"答陆山人本仁","f":"五言律诗","c":["三年无一字，梦想落沧洲。","不遂金门谒，还从庑下游。","春生琼树馆，天远洞庭舟。","薄劣风尘里，空惭骏马求。"]},{"t":"紫荆关","f":"五言律诗","c":["径转蛇盘险，云连鸟去长。","山桃微著紫，沙柳不成黄。","重镇临天府，神功划大荒。","金城谁献议，老作尚书郎。"]},{"t":"宿关城公署","f":"五言律诗","c":["深院静松筠，喧喧鸟雀群。","窗明犹瞰雪，榻冷半侵云。","入夜风声异，边关气色分。","更长梦猿鹤，不解赋从军。"]},{"t":"饭银钗岭馆舍","f":"五言律诗","c":["云藏千仞壁，日落数家村。","节冷无烟火，沙乾乏水源。","山家供麦饭，野逻具醪尊。","稍喜临边静，垂鞭出此门。"]},{"t":"戗风岭","f":"五言律诗","c":["沙泥拆雨岸，细路转堪憎。","去马冲风色，征衣挂石棱。","疲兵时偃卧，古堠更陵乘。","赖有销愁地，云中岳色层。"]},{"t":"至王家庄风沙骤作","f":"五言律诗","c":["知是山阴近，风威特地寒。","惊沙鸣索索，落叶聚团团。","铁笥腰间重，戎衣马上难。","章台冶游子，不向塞垣看。"]},{"t":"渡桑乾河","f":"五言律诗","c":["古渡是桑乾，征人晓涉寒。","鸣笳喧聚落，带剑拥材官。","霜雪经行尽，烟花出塞残。","春衣犹未寄，空倚月轮看。"]},{"t":"西行咏怀古? 其一 平城","f":"五言律诗","c":["神龙困泥淖，燕雀反见咍。","如何赤帝子，遇窘白登台。","谋臣虽幸中，鱼服几殆哉。","不见芒砀气，阴风千里来。"]},{"t":"西行咏怀古? 其二 灵丘","f":"五言律诗","c":["佳兵古所忌，奇智人不亲。","武灵何倜傥，变服诧强秦。","祸机起床笫，兴亡由一身。","惟有邯郸道，千秋狐兔尘。"]},{"t":"西行咏怀古? 其三 荆轲宅","f":"五言律诗","c":["传道荆轲里，町疃皆故丘。","陇树无西指，易水犹东流。","贤愚等共尽，尔独报君雠。","叔孙何首鼠，诡对乃封侯。"]},{"t":"悬空寺与北岳相接","f":"五言律诗","c":["隐壁金绳起，依山翠殿安。","两崖分岳色，百丈下风湍。","云狭牵衣过，天长仰面看。","石楼遥似画，归去濯金盘。"]},{"t":"大云寺在灵丘县门对太白峰","f":"五言律诗","c":["谁知沙塞里，亦自称禅栖。","雪涨晴沙合，山欹晚堞低。","多歧分客路，一宿憩招提。","才有安心处，关门又听鸡。"]},{"t":"同翟孝廉廷楠宿北岳顶","f":"五言律诗","c":["贪奇犹未已，■被宿诸峰。","入夜惊栖鹤，知君是卧龙。","投杯临瀑水，卧簟展青松。","自觉非人世，烟霞衣袖重。"]},{"t":"横翠楼元将张柔所建","f":"五言律诗","c":["高楼当绝塞，春望转氤氲。","百战全燕地，千重大漠云。","控弦无敌骑，饮羽忆将军。","老去亲戎马，悲笳向夕闻。"]},{"t":"答柏山人","f":"五言律诗","c":["邂逅夷门客，悬灯共和诗。","竹斋鸣雨歇，卧簟晓凉披。","肝胆平生是，风尘此晤宜。","夜阑浑不寐，五岳起予思。"]},{"t":"秋夜杨懋功宅同王敬美诸子集得春字","f":"五言律诗","c":["白露沾衣重，凉风送酒频。","二京多赋客，七夕会佳人。","月隐长河色，花馀小苑春。","合并良不易，留滞任缁尘。"]},{"t":"七夕别张羽王得平字","f":"五言律诗","c":["隐树风初起，临阶月乍明。","故人千里别，仙媛隔年情。","爽气侵鸾扇，轻阴下凤城。","惜无双宝剑，浊酒见生平。"]},{"t":"祝楼张封君挽诗","f":"五言律诗","c":["老莱坚隐操，襄汉接衡门。","径竹馀千亩，篱花具一尊。","气俄金马淡，星竟少微昏。","万里生刍泪，遥遥寄楚猿。"]},{"t":"遂初堂为尤茂先作","f":"五言律诗","c":["何年遗邸第，轩豁水云乡。","玉乳斜分溜，青溪曲抱堂。","虹流奎画在，日晒竹书光。","欲榜游吴楫，名园偶辟疆。"]},{"t":"别舍弟惟仁南归","f":"古风","c":["联床初引兴，?鼓忽惊心。","售玉空燕市，思家祇越吟。","微名人竞老，古调独何深。","失路唯堪念，先予到故林。"]},{"t":"送王百谷还吴","f":"五言律诗","c":["才名天亦妒，连蹇似君稀。","得病因成赋，还家忆授衣。","秋蛩吟共苦，霜月影同依。","旧识平津邸，无嗟此道非。"]},{"t":"送管建初","f":"五言律诗","c":["十上貂裘敝，谁能老汉关。","祇应岩下客，长望日边还。","猎火明秋塞，河流直故山。","身闲且归去，名姓在人间。"]},{"t":"寄吴惟善陆本仁二君","f":"五言律诗","c":["五湖秋望远，怀古意徒深。","尔逐关门吏，犹悬魏阙心。","相思如梦寐，得句动沉吟。","愁绝荆溪上，菱歌不易寻。"]},{"t":"黄定父自维扬至过访旅寓","f":"五言律诗","c":["古谊惟君独，征途访我遥。","梦来淮水月，棹发广陵潮。","脱粟期同饭，村醪为解貂。","羁心正愁绝，赖有桂丛招。"]},{"t":"送华文学之留都","f":"五言律诗","c":["载书初诣阙，沿牒复归吴。","经笥诸生学，章缝鲁国儒。","轩车荣故里，雨雪戒长途。","白虎群贤在，还来赋论都。"]},{"t":"何山人以诗过谒答之","f":"五言律诗","c":["同旅谁相问，新诗独见投。","校书非马厩，为客任貂裘。","世事凭双璧，君才老一丘。","陆云书尽好，须作鄮中游。"]},{"t":"送陈垣卿之临川文学","f":"五言律诗","c":["远宦怜乡土，名山称赏心。","松萝胜绛帐，乳洞洽青襟。","兵已销篁竹，书堪奏上林。","逍遥还引望，云气五陵深。"]},{"t":"送大庾僧游五台山","f":"五言律诗","c":["离却梅花国，西游复渡河。","风沙僧律苦，湖海梵缘多。","远聚投人住，残年避雪过。","愧予尘想在，频夜梦烟萝。"]},{"t":"送梁持伯奉使南还","f":"五言律诗","c":["房杜千秋后，诸昆复象贤。","侍晨辞魏阙，把诏下江天。","细草萦花绶，轻云翼锦鞯。","高堂称庆毕，相待日华边。"]},{"t":"送何介卿明府之任融邑","f":"五言律诗","c":["北阙方沿牒，西游复过家。","非缘寻碧柳，应喜得丹砂。","暑月才衣葛，王程正及瓜。","远方知纳款，一为报京华。"]},{"t":"端午赐扇綵楼","f":"五言律诗","c":["分直从芸省，沾恩自凤闱。","织成千缕细，裁就一轮辉。","爽气微生握，霞纹半入衣。","山龙无寸补，徒自滥云飞。"]},{"t":"献俘礼成颁赐金币","f":"五言律诗","c":["玉关初送款，汉殿正垂裳。","恩出兼金重，功微尺组长。","礼成沾绮馔，喜极举瑶觞。","王会千秋盛，无劳事朔方。"]},{"t":"白雪山房为李惟寅典禁赋","f":"五言律诗","c":["郢曲无人和，南音每自操。","青云今少达，玉树转孤高。","兵偃闲金甲，林栖接缊袍。","虽悬双鹊印，未敌饮春醪。"]},{"t":"送梁幼希之兴国文学","f":"五言律诗","c":["抱玉无嗟屈，谈经自感恩。","相门韦氏在，儒行鲁人尊。","暮雨过章水，停云近故园。","贤良纷论难，迟尔侍金门。"]},{"t":"送李少芬之新城文学","f":"五言律诗","c":["此去苏湖近，千秋见典刑。","风流看带印，青紫起谈经。","渔浦开官阁，严滩问草亭。","壮游应不负，鳌钓掣沧溟。"]},{"t":"送方进士季邻之乌程","f":"五言律诗","c":["新恩多出宰，羡尔独游吴。","官阁傍连寺，春城半入湖。","山川良具美，井邑未全苏。","谁解陈封事，翩翩待玉凫。"]},{"t":"送蒋氏兄弟还南中","f":"五言律诗","c":["北地霜风劲，南中二妙归。","云间连彩翮，堂上待斑衣。","三径蓬蒿在，千山道路微。","眷然台省客，玉树梦音徽。"]},{"t":"送何子还岭南","f":"五言律诗","c":["一雨驱残暑，长安花渐稀。","诸怜双玉羽，不共凤城飞。","客邸嗟燃桂，乡心畏捣衣。","阮家兄弟好，迟醉竹林扉。"]},{"t":"潘少承移居同里间过小饮","f":"五言律诗","c":["僦居同里闬，休假得经过。","旅客亲灯火，閒门掩薜萝。","风沙铜狄近，云气日华多。","试问王孙草，归来兴若何。"]},{"t":"司徒俞公挽歌 其一","f":"五言律诗","c":["淮甸曾专席，边庭旧倚烽。","劳深苏属国，名重郑司农。","末路收奇骏，中原失卧龙。","感恩门下客，絮酒阻扶筇。"]},{"t":"司徒俞公挽歌 其二","f":"五言律诗","c":["台中俄解印，海上托求仙。","枢筦逢明主，金貂起暮年。","途长孤剑在，恩重一身捐。","不藉麒麟画，千秋月旦传。"]},{"t":"丘民部谦之招游崇善寺得湖字","f":"五言律诗","c":["远近皆消意，清游自不孤。","尘途淹岁月，客思渺江湖。","丽句裁芳蕙，清斋供野蒲。","一龛饶水竹，端合老潜夫。"]},{"t":"至日子鸣再过","f":"五言律诗","c":["头戴小乌巾，閒游逐市尘。","到门风雪暮，剧饮性情真。","坐久因行炙，羹稀秪忆莼。","君卿解唇舌，得似好玄人。"]},{"t":"安茂卿过访因赠","f":"五言律诗","c":["蓬扉馀夕照，疲马倦寒冰。","割炙逢王粲，登龙愧李膺。","清言心已醉，文赋尔兼能。","未论青萍色，连城价转增。"]},{"t":"郑伯良携赵子昂宋克温真迹见示","f":"五言律诗","c":["翰墨前贤在，悬金不易求。","登坛称二妙，破冢阅千秋。","雅好怜昌歜，穷途哂敝裘。","椟还虽可恨，已胜夜光投。"]},{"t":"遣力还家","f":"五言律诗","c":["阿段南归去，能携尺素书。","世途同草莽，行橐易萧疏。","故国新群豕，残经老蠹鱼。","因声寄松桂，东海欲移居。"]},{"t":"闻海寇入高凉陷属邑怅然有作","f":"五言律诗","c":["军中飞檄迅，天外跕鸢遥。","料敌书生短，平时将士骄。","百城连赤羽，一岁少青苗。","纵有明珠在，无缘献圣朝。"]},{"t":"春日集思伯宅","f":"五言律诗","c":["春色燕山浅，芳菲已不禁。","雪飞犹作态，云起欲成阴。","无计投簪绂，相携就竹林。","乐游原上客，能服少年心。"]},{"t":"寒食前同童子鸣安茂卿僧普纪游郊外","f":"五言律诗","c":["懒出东郊路，因逢日稍暄。","暮云低古堞，流水避山门。","麦饭浇中野，尊醪贳近村。","因思故园梦，黄犊绕平原。"]},{"t":"郊游后同潘光禄孙上林童安二山人过朱在明宅小饮","f":"五言律诗","c":["踏遍荒郊路，归同促膝欢。","入春衣渐减，经节食犹寒。","野态衔杯出，新诗秉烛看。","双童吹小管，明月下阶残。"]},{"t":"寄胡元瑞读书真如寺","f":"五言律诗","c":["双林成独往，萝径阻同攀。","诗卷参莲座，经禅息树间。","馀寒犹拥衲，长日不开关。","若渐天池羽，脩心起雪山。"]},{"t":"真如寺访胡元瑞不遇","f":"五言律诗","c":["芳菲能几日，屡骑到閒门。","流水过经院，春风锁给园。","履声稀户外，棋局置松根。","那得逃空去，佳期独负言。"]},{"t":"望湖亭迟童安二子不至","f":"五言律诗","c":["野亭将日暮，湖水荡空回。","松坞明千塔，云山辨五台。","听莺欹客枕，摘蕊送春杯。","何处双飞鹤，翩翩不共来。"]},{"t":"下山别在明徵甫","f":"五言律诗","c":["青山不忍别，况与故人违。","水上俄生雾，松间渐落晖。","宿云君借榻，涉涧我褰衣。","莫逐桃花去，听鸡入琐闱。"]},{"t":"王亮卿将之塞上以诗见投赋答","f":"五言律诗","c":["徵书还出谷，为有故人怜。","手版趋西府，心期在北燕。","聚沙规塞外，测漏报军前。","不受风尘色，人今似鲁连。"]},{"t":"同潘少承陈忠甫过康裕卿访童子鸣","f":"五言律诗","c":["已向桐庐卧，还从燕市游。","云山携蜡屐，风雪揽貂裘。","名以新篇重，心缘古侠投。","黄花亦烂漫，为照草堂幽。"]},{"t":"送孙少府之沁水","f":"五言律诗","c":["旅邸独相亲，宁辞载酒频。","貂裘为客久，黄绶出关新。","绵上烟犹冷，西河俗旧淳。","讼庭閒坐啸，亦胜走风尘。"]},{"t":"朱在明阻冻返棹暂泊都门辄诗往讯","f":"五言律诗","c":["十丈滹沱雪，凝寒转不禁。","遥怜回客棹，犹似恋朋簪。","高枕悬归梦，层城隔醉吟。","谁知倦游者，一倍故人心。"]},{"t":"玉河泛舟别童子鸣","f":"五言律诗","c":["越客理归装，春风思北梁。","风花渡水远，菱荇入船香。","落日催停骑，清波写靓妆。","燕山青未了，相送意俱长。"]},{"t":"送吴孝父还真州","f":"五言律诗","c":["来往亦何求，风尘自薄游。","为文千赋熟，行路寸心投。","木叶淮南暮，家山白岳秋。","惊心解携易，不共五湖舟。"]},{"t":"送何孝廉南归","f":"五言律诗","c":["未献长杨赋，能高洛下名。","不嫌薪桂尽，还恋采衣轻。","江路蘼芜绿，家园橘柚荣。","东林吾旧社，回首问柴荆。"]},{"t":"王仲谐邀看芍药","f":"五言律诗","c":["姚魏元同品，开时亦未残。","动摇因翠袖，扶植借朱阑。","静影灯前落，流云席上看。","夜来风雨至，应恐越罗单。"]},{"t":"李惟寅集诸子贝叶斋予以病不赴","f":"五言律诗","c":["朱门成小筑，萧散似清溪。","水石凌棐几，香烟袭锦绨。","拈花怜昨梦，藉草得新题。","弦管惊心处，长安更向西。"]},{"t":"汝脩诸君见过","f":"五言律诗","c":["久客依人懒，西行借草堂。","物情堪俯仰，吾意在耕桑。","铃阁栖鸦近，禅镫落雁光。","酒垆应可觅，须恕阮家狂。"]},{"t":"乔启仁后园丁香花盛开迟过同赏","f":"五言律诗","c":["君是含香吏，花能作意开。","折来方玉蕊，植下向瑶台。","淡薄匀春色，飘零入酒杯。","芳菲虽可惜，不是故园梅。"]},{"t":"同邵长孺宿榆河","f":"五言律诗","c":["八千乡路远，北上转成遥。","暮雨停骖处，山陵秉节朝。","馆人羞野蕨，行灶拾枯樵。","半百多羁旅，关情独此宵。"]},{"t":"曾太常召同张羽王邵长孺小集","f":"五言律诗","c":["凉风吹日暮，曲水抱檐回。","玉醴祠官送，华筵海客陪。","卜邻伤往事，推毂冠时才。","花下频倾写，谁言触热来。"]},{"t":"王敬美以游京口诸山篇咏见示 其一","f":"五言律诗","c":["谢公山水癖，名胜往来经。","箧里芜城赋，帆前瘗鹤铭。","馀酣穷落日，远兴尽沧溟。","太息屠门客，风尘两鬓星。"]},{"t":"王敬美以游京口诸山篇咏见示 其二","f":"五言律诗","c":["故人招隐处，踪迹继焦君。","树色衔青阁，江津带白云。","饮猿垂涧接，别鹤入山闻。","不是逢王烈，谁能辨鸟文。"]},{"t":"同李阳谷袁进士暨儿琰夜集得峰字","f":"五言律诗","c":["萍水惬相逢，春杯入夜浓。","宫云流五色，城雪拥千峰。","花月留飞舄，才名得卧龙。","殷勤此携手，霞外觅行踪。"]},{"t":"送董生还海宁时欲以春秋疏上不果","f":"五言律诗","c":["草屩来燕市，缝衣返故乡。","叫阍心力尽，垂橐路途长。","著论名堪老，为园计未荒。","吾谋非不用，君自爱沧浪。"]},{"t":"荣昭德妃挽歌 其一","f":"五言律诗","c":["名冠椒风日，恩深桂殿前。","盛筐惟卒礼，辞辇宿称贤。","玉盌留朝奠，珠襦秘夜泉。","华容虽寂寞，龙綍表新阡。"]},{"t":"荣昭德妃挽歌 其二","f":"五言律诗","c":["女德辉彤管，嫔仪肃桂宫。","瑶池云自出，湘水路应穷。","宿草沾晨露，疏杨切暝风。","凤栖遗泽在，能慰九泉中。"]},{"t":"荣昭德妃挽歌 其三","f":"五言律诗","c":["素车遵广陌，丹旐转坟园。","爵秩三宫贵，威仪九御存。","苔阶凝古色，松隧锁黄昏。","秪有齐纨扇，犹馀箧笥恩。"]},{"t":"荣昭德妃挽歌 其四","f":"五言律诗","c":["祖道鸣笳引，行尘叠鼓声。","椒涂非昔日，象服俨平生。","诔册陈金印，灵輀饰翠旌。","婉仪将旧德，青史尚垂名。"]},{"t":"过田叔","f":"五言律诗","c":["促膝欢能几，还家路渐分。","我思湟水月，君倚大行云。","折简开新酝，探书得古文。","人伦吾岂敢，惟喜过黄君。"]},{"t":"人日屠田叔邀同卢西台张明府屠光禄张孝廉董山人小集","f":"五言律诗","c":["人日欣同赏，禅栖七客来。","残书留雪映，高兴待花催。","燕越星方聚，风霜雁未回。","淹留对红烛，便是百年杯。"]},{"t":"送彭稚脩还南浦","f":"五言律诗","c":["相逢满坐倾，人知卫玠清。","诸孙连帝胄，五字占时名。","草绿还家路，花伤滞客情。","词人如物色，宝剑在丰城。"]},{"t":"送田叔","f":"五言律诗","c":["暂下白云曹，趋庭有凤毛。","行多携梵夹，醉可读离骚。","铜柱风烟迥，梅梁海气高。","惊心成去住，能念旧绨袍。"]},{"t":"同梁公智过灵济道院访陈忠甫","f":"五言律诗","c":["一身经徼外，千里涉殊庭。","暂憩登山屐，閒携相鹤经。","水衣生败壁，书带拂虚棂。","但适沉冥兴，何妨笑独醒。"]},{"t":"从张羽王借郁林观碑本碑在海州","f":"五言律诗","c":["谪君馀习气，翰墨尚留心。","辍食经淮海，看碑到郁林。","登临应堕泪，行坐每沉吟。","可惜咸阳市，徒捐一字金。"]},{"t":"同莫公远张羽王梁公智过道院访陈忠甫","f":"五言律诗","c":["一探壶中隐，居然离俗尘。","石幢阴过午，花院晚留春。","侠烈心相许，萧閒兴是真。","抽簪吾已老，羡尔白云人。"]},{"t":"书陶贞白十赉文赠田叔系以小诗","f":"五言律诗","c":["知从京口渡，还礼华阳云。","紫气三茅馆，真言十赉文。","参苓谁解给，鸾鹤可为群。","岂是抽簪日，归朝万石君。"]},{"t":"同张羽王梁公智步双河庵堤上","f":"五言律诗","c":["凭眺非无地，偏寻一径幽。","风花过净院，芦荻满汀洲。","月渐中宵减，人嗟两鬓秋。","负羁将谪宦，俱厌五陵游。"]},{"t":"送歙僧大海真了游五台","f":"五言律诗","c":["结伴西游去，灵山似竺乾。","锡飞千嶂顶，灯现五峰前。","辛苦头陀行，平生佛国缘。","若论心印在，还问海南禅。"]},{"t":"吾兼亭为丘谦之赋 其一","f":"五言律诗","c":["儤直常经此，为园亦在兹。","隐偏金马籍，地即缙云司。","苑树常分色，宫莺或借枝。","秪应兰省客，来往洽襟期。"]},{"t":"吾兼亭为丘谦之赋 其二","f":"五言律诗","c":["讵意风尘里，还将一壑看。","浮沉操案牍，懒慢著衣冠。","长啸应怀古，端忧更倚阑。","耽奇吾亦尔，不是恋微官。"]},{"t":"吾兼亭为丘谦之赋 其三","f":"五言律诗","c":["密竹千茎翠，幽花一径迷。","闭门初散吏，倚树更分题。","赖是官曹简，能将物我齐。","杜陵多遣兴，长钓浣花溪。"]},{"t":"吾兼亭为丘谦之赋 其四","f":"五言律诗","c":["当代文章伯，裁诗画省中。","风流今不见，丘壑得无同。","翰墨虚留壁，兰苕失旧丛。","怜才惟郢客，洒泪此亭中。"]},{"t":"送梁公智移官吉州 其一","f":"五言律诗","c":["怀禄非吾愿，移官肯叹嗟。","鹭洲迎解佩，螺水忆乘槎。","梦寐销丹地，行藏问酒家。","拿音一回首，红发满溪花。"]},{"t":"送梁公智移官吉州 其二","f":"五言律诗","c":["握手平生好，青云几客途。","马空疲皂枥，人渐老屠沽。","词赋名何益，弦歌计总芜。","飘零壮心在，龙剑未全孤。"]},{"t":"应妙寺即白塔寺僧慧乾居之","f":"五言律诗","c":["杖钵携来久，香灯静院偏。","栽花成野径，接竹引春泉。","支遁逍遥论，天台止观禅。","坐来忘妙说，塔影挂窗前。"]},{"t":"护国寺以居僧之使远国者中有赵文敏碑","f":"五言律诗","c":["汉家勤绝国，檀施表奇观。","梵品从天竺，真僧是法兰。","护碑龙首缺，巢栋燕泥乾。","不见金缯出，关门用一丸。"]},{"t":"双塔寺兴隆寺别院有金党元英碑今废为内教场","f":"五言律诗","c":["长安开甲第，舍卫接王城。","古佛旃檀阁，将军细柳营。","灯残留说偈，碑半减题名。","此是红尘地，轮蹄终日行。"]},{"t":"能仁寺旧藏有桦皮梵经字甚精凿","f":"五言律诗","c":["游人方舍俗，释子复开关。","白拂支颐久，清言酌茗閒。","书难窥豹管，墨是出鸡山。","若杜毗邪口，谁传出世间。"]},{"t":"洪庆寺马尾松","f":"五言律诗","c":["亭亭垂翠盖，趺坐一僧来。","梁栋非吾事，青黄是木灾。","枝连拂衣石，凉荫译经台。","樗散拚人弃，摩挲愧汝才。"]},{"t":"法弘寺建新城时关地有僧涅槃龛中其形如生即寺僧也","f":"五言律诗","c":["浩劫知何代，长林过客迷。","不知今壁垒，犹是昔招提。","定里人长寂，花间鸟自啼。","醉来惟荷锸，岐路任东西。"]},{"t":"天宁寺有舍利塔僧道衍曾隐此","f":"五言律诗","c":["青青千柏林，隋唐留至今。","佛光时隐现，塔影半晴阴。","草细经游鹿，庭閒演戏禽。","机心刊落久，那复异人寻。"]},{"t":"发长清县","f":"五言律诗","c":["丹梯初引兴，愁绝赴前期。","未蜡登山屐，先题望岳诗。","停车松日下，解带麦风吹。","万里游今始，抽簪恨苦迟。"]},{"t":"苏公亭","f":"五言律诗","c":["谋生本业屦，岂意学逃名。","千金兼束帛，无乃故人情。","凿湖从此遁，蓬门空自扃。","潮中有兰芷，俎豆共芳馨。"]},{"t":"游顾玄言二泉山亭二首 其一","f":"五言律诗","c":["尘土梦初醒，招寻得此亭。","泉分双井练，楼入四山青。","倚树方成偈，烹茶旧续经。","异时鸡黍约，风竹细来听。"]},{"t":"游顾玄言二泉山亭二首 其二","f":"五言律诗","c":["谁解捐尘网，烟霞共一欣。","引杯承竹露，展簟接山云。","丘壑应忘我，鱼凫正属君。","扁舟从此去，渔钓幸相闻。"]},{"t":"朱明洞","f":"五言律诗","c":["乘蹻入清都，居然景气殊。","泉声迷远近，松籁荅虚无。","神室留丹火，仙家閟玉壶。","冲腾已迟暮，物色待潜夫。"]},{"t":"青霞谷","f":"五言律诗","c":["霞外昔沉冥，松篁尚匝青。","桥边逢洗钵，石上记翻经。","一壑专名胜，千秋更典刑。","偶来忘絮酒，长揖谢山灵。"]},{"t":"黄龙洞","f":"五言律诗","c":["秀甲朱明外，何年辟草莱。","悬萝千磴暝，飞瀑二楼开。","采药应迷屐，翻经尚有台。","相期看日出，云气在蓬莱。"]},{"t":"飞云顶","f":"五言律诗","c":["飞步上㠝岏，星辰渐可扪。","一山浮海至，五岭此峰尊。","元气回阴洞，丹霞辟妙门。","从来尘劫外，别自有乾坤。"]},{"t":"答邹方伯","f":"五言律诗","c":["共赋燕台月，佳期得重寻。","剧谈当世事，推毂昔贤心。","画省开文苑，青衿列道林。","时艰思共济，吾待拂朝簪。"]},{"t":"答孙观察","f":"五言律诗","c":["入幕吾何敢，寒宵重有期。","披云占藻思，零雨见新诗。","弭棹沧江外，怀人落日时。","归鸿如报客，春在万年枝。"]},{"t":"冬日梅华堂开社招君肃寅仲公补少仲仲登公绍开先诸子","f":"五言律诗","c":["北郭曾招隐，深留水石踪。","蓬蒿怜二仲，文史入三冬。","霜径初封橘，寒畦晚摘菘。","故山吾不负，琴酒许相从。"]},{"t":"潘子迁过梅华堂待月梁士哲继至","f":"五言律诗","c":["三径蓬蒿在，风流二子过。","狂来忘我懒，坐久觉情多。","竹下黄花酒，风前白雪歌。","徘徊还秉烛，明月待羊何。"]},{"t":"朱贞吉孔阳昆玉以予校刻复古编有诗见讯奉答","f":"五言律诗","c":["天禄归来日，谁知四壁空。","技应怜刻鹄，文不悔雕虫。","副墨名山在，馀生雅尚同。","何时捉谈麈，披写对兴公。"]},{"t":"万里乘风卷送友人北上","f":"五言律诗","c":["握手念将别，清尊尚未空。","离心悬岭树，客路值秋风。","鹏翮搏南海，鸿仪会泽宫。","甘泉多侍从，谁为荐扬雄。"]},{"t":"寿黄母六十一初度","f":"五言律诗","c":["喜际嘉平月，奇龄六秩开。","萱花凌绮树，慈竹映春杯。","绛节排云下，金书附鹤回。","浔阳正清浅，红日莫相催。"]},{"t":"潘子携酒同欧氏诸子过清泉山中出吴笺索余拙书因留夜坐","f":"五言律诗","c":["通家称孔李，联骑问幽居。","性洽高阳酒，名惭大令书。","行吟随一鹤，风雨待三鱼。","十载尘缨解，烟霞礼法疏。"]},{"t":"澹台子羽墓","f":"五言律诗","c":["临河闻返驾，高第乃南浮。","行径无芳躅，松楸馀故丘。","山川良不改，吾道日悠悠。","谁怜卑薄地，千古有麟游。"]},{"t":"友人惠菊夜至","f":"五言律诗","c":["柴桑虽久卧，三径未曾栽。","海上封书至，篱根带雨来。","繁霜吹短鬓，红烬落苍苔。","纵是相逢晚，犹胜二月开。"]},{"t":"七夕同陈任夫高正甫麦仲张林开先舍弟惟仁侄璘集清居得燕字","f":"五言律诗","c":["阁道双星过，虚堂暮雨悬。","清歌闻激楚，宝剑忆游燕。","雁下沉秋色，萤流入野烟。","词人方接席，应不恨华年。"]},{"t":"春草堂为巍甫作","f":"五言律诗","c":["谢公携屐处，坐爱一池幽。","朱邸依兰阰，青山入蕙楼。","云容开浩渺，客思满汀洲。","莫叹群芳歇，王孙正薄游。"]},{"t":"尚雅斋为佳甫作","f":"五言律诗","c":["试问通侯印，何如乐志园。","传家为竹素，入室有兰荪。","玉度波千顷，清吟月满轩。","款门无恶客，芳醴正盈尊。"]},{"t":"同丁计部诸子集王鸿胪山斋怀五岳之胜得高字","f":"五言律诗","c":["名山谁历遍，挥麈亦称豪。","岩壑驱词古，风云入望高。","金光遥可掇，藜杖肯辞劳。","猿鹤应相笑，驰烟待尔曹。"]},{"t":"顾鸿胪诸子邀同丁计部游玉河堤上得明字","f":"五言律诗","c":["久作尘中客，閒从堤上行。","轻风花外度，残照雨边明。","趋事联三省，游踪愧二京。","当歌聊驻马，轻别若为情。"]},{"t":"重阳后过沈纯甫同艾蔡二曹长小饮","f":"五言律诗","c":["偶尔襟期合，相携坐竹根。","霜华犹满径，风叶漫开尊。","故国飞鸿断，长途老马存。","非君慰寥寂，谁解扫行园。"]},{"t":"送杨参军","f":"五言律诗","c":["谢家传玉树，倾盖即依然。","谏草犹存笥，琴尊半在船。","莲花分幕静，杨柳挂帆偏。","若是过牛渚，长歌夜月前。"]},{"t":"送黄孔昭","f":"五言律诗","c":["千山初落木，归客兴偏新。","药饵经秋减，萝衣似旧贫。","侯门无左席，渔艇有閒身。","到处堪栖泊，原非失路人。"]},{"t":"答蔡伯华刑部","f":"五言律诗","c":["衡门方昼掩，特枉法曹过。","良晤寻鸡黍，秋风入薜萝。","名山思裹足，烟雨忆披蓑。","不为沉冥久，逢君白石歌。"]},{"t":"同姚伯子黄定甫邵长孺李季常游甘露寺","f":"五言律诗","c":["高阁生远兴，飘然在五湖。","暮云低不散，远树近看无。","说偈参莲座，游踪渺玉壶。","长天一回首，唯有月明孤。"]},{"t":"题迟贤亭靳仙笔迹","f":"五言律诗","c":["白云飞不去，掷笔此亭幽。","星宿垂芒在，虫鱼汗简留。","识奇空白首，招手即丹丘。","欲展青毡卧，荒生霹雳愁。"]},{"t":"过顾叔潜得题字","f":"五言律诗","c":["幽寻不在远，吏隐占青溪。","乡梦衔杯失，新诗摘叶题。","萤疏经雨乱，花好傍人低。","日出铜街静，犹能散马蹄。"]},{"t":"送胡山人","f":"五言律诗","c":["悬壶谁解识，负笈且归休。","招手丹丘近，摇心白岳秋。","虫鱼窥秘简，虹月傍行舟。","回首风沙地，逢人笑黑裘。"]},{"t":"咏匏冠","f":"五言律诗","c":["苦蒂才堪摘，良工巧斲成。","不知蝉翼贵，宁让竹皮轻。","束发禁霜冷，穿花滴露清。","终焉惭戴鹖，还有著书名。"]},{"t":"送唐惟良之广陵二首 其一","f":"五言律诗","c":["邗水遥通海，乘槎复此过。","儿童骑竹在，盐铁算缗多。","市估帆樯乱，人烟岛屿和。","徒劳君莫叹，留兴在沧波。"]},{"t":"送唐惟良之广陵二首 其二","f":"五言律诗","c":["才名馀画省，吏隐得沧洲。","汀草生春色，渔歌唤客愁。","疏灯京口渡，孤刹大江流。","试问观涛处，词人几度游。"]},{"t":"送蔡伯华之闽中","f":"五言律诗","c":["出处几人异，非缘薄省郎。","交情异贫贱，世事有沧桑。","煮海窥盐策，题诗出射堂。","流年堪自惜，何用叹浮湘。"]},{"t":"过天宁寺僧宝檀方丈 其一","f":"五言律诗","c":["曾有黄金地，谁为苦行僧。","仗经行路远，采药入云层。","一食伊蒲饭，长明石枕灯。","不依禅宿去，头白已无能。"]},{"t":"过天宁寺僧宝檀方丈 其二","f":"五言律诗","c":["野外芳华早，何妨策杖寻。","草深垂井口，碑卧古坛阴。","高坐惟尊足，清斋尚摄心。","给园留赏处，还似阮家林。"]},{"t":"送黄清甫偕顾舍人游滇中","f":"五言律诗","c":["旧好如禽庆，名山得共陪。","洱河神禹导，路箐爨王开。","冠带名家子，登临济胜才。","关城雄剑阁，应待勒铭回。"]},{"t":"闻故园草阁火","f":"五言律诗","c":["架上馀千轴，俱随绿燄飞。","平生惟蜡屐，旧物秪牛衣。","信是冥怀待，谁言损读非。","啸歌聊复尔，北叟可同归。"]},{"t":"同顾鸿胪兄弟过王鸿胪宅永上人在焉","f":"五言律诗","c":["委巷多车马，还因典客名。","乡心灯下尽，谈麈坐中倾。","径草抽新雨，风丝漾晚晴。","归舟应可问，春浪此时平。"]},{"t":"郑伯良邀同诸公登万佛阁","f":"五言律诗","c":["日送莺花去，风雩兴可乘。","尘心攀阁远，野兴入林增。","龙树栖孤影，蜂房飐万灯。","若无光禄酒，春思杳难凭。"]},{"t":"市中得旧琴囊而予无琴也","f":"五言律诗","c":["锦样已模糊，何时混世沽。","秪馀空橐在，多半古音无。","携可缄诗草，闲将覆局图。","勿言无所用，五石汎江湖。"]},{"t":"过范子宣观王生临帖","f":"五言律诗","c":["用意颇精勤，毫芒细细分。","春丝抽独茧，惊电出重云。","携我青藜杖，书君白练裙。","长安应纸贵，馀子但纷纭。"]},{"t":"送陈从训还丹徒","f":"五言律诗","c":["河朔衔杯日，蓬莱奏伎游。","寸心酬国士，片语逊名流。","衣湿离筵雨，帆开驿路秋。","南云正翘首，一雁下芦洲。"]},{"t":"寄陆无从","f":"五言律诗","c":["不为忧生产，谁能废啸歌。","谈经须历下，贷粟少监河。","秋雨生黄叶，寒江拥白波。","不知蓬室底，玄草近如何。"]},{"t":"寄李季常","f":"五言律诗","c":["才名空落拓，诗句转清新。","推毂无先辈，论交见古人。","思君淮水月，携手蜀山春。","不是逢沮溺，依然又问津。"]},{"t":"雨中奉讯唐惟良","f":"五言律诗","c":["带印无多日，前期远见寻。","摇心双阙下，理棹五湖阴。","客邸嗟燃桂，朝廷有赐金。","萧条黄叶里，休忆白头吟。"]},{"t":"同左辖郭公过广济寺","f":"五言律诗","c":["左辖中朝贵，空门物外游。","白云邀入寺，红树引登楼。","积雨逢新霁，乡心值早秋。","相酬无丽句，谁解识汤休。"]},{"t":"郭方伯应宿至自南中止广惠寺同刘观察仲脩携酒奉讯 其一","f":"五言律诗","c":["未觉双峰远，方营一日閒。","旃檀入古寺，雷雨过空山。","苔滑停车处，风生捉麈间。","禅房宁久住，人望在朝班。"]},{"t":"郭方伯应宿至自南中止广惠寺同刘观察仲脩携酒奉讯 其二","f":"五言律诗","c":["南中无信使，竹下有行踪。","岂谓天涯远，还于佛国逢。","解衣停暮雨，闻梵报疏钟。","世事悠然里，寒暄已自慵。"]},{"t":"刘观察园亭送唐惟良还扬州同欧桢伯作","f":"五言律诗","c":["省署昔攀援，衡茅更接连。","藤萝犹迸月，池沼欲分天。","作赋人投楚，登台价在燕。","一将摇落思，销尽绿尊前。"]},{"t":"题张山人子嘿孝思卷","f":"五言律诗","c":["已向沧洲老，还从燕市游。","行藏丹检在，风月锦囊收。","搦管云生纸，披衣雪满裘。","江湖千里梦，犹忆到松楸。"]},{"t":"赠医士姚允升","f":"五言律诗","c":["蚤年耽内学，一室事医王。","蓟子传仙术，桐君与药方。","终朝常扣齿，一榻自焚香。","若访丹砂去，双凫问草堂。"]},{"t":"大司马东沙张公挽诗 其一","f":"五言律诗","c":["故老三朝尽，芳名一代尊。","麒麟身未画，丘壑道终存。","赤水馀篇翰，丹霄投梦魂。","千秋文冢在，荣耀竟谁伦。"]},{"t":"大司马东沙张公挽诗 其二","f":"五言律诗","c":["典午馀勋伐，中朝尚典刑。","书能穷左史，文竟薄玄经。","紫气终难翳，沧波逝不停。","疏才惭许与，头白尚飘零。"]},{"t":"读书楼为曾阳白先生赋","f":"五言律诗","c":["风月昔登临，丹梯尚可寻。","青藜天禄阁，白雪郢中吟。","几席岚霏湿，轩窗露气深。","琅然云水外，犹是凤鸾音。"]},{"t":"锦标轩","f":"五言律诗","c":["锦帜中流得，泥金上国来。","衣冠通两世，星象接三台。","题柱荆山积，雕楹汉水开。","桓荣稽古力，千载复论才。"]},{"t":"西圃馀清","f":"五言律诗","c":["野望通云上，衡门在水西。","骚人搴薜荔，游客唱铜鞮。","橘树千林遍，桃花隔岸迷。","凤毛霄汉在，垂钓任清溪。"]},{"t":"哭徐子与六首 其一","f":"五言律诗","c":["岳牧才名大，中朝礼数优。","天文垂左辖，风谊起南州。","羽卫森开府，江山自倚楼。","玺书虽未下，为政已风流。"]},{"t":"哭徐子与六首 其二","f":"五言律诗","c":["词场应冠绝，心匠亦兼能。","崛起无前辈，雄飞值中兴。","浮沉玄理胜，时俗吏才称。","往事穹碑在，千秋下马陵。"]},{"t":"哭徐子与六首 其三","f":"五言律诗","c":["苍苍不可问，叹逝每如斯。","岂意长安酒，为君永诀时。","鸿都今绝笔，大雅久无诗。","不独风流尽，文章属数奇。"]},{"t":"哭徐子与六首 其四","f":"五言律诗","c":["无书才几月，委蜕得非真。","道丧应歌凤，吾衰更泣麟。","簿书聊偶世，时命仅同人。","醉墨纵横处，星沉霅水滨。"]},{"t":"哭徐子与六首 其五","f":"五言律诗","c":["讼牒常移少，高斋日扫除。","故人无政府，门客满公车。","酒德应堪颂，官箴亦未疏。","汝南多赋客，犹是大风馀。"]},{"t":"哭徐子与六首 其六","f":"五言律诗","c":["中原称五子，附骥亦纷纷。","国色应殊众，清言独见君。","不逢非汉谶，垂老见雄文。","凄切邻人笛，长安醉后闻。"]},{"t":"林计部德基同丘使君谦之陈山人汝信自通州泛舟送予至潞河","f":"五言律诗","c":["赖是官曹简，何妨胜事偏。","金章参野褐，青黛倚楼船。","宿鹭惊人起，残虹傍雨悬。","空江回骑吏，留兴绿尊前。"]},{"t":"别丘谦之以苏晋图奉赠","f":"五言律诗","c":["岂谓逃禅者，临岐欲别难。","昔联东省玉，今佩楚江兰。","落日催回舸，春风岸客冠。","披图见颜色，何异屋梁看。"]},{"t":"赠顾舍人","f":"五言律诗","c":["东阁多奇士，文章未陆沉。","诗言自匡鼎，家学得刘歆。","出入清华地，翻飞翰墨林。","交情元竹下，况乃接朝簪。"]},{"t":"鴳适斋为朱张水文学赋","f":"五言律诗","c":["一室蓬蒿下，清斋似杜机。","但求栖息稳，不恨稻粱微。","喜客开山笥，乘閒款竹扉。","山川一何广，黄鹄待翻飞。"]},{"t":"同谦之丘使君自天宁寺骑至西湖上","f":"五言律诗","c":["欲送残春去，长堤日已曛。","村舂隔水远，浦树到湖分。","惜别贪携手，行吟独共君。","莫惊沙上鸟，飞去各青云。"]},{"t":"龙潭","f":"五言律诗","c":["何年龙已去，野色澹荒陂。","元气回深洞，阴风出古祠。","探珠寻赤水，沉璧问清时。","牧竖犹回首，千灵访具茨。"]},{"t":"宿瑗上人房","f":"五言律诗","c":["久客应难寐，中宵独据床。","心无蕉鹿竞，梦已路途长。","曙色斋钟动，行厨野蔌香。","更衣问前路，惆怅别云房。"]},{"t":"功德寺牡丹","f":"五言律诗","c":["一径交深竹，千丛暗野堂。","碧疑天女唾，花是佛王香。","绝艳休相妒，佳期不可忘。","飘零一杯酒，长啸望西房。"]},{"t":"华岩洞有耶律楚材故桓夏公石刻","f":"五言律诗","c":["深壑因谁造，挥斤亦有神。","江山留王气，题咏待词人。","泉作窗间雨，苔生石上尘。","碧纱笼底墨，萧索竟千春。"]},{"t":"望湖亭","f":"五言律诗","c":["层崖出天半，应接颇纷纭。","山合溟濛雨，湖通来去云。","春风吹桂棹，野日散鸥群。","一片江南色，吟思越鄂君。"]},{"t":"酌玉亭上","f":"五言律诗","c":["登山方改屐，把酒爱临流。","龙去还成雨，风鸣并作秋。","开奁鸿照影，弭盖凤经游。","绝胜频来往，毵毵笑白头。"]},{"t":"同谦之午憩金口寺石榻上","f":"五言律诗","c":["济胜心无己，看山日暂停。","梦回云屋冷，衣藉石床扃。","佛境看如幻，尘途笑独醒。","僧房无所供，亦自遣沉冥。"]},{"t":"慰慈上人坠马","f":"五言律诗","c":["经禅不出户，山色举头新。","绝磴应妨马，危途转畏人。","尘劳余裹足，电路尔观身。","莫更生嗔恼，西游本宿因。"]},{"t":"丘谦之下碧云寺予往香山两作速归","f":"五言律诗","c":["出谷应疑早，看山欲去迟。","日斜人影独，林薄鸟声悲。","咫尺犹相去，逢迎重有期。","不嫌骑马倦，难和碧云诗。"]},{"t":"同邬汝翼黄清甫陈崇训汪公干李季常过焦山访郭次甫","f":"五言律诗","c":["钓鳌生远兴，歌凤上高台。","海气风吹断，江流树引回。","莓苔行径滑，钟梵寺门开。","如此佳山水，生涯几度来。"]},{"t":"桐庐道中寄谢侍御 其一","f":"五言律诗","c":["有美吴山水，星轺宠命新。","涛声驱海曲，风采肃朝绅。","入社推高足，追班沗近臣。","未酬虚左席，长愧报恩身。"]},{"t":"桐庐道中寄谢侍御 其二","f":"五言律诗","c":["剑气凌东越，奎文映紫垣。","人伦开藻鉴，礼数起龙门。","白发存知己，丹心奉至尊。","汉庭如物色，虚薄讵须论。"]},{"t":"答邻止少侯","f":"五言律诗","c":["高步谁能似，名驹本帝家。","向人操白雪，投迹寄青霞。","宾榻频开醴，山窗屡试茶。","清言疲梦想，丛桂又开花。"]},{"t":"与梁少仲林开先汲古亭夜坐","f":"五言律诗","c":["归来无所适，剩有草玄亭。","岩溜千丝滴，云萝四壁青。","燃灯听佛偈，酌酒试茶经。","若论浮生理，惟知醉与醒。"]},{"t":"少仲开先过宿山楼","f":"五言律诗","c":["数过争悬榻，乘閒就隐居。","竹风披卧簟，松火照山厨。","远梦觉幽鸟，清神把道书。","长歌云水外，豪气不曾除。"]},{"t":"石羊馆为郭学宪赋","f":"五言律诗","c":["一室类安禅，铜梁策骑旋。","试看持节日，犹似下帷年。","花气迷春岛，藤阴覆玉泉。","清吟不觉夜，月在石桥边。"]},{"t":"归田杂咏十二首 其一","f":"五言律诗","c":["一雨淹晨暮，閒居似避喧。","邻人难假盖，樵客少过门。","脱粟应妨罄，残书懒自翻。","本无经济术，藏拙在乾坤。"]},{"t":"归田杂咏十二首 其二","f":"五言律诗","c":["近卜城西地，新畬渐可耕。","耰锄课童仆，丰俭付阴晴。","白水分畦映，青烟冒垄平。","萧然茅屋底，无力谢生成。"]},{"t":"归田杂咏十二首 其三","f":"五言律诗","c":["一丘堪偃卧，暇日掩柴扉。","山果垂藤熟，林莺接翅飞。","春风难再得，世事况多违。","但坐南窗下，休论昨日非。"]},{"t":"归田杂咏十二首 其四","f":"五言律诗","c":["颇怪频年事，江湖屡滞游。","王程妨野寺，身世落渔舟。","徒费千金伎，空馀一敝裘。","素丝虽可叹，知足亦何忧。"]},{"t":"归田杂咏十二首 其五","f":"五言律诗","c":["鹏阁曾三入，龙门幸一登。","散才当艺苑，妙语属山僧。","交态看贫贱，荣途有爱憎。","机心今已矣，稳卧玉山层。"]},{"t":"归田杂咏十二首 其六","f":"五言律诗","c":["家传馀万卷，世故半凋零。","虽识数行墨，终销两鬓青。","人多矜敝帚，世复笑玄经。","但饮尊中酒，胜于案上萤。"]},{"t":"归田杂咏十二首 其七","f":"五言律诗","c":["久欲游衡岳，轻舟信所如。","川程限楚越，生计系樵渔。","未种龙洲橘，先驰汶岭书。","四愁无处写，胜事恐成虚。"]},{"t":"归田杂咏十二首 其八","f":"五言律诗","c":["浮丘吾郭近，策杖屡经过。","神室无留火，沧溟有逝波。","灵踪天亦秘，遐举事如何。","乘屩非吾意，空悲去日多。"]},{"t":"归田杂咏十二首 其九","f":"五言律诗","c":["岂谓归田拙，幽居事足娱。","虫鱼诠古刻，山海咏新图。","名已落朝藉，身当隐市沽。","虽无乡里识，亦懒著潜夫。"]},{"t":"归田杂咏十二首 其十","f":"五言律诗","c":["苦忆平生友，怜予颇好奇。","能供光禄酒，常和法曹诗。","宦拙骑官马，朝回补竹篱。","风尘关塞黑，魂梦故来迟。"]},{"t":"归田杂咏十二首 其十一","f":"五言律诗","c":["短衣殊入宋，凭轼似经蒲。","宦辙十年有，乡书累月无。","推毂庙廊在，归山酒伴孤。","白头惟强饭，亦足慰长途。"]},{"t":"归田杂咏十二首 其十二","f":"五言律诗","c":["自卜三间隐，宁多二仲贤。","王家甥舅易，何氏弟兄禅。","琴酒中年辍，江湖远梦悬。","浮云尔何物，不似渌尊前。"]},{"t":"西庄迟梁少仲林开先过访 其一","f":"五言律诗","c":["林霏将欲敛，瓜地正堪耘。","隔竹频呼酒，开轩一待君。","拿音出浦远，人影过桥分。","莫谓馀西日，临堂见碧云。"]},{"t":"西庄迟梁少仲林开先过访 其二","f":"五言律诗","c":["二妙联镳至，尘襟顿觉披。","山风吹薜荔，野日澹茅茨。","浮白君能醉，还丹我较迟。","莫论风共雨，俱是入林时。"]},{"t":"梁少仲林开先招游西池泛舟 其一","f":"五言律诗","c":["岁月欺人得，乘閒只浪游。","看花迷浦口，回棹泊沙头。","细雨孤村暝，凉风野树秋。","无心论去住，云水共悠悠。"]},{"t":"梁少仲林开先招游西池泛舟 其二","f":"五言律诗","c":["近出循西水，中流具画船。","清游藉朋好，适兴任江天。","鲙落金盘细，杯行野割鲜。","当垆怜少妇，不解惜华年。"]},{"t":"同赵太史游罗浮宿冲虚观","f":"五言律诗","c":["寒宵无击柝，把剑起鸡鸣。","紫阁浮生梦，沧洲独客情。","风回瑶室响，云去铁桥平。","何处参差发，乘鸾朝玉京。"]}]};